use crate::synth::SynthSpec;
use serde::{Deserialize, Serialize};
use std::path::{Path, PathBuf};

#[derive(Clone, Debug)]
pub enum TrackSource {
    Demo(SynthSpec),
    File(PathBuf),
}

#[derive(Clone, Debug)]
pub struct Track {
    pub id: String,
    pub title: String,
    pub artist: String,
    pub album: String,
    pub genre: String,
    pub duration: f32,
    pub source: TrackSource,
    pub hue: f32,
}

#[derive(Clone, Debug)]
pub struct AlbumInfo {
    pub name: String,
    pub artist: String,
    pub hue: f32,
    pub tracks: Vec<String>,
    pub local: bool,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct LocalTrack {
    pub path: PathBuf,
    pub title: String,
    pub artist: String,
    pub album: String,
    pub duration: f32,
}

#[derive(Clone, Debug, Serialize, Deserialize, Default)]
pub struct Playlist {
    pub name: String,
    #[serde(default)]
    pub description: String,
    pub tracks: Vec<String>,
    pub hue: f32,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(default)]
pub struct UserData {
    pub liked: Vec<String>,
    pub playlists: Vec<Playlist>,
    pub folders: Vec<PathBuf>,
    pub local: Vec<LocalTrack>,
    pub recent: Vec<String>,
    pub volume: f32,
    pub shuffle: bool,
}

impl Default for UserData {
    fn default() -> Self {
        Self {
            liked: vec![],
            playlists: vec![],
            folders: vec![],
            local: vec![],
            recent: vec![],
            volume: 0.7,
            shuffle: false,
        }
    }
}

impl UserData {
    fn path(dir: &Path, user: &str) -> PathBuf {
        dir.join("users").join(format!("{user}.json"))
    }
    pub fn load(dir: &Path, user: &str) -> Self {
        std::fs::read_to_string(Self::path(dir, user))
            .ok()
            .and_then(|s| serde_json::from_str(&s).ok())
            .unwrap_or_default()
    }
    pub fn save(&self, dir: &Path, user: &str) {
        let p = Self::path(dir, user);
        if let Some(parent) = p.parent() {
            let _ = std::fs::create_dir_all(parent);
        }
        if let Ok(s) = serde_json::to_string_pretty(self) {
            let _ = std::fs::write(p, s);
        }
    }
