pub const ACCENT2: Color32 = Color32::from_rgb(167, 139, 250);

pub fn cr(n: u8) -> CornerRadius {
    CornerRadius::same(n)
}

pub fn bold(size: f32) -> FontId {
    FontId::new(size, FontFamily::Name("bold".into()))
