use crate::accounts::{member_since, Account, AccountStore};
use crate::library::{self, AlbumInfo, LocalTrack, Playlist, Track, UserData};
use crate::player::Player;
use crate::theme::*;
use eframe::egui::{
    self, pos2, vec2, Align2, Color32, Context, FontId, Frame, Id, Key, Margin, Painter, Pos2, Rect, RichText, ScrollArea,
    Sense, Shape, Stroke, TextEdit, Ui, UiBuilder,
};
use std::collections::{HashMap, VecDeque};
use std::path::PathBuf;
use std::sync::mpsc::{channel, Receiver};

#[derive(Clone, Debug, PartialEq)]
pub enum View {
    Home,
    Search,
    Library,
    Liked,
    Playlist(usize),
    Album(String),
    Mix(usize),
    Local,
    Queue,
    Account,
}

#[derive(Clone, Copy, PartialEq)]
enum AuthTab {
    SignIn,
    SignUp,
}

#[derive(Clone, Copy, PartialEq)]
enum Repeat {
    Off,
    All,
    One,
}

#[derive(Clone, Copy, PartialEq)]
enum LibFilter {
    All,
    Playlists,
    Albums,
    Local,
}

#[derive(Clone)]
enum Art {
    Cover(f32, String),
    Liked,
    Local,
}

#[derive(Clone, Copy, PartialEq)]
enum TableKind {
    Plain,
    Playlist(usize),
}

struct Mix {
    name: String,
    desc: String,
    hue: f32,
    ids: Vec<String>,
}

struct CardItem {
    title: String,
    subtitle: String,
    art: Art,
    view: View,
}

enum Action {
    PlayList(Vec<String>, usize),
    TogglePlay,
    Next,
    Prev,
    Seek(f32),
    Volume(f32),
    ToggleLike(String),
    AddToPlaylist(String, usize),
    NewPlaylist(Option<String>),
    RemoveFromPlaylist(usize, usize),
    DeletePlaylist(usize),
    EditPlaylist(usize),
    Queue(String),
    Go(View),
    Back,
    Forward,
    ToggleShuffle,
    CycleRepeat,
    AddFolder,
    RemoveFolder(usize),
    SignOut,
    Toast(String),
}

pub struct WaveletApp {
    data_dir: PathBuf,
    ephemeral: bool,
    accounts: AccountStore,
    user: Option<Account>,
    data: UserData,

    auth_tab: AuthTab,
    f_user: String,
    f_display: String,
    f_pass: String,
    f_pass2: String,
    f_remember: bool,
    auth_error: Option<String>,

    tracks: Vec<Track>,
    index: HashMap<String, usize>,
    albums: Vec<AlbumInfo>,
    mixes: Vec<Mix>,

    view: View,
    back: Vec<View>,
    forward: Vec<View>,
    search: String,
    lib_filter: LibFilter,

    player: Player,
    current: Option<String>,
    context: Vec<String>,
    ctx_pos: usize,
    queue: VecDeque<String>,
    shuffle: bool,
    repeat: Repeat,
    playing: bool,
    seek_drag: Option<f32>,

    pending: Vec<Action>,
    toast: Option<(String, f64)>,
    scan_rx: Option<Receiver<(PathBuf, Vec<LocalTrack>)>>,
    editing: Option<(usize, String, String)>,
    acct_name: String,
    acct_old: String,
    acct_new: String,
    acct_msg: Option<(String, bool)>,
    confirm_delete: bool,
    focus_search: bool,

    screenshot: Option<PathBuf>,
    frames: u32,
    shot_requested: bool,
}

impl WaveletApp {
    pub fn new(screenshot: Option<PathBuf>) -> Self {
        let data_dir = dirs::data_dir().unwrap_or_else(|| PathBuf::from(".")).join("Wavelet");
        let ephemeral = screenshot.is_some();
        let accounts = if ephemeral { AccountStore::default() } else { AccountStore::load(&data_dir) };
        let mut app = Self {
            data_dir,
            ephemeral,
            accounts,
            user: None,
            data: UserData::default(),
            auth_tab: AuthTab::SignIn,
            f_user: String::new(),
            f_display: String::new(),
            f_pass: String::new(),
            f_pass2: String::new(),
            f_remember: true,
            auth_error: None,
            tracks: vec![],
            index: HashMap::new(),
            albums: vec![],
            mixes: vec![],
            view: View::Home,
            back: vec![],
            forward: vec![],
            search: String::new(),
            lib_filter: LibFilter::All,
            player: Player::new(!ephemeral),
            current: None,
            context: vec![],
            ctx_pos: 0,
            queue: VecDeque::new(),
            shuffle: false,
            repeat: Repeat::Off,
            playing: false,
            seek_drag: None,
            pending: vec![],
            toast: None,
            scan_rx: None,
            editing: None,
            acct_name: String::new(),
            acct_old: String::new(),
            acct_new: String::new(),
            acct_msg: None,
            confirm_delete: false,
            focus_search: false,
            screenshot,
            frames: 0,
            shot_requested: false,
        };
        app.rebuild_index();
        if app.ephemeral {
            app.demo_session();
        } else if let Some(u) = app.accounts.remembered.clone() {
            if let Some(acc) = app.accounts.find(&u).cloned() {
                app.enter(acc);
            }
        }
        if app.accounts.accounts.is_empty() {
            app.auth_tab = AuthTab::SignUp;
        }
        app
    }

    // ---------------------------------------------------------------- data

    fn rebuild_index(&mut self) {
        let mut tracks = library::demo_catalog();
        for l in &self.data.local {
            tracks.push(library::local_to_track(l));
        }
        self.index = tracks.iter().enumerate().map(|(i, t)| (t.id.clone(), i)).collect();
        let mut albums: Vec<AlbumInfo> = vec![];
        for t in &tracks {
            let local = matches!(t.source, library::TrackSource::File(_));
            if let Some(a) = albums.iter_mut().find(|a| a.name == t.album && a.local == local) {
                a.tracks.push(t.id.clone());
            } else {
                albums.push(AlbumInfo { name: t.album.clone(), artist: t.artist.clone(), hue: t.hue, tracks: vec![t.id.clone()], local });
            }
        }
        let defs: [(&str, &[&str], f32); 3] = [
            ("Daily Mix 1", &["Electronic", "Dance"], 0.8),
            ("Daily Mix 2", &["Chill", "Lo-fi"], 0.45),
            ("Calm Mix", &["Ambient", "Lo-fi", "Chill"], 0.06),
        ];
        let mut mixes = vec![];
        for (mi, (name, genres, hue)) in defs.iter().enumerate() {
            let mut ids: Vec<&Track> = tracks.iter().filter(|t| genres.contains(&t.genre.as_str())).collect();
            let mut rng = fastrand::Rng::with_seed(mi as u64 + 11);
            rng.shuffle(&mut ids);
            let mut artists: Vec<String> = vec![];
            for t in &ids {
                if !artists.contains(&t.artist) {
                    artists.push(t.artist.clone());
                }
            }
            let desc = format!("{} and more", artists.iter().take(2).cloned().collect::<Vec<_>>().join(", "));
            mixes.push(Mix { name: name.to_string(), desc, hue: *hue, ids: ids.iter().map(|t| t.id.clone()).collect() });
        }
        self.tracks = tracks;
        self.albums = albums;
        self.mixes = mixes;
    }

    fn track(&self, id: &str) -> Option<&Track> {
        self.index.get(id).map(|&i| &self.tracks[i])
    }

    fn save(&self) {
        if self.ephemeral {
            return;
        }
        if let Some(u) = &self.user {
            self.data.save(&self.data_dir, &u.username);
        }
    }

    fn save_accounts(&self) {
        if !self.ephemeral {
            self.accounts.save(&self.data_dir);
        }
    }

    fn enter(&mut self, acc: Account) {
        self.data = if self.ephemeral { UserData::default() } else { UserData::load(&self.data_dir, &acc.username) };
        self.shuffle = self.data.shuffle;
        self.player.set_volume(self.data.volume);
        self.acct_name = acc.display_name.clone();
        self.user = Some(acc);
        self.view = View::Home;
        self.back.clear();
        self.forward.clear();
        self.rebuild_index();
        self.f_pass.clear();
        self.f_pass2.clear();
        self.auth_error = None;
    }

    fn sign_out(&mut self) {
        self.player.stop();
        self.playing = false;
        self.current = None;
        self.context.clear();
        self.queue.clear();
        self.user = None;
        self.data = UserData::default();
        self.accounts.remembered = None;
        self.save_accounts();
        self.rebuild_index();
        self.auth_tab = AuthTab::SignIn;
        self.confirm_delete = false;
        self.acct_msg = None;
    }

    fn demo_session(&mut self) {
        let acc = Account {
            username: "alex".into(),
            display_name: "Alex Rivera".into(),
            salt: String::new(),
            hash: String::new(),
            created: 1_760_000_000,
        };
        self.enter(acc);
        self.data.liked = vec!["demo:0:0".into(), "demo:2:1".into(), "demo:1:2".into(), "demo:4:0".into(), "demo:3:1".into()];
        self.data.playlists = vec![
            Playlist { name: "Road Trip".into(), description: "Windows down, volume up.".into(), tracks: vec!["demo:0:0".into(), "demo:4:0".into(), "demo:0:1".into(), "demo:4:2".into(), "demo:1:1".into(), "demo:0:2".into()], hue: 0.95 },
            Playlist { name: "Focus Flow".into(), description: "Calm beats for deep work.".into(), tracks: vec!["demo:2:0".into(), "demo:2:2".into(), "demo:3:0".into(), "demo:1:0".into()], hue: 0.5 },
            Playlist { name: "Late Night".into(), description: String::new(), tracks: vec!["demo:3:2".into(), "demo:0:1".into(), "demo:2:1".into(), "demo:3:1".into(), "demo:4:1".into()], hue: 0.7 },
        ];
        self.data.recent = vec!["demo:0:0".into(), "demo:2:1".into(), "demo:3:0".into(), "demo:1:2".into()];
        let ids = self.data.playlists[0].tracks.clone();
        self.context = ids;
        self.ctx_pos = 0;
        if let Some(t) = self.track("demo:0:0").cloned() {
            let _ = self.player.load(&t);
            self.player.seek(47.0);
            self.current = Some(t.id.clone());
        }
    }

    // ---------------------------------------------------------------- playback

    fn play_id(&mut self, id: &str) {
        let Some(t) = self.track(id).cloned() else { return };
        match self.player.load(&t) {
            Ok(()) => {
                self.player.play();
                self.playing = true;
                self.current = Some(t.id.clone());
                self.data.recent.retain(|r| r != &t.id);
                self.data.recent.insert(0, t.id.clone());
                self.data.recent.truncate(30);
                self.save();
            }
            Err(e) => {
                self.playing = false;
                self.current = Some(t.id.clone());
                self.show_toast(e);
            }
        }
    }

    fn start(&mut self, ids: Vec<String>, pos: usize) {
        if ids.is_empty() {
            return;
        }
        let pos = if self.shuffle && pos == 0 && ids.len() > 1 { fastrand::usize(..ids.len()) } else { pos.min(ids.len() - 1) };
        self.context = ids;
        self.ctx_pos = pos;
        let id = self.context[pos].clone();
        self.play_id(&id);
    }

    fn next(&mut self, auto: bool) {
        if auto && self.repeat == Repeat::One {
            if let Some(id) = self.current.clone() {
                self.play_id(&id);
            }
            return;
        }
        if let Some(id) = self.queue.pop_front() {
            self.play_id(&id);
            return;
        }
        let n = self.context.len();
        if n == 0 {
            self.player.stop();
            self.playing = false;
            return;
        }
        let np = if self.shuffle && n > 1 {
            loop {
                let r = fastrand::usize(..n);
                if r != self.ctx_pos {
                    break r;
                }
            }
        } else if self.ctx_pos + 1 < n {
            self.ctx_pos + 1
        } else if self.repeat == Repeat::All || !auto {
            0
        } else {
            // End of the list: rewind to the first song and stop.
            self.ctx_pos = 0;
            let id = self.context[0].clone();
            self.play_id(&id);
            self.player.pause();
            self.playing = false;
            return;
        };
        self.ctx_pos = np;
        let id = self.context[np].clone();
        self.play_id(&id);
    }

    fn prev(&mut self) {
        if self.player.position() > 3.0 || self.context.is_empty() {
            self.player.seek(0.0);
            return;
        }
        let n = self.context.len();
        self.ctx_pos = if self.ctx_pos == 0 {
            if self.repeat == Repeat::All { n - 1 } else { 0 }
        } else {
            self.ctx_pos - 1
        };
        let id = self.context[self.ctx_pos].clone();
        self.play_id(&id);
    }

    fn toggle_play(&mut self) {
        if self.current.is_none() {
            let ids = if !self.data.liked.is_empty() { self.data.liked.clone() } else { self.mixes[0].ids.clone() };
            self.start(ids, 0);
            return;
        }
        if self.playing {
            self.player.pause();
            self.playing = false;
        } else {
            if !self.player.loaded() {
                if let Some(id) = self.current.clone() {
                    self.play_id(&id);
                }
                return;
            }
            self.player.play();
            self.playing = true;
        }
    }

    fn show_toast(&mut self, s: impl Into<String>) {
        self.toast = Some((s.into(), -1.0));
    }

    fn ids_for(&self, v: &View) -> Vec<String> {
        match v {
            View::Liked => self.data.liked.clone(),
            View::Playlist(i) => self.data.playlists.get(*i).map(|p| p.tracks.clone()).unwrap_or_default(),
            View::Album(a) => self.albums.iter().find(|x| &x.name == a).map(|x| x.tracks.clone()).unwrap_or_default(),
            View::Mix(i) => self.mixes.get(*i).map(|m| m.ids.clone()).unwrap_or_default(),
            View::Local => self.data.local.iter().map(|l| library::local_to_track(l).id).collect(),
            _ => vec![],
        }
    }

    fn go(&mut self, v: View) {
        if v != self.view {
            let old = std::mem::replace(&mut self.view, v);
            self.back.push(old);
            self.forward.clear();
            if self.view == View::Search {
                self.focus_search = true;
            }
        }
    }

    fn apply(&mut self, a: Action) {
        match a {
            Action::PlayList(ids, pos) => {
                self.shuffle_guard_start(ids, pos);
            }
            Action::TogglePlay => self.toggle_play(),
            Action::Next => self.next(false),
            Action::Prev => self.prev(),
            Action::Seek(f) => {
                let d = self.player.duration();
                self.player.seek(f.clamp(0.0, 1.0) * d);
            }
            Action::Volume(v) => {
                self.player.set_volume(v);
                self.data.volume = v;
                self.save();
            }
            Action::ToggleLike(id) => {
                if self.data.liked.contains(&id) {
                    self.data.liked.retain(|x| x != &id);
                    self.show_toast("Removed from Liked Songs");
                } else {
                    self.data.liked.insert(0, id);
                    self.show_toast("Added to Liked Songs");
                }
                self.save();
            }
            Action::AddToPlaylist(id, p) => {
                if let Some(pl) = self.data.playlists.get_mut(p) {
                    let name = pl.name.clone();
                    if pl.tracks.contains(&id) {
                        self.show_toast(format!("Already in {name}"));
                    } else {
                        pl.tracks.push(id);
                        self.show_toast(format!("Added to {name}"));
                    }
                }
                self.save();
            }
            Action::NewPlaylist(first) => {
                let n = self.data.playlists.len() + 1;
                let mut pl = Playlist { name: format!("My Playlist #{n}"), description: String::new(), tracks: vec![], hue: fastrand::f32() };
                if let Some(id) = first {
                    pl.tracks.push(id);
                }
                self.data.playlists.push(pl);
                let idx = self.data.playlists.len() - 1;
                self.save();
                self.go(View::Playlist(idx));
                self.show_toast("Playlist created");
            }
            Action::RemoveFromPlaylist(p, row) => {
                if let Some(pl) = self.data.playlists.get_mut(p) {
                    if row < pl.tracks.len() {
                        pl.tracks.remove(row);
                        let name = pl.name.clone();
                        self.show_toast(format!("Removed from {name}"));
                    }
                }
                self.save();
            }
            Action::DeletePlaylist(p) => {
                if p < self.data.playlists.len() {
                    let pl = self.data.playlists.remove(p);
                    self.back.clear();
                    self.forward.clear();
                    self.view = View::Library;
                    self.show_toast(format!("Deleted {}", pl.name));
                    self.save();
                }
            }
            Action::EditPlaylist(p) => {
                if let Some(pl) = self.data.playlists.get(p) {
                    self.editing = Some((p, pl.name.clone(), pl.description.clone()));
                }
            }
            Action::Queue(id) => {
                self.queue.push_back(id);
                self.show_toast("Added to queue");
            }
            Action::Go(v) => self.go(v),
            Action::Back => {
                if let Some(v) = self.back.pop() {
                    let old = std::mem::replace(&mut self.view, v);
                    self.forward.push(old);
                }
            }
            Action::Forward => {
                if let Some(v) = self.forward.pop() {
                    let old = std::mem::replace(&mut self.view, v);
                    self.back.push(old);
                }
            }
            Action::ToggleShuffle => {
                self.shuffle = !self.shuffle;
                self.data.shuffle = self.shuffle;
                self.save();
            }
            Action::CycleRepeat => {
                self.repeat = match self.repeat {
                    Repeat::Off => Repeat::All,
                    Repeat::All => Repeat::One,
                    Repeat::One => Repeat::Off,
                };
            }
            Action::AddFolder => {
                if self.scan_rx.is_some() {
                    return;
                }
                if let Some(dir) = rfd::FileDialog::new().set_title("Choose a folder with your music").pick_folder() {
                    let (tx, rx) = channel();
                    std::thread::spawn(move || {
                        let r = library::scan_folder(&dir);
                        let _ = tx.send((dir, r));
                    });
                    self.scan_rx = Some(rx);
                    self.show_toast("Looking for music…");
                }
            }
            Action::RemoveFolder(i) => {
                if i < self.data.folders.len() {
                    let f = self.data.folders.remove(i);
                    self.data.local.retain(|l| !l.path.starts_with(&f));
                    self.rebuild_index();
                    self.save();
                    self.show_toast("Folder removed");
                }
            }
            Action::SignOut => self.sign_out(),
            Action::Toast(s) => self.show_toast(s),
        }
    }

    fn shuffle_guard_start(&mut self, ids: Vec<String>, pos: usize) {
        self.start(ids, pos);
    }

    fn poll_scan(&mut self) {
        let Some(rx) = &self.scan_rx else { return };
        if let Ok((dir, found)) = rx.try_recv() {
            self.scan_rx = None;
            let n = found.len();
            if n == 0 {
                self.show_toast("No music files found in that folder");
                return;
            }
            self.data.local.retain(|l| !l.path.starts_with(&dir));
            self.data.local.extend(found);
            if !self.data.folders.contains(&dir) {
                self.data.folders.push(dir);
            }
            self.rebuild_index();
            self.save();
            self.show_toast(format!("Added {n} songs from your computer"));
        }
    }

    // ---------------------------------------------------------------- frame

    fn tick(&mut self, ctx: &Context) {
        if self.playing && self.player.finished() {
            self.next(true);
        }
        if self.playing || self.scan_rx.is_some() {
            ctx.request_repaint_after(std::time::Duration::from_millis(100));
        }
        if self.user.is_some() && !ctx.wants_keyboard_input() && ctx.input(|i| i.key_pressed(Key::Space)) {
            self.toggle_play();
        }
    }

    fn handle_screenshot(&mut self, ctx: &Context) {
        let Some(path) = self.screenshot.clone() else { return };
        self.frames += 1;
        ctx.request_repaint();
        if self.frames >= 120 && !self.shot_requested {
            self.shot_requested = true;
            ctx.send_viewport_cmd(egui::ViewportCommand::Screenshot(Default::default()));
        }
        let shot = ctx.input(|i| {
            i.events.iter().find_map(|e| match e {
                egui::Event::Screenshot { image, .. } => Some(image.clone()),
                _ => None,
            })
        });
        if let Some(img) = shot {
            let [w, h] = img.size;
            let mut bytes = Vec::with_capacity(w * h * 4);
            for c in &img.pixels {
                bytes.extend_from_slice(&[c.r(), c.g(), c.b(), 255]);
            }
            if let Some(parent) = path.parent() {
                if !parent.as_os_str().is_empty() {
                    let _ = std::fs::create_dir_all(parent);
                }
            }
            if let Some(buf) = image::RgbaImage::from_raw(w as u32, h as u32, bytes) {
                if let Err(e) = buf.save(&path) {
                    eprintln!("failed to save screenshot: {e}");
                }
            }
            ctx.send_viewport_cmd(egui::ViewportCommand::Close);
        }
        if self.frames > 600 {
            ctx.send_viewport_cmd(egui::ViewportCommand::Close);
        }
    }

