impl eframe::App for WaveletApp {
    fn update(&mut self, ctx: &Context, _frame: &mut eframe::Frame) {
        self.poll_scan();
        if self.user.is_some() {
            self.main_ui(ctx);
        } else {
            self.auth_ui(ctx);
        }
        let actions = std::mem::take(&mut self.pending);
        for a in actions {
            self.apply(a);
        }
        self.tick(ctx);
        self.handle_screenshot(ctx);
    }
}

