    fn auth_ui(&mut self, ctx: &Context) {
        egui::CentralPanel::default().frame(Frame::new().fill(BG)).show(ctx, |ui| {
            let full = ui.max_rect();
            let p = ui.painter().clone();
            gradient4(&p, full, Color32::from_rgb(52, 26, 82), Color32::from_rgb(18, 14, 26), Color32::from_rgb(14, 12, 20), Color32::from_rgb(78, 34, 30));
            p.circle_filled(pos2(full.left() + full.width() * 0.18, full.top() + full.height() * 0.25), 180.0, ACCENT2.gamma_multiply(0.08));
            p.circle_filled(pos2(full.right() - full.width() * 0.15, full.bottom() - full.height() * 0.2), 220.0, ACCENT.gamma_multiply(0.07));

            let signup = self.auth_tab == AuthTab::SignUp;
            let h = if signup { 640.0 } else { 520.0 };
            let card = Rect::from_center_size(full.center(), vec2(430.0, h.min(full.height() - 20.0)));
            p.rect_filled(card, cr(18), PANEL);
            p.rect_stroke(card, cr(18), Stroke::new(1.0, CARD_HOVER), egui::StrokeKind::Inside);

            ui.scope_builder(UiBuilder::new().max_rect(card.shrink2(vec2(40.0, 30.0))), |ui| {
                let w = ui.available_width();
                let (lr, _) = ui.allocate_exact_size(vec2(w, 56.0), Sense::hover());
                logo(&p, lr.center(), 26.0);
                ui.vertical_centered(|ui| {
                    ui.label(RichText::new("Wavelet").font(bold(30.0)).color(TEXT));
                    ui.label(RichText::new("Music without interruptions. No ads, ever.").color(SUBTLE));
                });
                ui.add_space(16.0);

                // tabs
                let (tr, _) = ui.allocate_exact_size(vec2(w, 42.0), Sense::hover());
                p.rect_filled(tr, cr(21), BG);
                for (i, (tab, label)) in [(AuthTab::SignIn, "Sign in"), (AuthTab::SignUp, "Create account")].iter().enumerate() {
                    let r = Rect::from_min_size(pos2(tr.left() + i as f32 * w / 2.0, tr.top()), vec2(w / 2.0, 42.0)).shrink(4.0);
                    let resp = ui.interact(r, Id::new(("auth_tab", i)), Sense::click());
                    let sel = self.auth_tab == *tab;
                    if sel {
                        p.rect_filled(r, cr(17), CARD_HOVER);
                    }
                    let col = if sel || resp.hovered() { TEXT } else { SUBTLE };
                    p.text(r.center(), Align2::CENTER_CENTER, *label, bold(14.0), col);
                    if resp.clicked() && !sel {
                        self.auth_tab = *tab;
                        self.auth_error = None;
                    }
                }
                ui.add_space(14.0);

                let mut submit = false;
                field_label(ui, "Username");
                let r = ui.add(text_field(&mut self.f_user, "your-name", false, w));
                submit |= enter_pressed(ui, &r);
                if signup {
                    field_label(ui, "Display name");
                    let r = ui.add(text_field(&mut self.f_display, "What should we call you?", false, w));
                    submit |= enter_pressed(ui, &r);
                }
                field_label(ui, "Password");
                let r = ui.add(text_field(&mut self.f_pass, "At least 6 characters", true, w));
                submit |= enter_pressed(ui, &r);
                if signup {
                    field_label(ui, "Confirm password");
                    let r = ui.add(text_field(&mut self.f_pass2, "Type it again", true, w));
                    submit |= enter_pressed(ui, &r);
                }
                ui.add_space(6.0);
                ui.checkbox(&mut self.f_remember, RichText::new("Keep me signed in").color(SUBTLE));
                ui.add_space(10.0);

                let label = if signup { "Create account" } else { "Sign in" };
                if pill_button(ui, label, w, 46.0, ACCENT, BG).clicked() {
                    submit = true;
                }
                if let Some(e) = &self.auth_error {
                    ui.add_space(8.0);
                    ui.vertical_centered(|ui| ui.label(RichText::new(e).color(Color32::from_rgb(255, 110, 110))));
                }
                ui.add_space(10.0);
                ui.vertical_centered(|ui| {
                    let msg = if signup { "Your account is stored privately on this computer." } else { "New here? Choose \"Create account\" above." };
                    ui.label(RichText::new(msg).size(12.5).color(FAINT));
                });

                if submit {
                    let res = if signup {
                        self.accounts.sign_up(&self.f_user, &self.f_display, &self.f_pass, &self.f_pass2)
                    } else {
                        self.accounts.sign_in(&self.f_user, &self.f_pass)
                    };
                    match res {
                        Ok(acc) => {
                            self.accounts.remembered = if self.f_remember { Some(acc.username.clone()) } else { None };
                            self.save_accounts();
                            let first = acc.display_name.split_whitespace().next().unwrap_or("").to_string();
                            self.enter(acc);
                            if signup {
                                self.show_toast(format!("Welcome, {first}! Enjoy ad-free music."));
                            }
                        }
                        Err(e) => self.auth_error = Some(e),
                    }
                }
            });
        });
    }

