mod views;
mod widgets;

use crate::accounts::{Account, AccountStore};
use crate::library::{self, AlbumInfo, LocalTrack, Playlist, Track, UserData};
use crate::player::Player;
use crate::theme::*;
use eframe::egui::{self, pos2, vec2, Align2, Color32, Context, Frame, Id, Key, Margin, Pos2, Rect, RichText, ScrollArea, Sense, Stroke, TextEdit, Ui, UiBuilder};
use std::collections::{HashMap, VecDeque};
use std::path::PathBuf;
use std::sync::mpsc::{channel, Receiver};
use widgets::*;

#[derive(Clone, Debug, PartialEq)]
pub enum View {
    Home,
    Search,
    Library,
    Liked,
    Playlist(usize),
    Album(String),
    Mix(usize),
    Local,
    Queue,
    Account,
}

#[derive(Clone, Copy, PartialEq)]
enum AuthTab {
    SignIn,
    SignUp,
}

#[derive(Clone, Copy, PartialEq)]
enum Repeat {
    Off,
    All,
    One,
}

#[derive(Clone, Copy, PartialEq)]
enum LibFilter {
    All,
    Playlists,
    Albums,
    Local,
}

#[derive(Clone)]
pub enum Art {
    Cover(f32, String),
    Liked,
    Local,
}

#[derive(Clone, Copy, PartialEq)]
enum TableKind {
    Plain,
    Playlist(usize),
}

struct Mix {
    name: String,
    desc: String,
    hue: f32,
    ids: Vec<String>,
}

struct CardItem {
    title: String,
    subtitle: String,
    art: Art,
    view: View,
}

enum Action {
    PlayList(Vec<String>, usize),
    TogglePlay,
    Next,
    Prev,
    Seek(f32),
    Volume(f32),
    ToggleLike(String),
    AddToPlaylist(String, usize),
    NewPlaylist(Option<String>),
    RemoveFromPlaylist(usize, usize),
    DeletePlaylist(usize),
    EditPlaylist(usize),
    Queue(String),
    Go(View),
    Back,
    Forward,
    ToggleShuffle,
    CycleRepeat,
    AddFolder,
    RescanFolder(PathBuf),
    RemoveFolder(usize),
    SignOut,
}

pub struct WaveletApp {
    data_dir: PathBuf,
    ephemeral: bool,
    accounts: AccountStore,
    user: Option<Account>,
    data: UserData,

    auth_tab: AuthTab,
    f_user: String,
    f_display: String,
    f_pass: String,
    f_pass2: String,
    f_remember: bool,
    auth_error: Option<String>,

    tracks: Vec<Track>,
    index: HashMap<String, usize>,
    albums: Vec<AlbumInfo>,
    mixes: Vec<Mix>,

    view: View,
    back: Vec<View>,
    forward: Vec<View>,
    search: String,
    lib_filter: LibFilter,

    player: Player,
    current: Option<String>,
    context: Vec<String>,
    ctx_pos: usize,
    queue: VecDeque<String>,
    shuffle: bool,
    repeat: Repeat,
    playing: bool,
    seek_drag: Option<f32>,

    pending: Vec<Action>,
    toast: Option<(String, f64)>,
    scan_rx: Option<Receiver<(PathBuf, Vec<LocalTrack>)>>,
    editing: Option<(usize, String, String)>,
    acct_name: String,
    acct_old: String,
    acct_new: String,
    acct_msg: Option<(String, bool)>,
    confirm_delete: bool,
    focus_search: bool,

    screenshot: Option<PathBuf>,
    frames: u32,
    shot_requested: bool,
}

impl WaveletApp {
    pub fn new(screenshot: Option<PathBuf>) -> Self {
        let data_dir = dirs::data_dir().unwrap_or_else(|| PathBuf::from(".")).join("Wavelet");
        let ephemeral = screenshot.is_some();
        let accounts = if ephemeral { AccountStore::default() } else { AccountStore::load(&data_dir) };
        let mut app = Self {
            data_dir,
            ephemeral,
            accounts,
            user: None,
            data: UserData::default(),
            auth_tab: AuthTab::SignIn,
            f_user: String::new(),
            f_display: String::new(),
            f_pass: String::new(),
            f_pass2: String::new(),
            f_remember: true,
            auth_error: None,
            tracks: vec![],
            index: HashMap::new(),
            albums: vec![],
            mixes: vec![],
            view: View::Home,
            back: vec![],
            forward: vec![],
            search: String::new(),
            lib_filter: LibFilter::All,
            player: Player::new(!ephemeral),
            current: None,
            context: vec![],
            ctx_pos: 0,
            queue: VecDeque::new(),
            shuffle: false,
            repeat: Repeat::Off,
            playing: false,
            seek_drag: None,
            pending: vec![],
            toast: None,
            scan_rx: None,
            editing: None,
            acct_name: String::new(),
            acct_old: String::new(),
            acct_new: String::new(),
            acct_msg: None,
            confirm_delete: false,
            focus_search: false,
            screenshot,
            frames: 0,
            shot_requested: false,
        };
        app.rebuild_index();
        if app.accounts.accounts.is_empty() {
            app.auth_tab = AuthTab::SignUp;
        }
        if app.ephemeral {
            app.demo_session();
        } else if let Some(u) = app.accounts.remembered.clone() {
            if let Some(acc) = app.accounts.find(&u).cloned() {
                app.enter(acc);
            }
        }
        app
    }

    // ---------------------------------------------------------------- data

    fn rebuild_index(&mut self) {
        let mut tracks = library::demo_catalog();
        for l in &self.data.local {
            tracks.push(library::local_to_track(l));
        }
        self.index = tracks.iter().enumerate().map(|(i, t)| (t.id.clone(), i)).collect();
        let mut albums: Vec<AlbumInfo> = vec![];
        for t in &tracks {
            let local = matches!(t.source, library::TrackSource::File(_));
            if let Some(a) = albums.iter_mut().find(|a| a.name == t.album && a.local == local) {
                a.tracks.push(t.id.clone());
            } else {
                albums.push(AlbumInfo { name: t.album.clone(), artist: t.artist.clone(), hue: t.hue, tracks: vec![t.id.clone()], local });
            }
        }
        let defs: [(&str, &[&str], f32); 3] = [
            ("Daily Mix 1", &["Electronic", "Dance"], 0.8),
            ("Daily Mix 2", &["Chill", "Lo-fi"], 0.45),
            ("Calm Mix", &["Ambient", "Lo-fi", "Chill"], 0.06),
        ];
        let mut mixes = vec![];
        for (mi, (name, genres, hue)) in defs.iter().enumerate() {
            let mut picked: Vec<&Track> = tracks.iter().filter(|t| genres.contains(&t.genre.as_str())).collect();
            let mut rng = fastrand::Rng::with_seed(mi as u64 + 11);
            rng.shuffle(&mut picked);
            let mut artists: Vec<String> = vec![];
            for t in &picked {
                if !artists.contains(&t.artist) {
                    artists.push(t.artist.clone());
                }
            }
            let desc = format!("{} and more", artists.iter().take(2).cloned().collect::<Vec<_>>().join(", "));
            mixes.push(Mix { name: name.to_string(), desc, hue: *hue, ids: picked.iter().map(|t| t.id.clone()).collect() });
        }
        self.tracks = tracks;
        self.albums = albums;
        self.mixes = mixes;
    }

    fn track(&self, id: &str) -> Option<&Track> {
        self.index.get(id).map(|&i| &self.tracks[i])
    }

    fn save(&self) {
        if self.ephemeral {
            return;
        }
        if let Some(u) = &self.user {
            self.data.save(&self.data_dir, &u.username);
        }
    }

    fn save_accounts(&self) {
        if !self.ephemeral {
            self.accounts.save(&self.data_dir);
        }
    }

    fn enter(&mut self, acc: Account) {
        self.data = if self.ephemeral { UserData::default() } else { UserData::load(&self.data_dir, &acc.username) };
        self.shuffle = self.data.shuffle;
        self.player.set_volume(self.data.volume);
        self.acct_name = acc.display_name.clone();
        self.user = Some(acc);
        self.view = View::Home;
        self.back.clear();
        self.forward.clear();
        self.rebuild_index();
        self.f_pass.clear();
        self.f_pass2.clear();
        self.auth_error = None;
    }

    fn sign_out(&mut self) {
        self.player.stop();
        self.playing = false;
        self.current = None;
        self.context.clear();
        self.queue.clear();
        self.user = None;
        self.data = UserData::default();
        self.accounts.remembered = None;
        self.save_accounts();
        self.rebuild_index();
        self.auth_tab = if self.accounts.accounts.is_empty() { AuthTab::SignUp } else { AuthTab::SignIn };
        self.confirm_delete = false;
        self.acct_msg = None;
        self.editing = None;
    }

    fn demo_session(&mut self) {
        let acc = Account { username: "alex".into(), display_name: "Alex Rivera".into(), salt: String::new(), hash: String::new(), created: 1_760_000_000 };
        self.enter(acc);
        let ids = |v: &[&str]| v.iter().map(|s| s.to_string()).collect::<Vec<_>>();
        self.data.liked = ids(&["demo:0:0", "demo:2:1", "demo:1:2", "demo:4:0", "demo:3:1"]);
        self.data.playlists = vec![
            Playlist { name: "Road Trip".into(), description: "Windows down, volume up.".into(), tracks: ids(&["demo:0:0", "demo:4:0", "demo:0:1", "demo:4:2", "demo:1:1", "demo:0:2"]), hue: 0.95 },
            Playlist { name: "Focus Flow".into(), description: "Calm beats for deep work.".into(), tracks: ids(&["demo:2:0", "demo:2:2", "demo:3:0", "demo:1:0"]), hue: 0.5 },
            Playlist { name: "Late Night".into(), description: String::new(), tracks: ids(&["demo:3:2", "demo:0:1", "demo:2:1", "demo:3:1", "demo:4:1"]), hue: 0.68 },
        ];
        self.data.recent = ids(&["demo:0:0", "demo:2:1", "demo:3:0", "demo:1:2"]);
        self.context = self.data.playlists[0].tracks.clone();
        self.ctx_pos = 0;
        if let Some(t) = self.track("demo:0:0").cloned() {
            let _ = self.player.load(&t);
            self.player.seek(47.0);
            self.current = Some(t.id.clone());
        }
    }

    // ---------------------------------------------------------------- playback

    fn play_id(&mut self, id: &str) {
        let Some(t) = self.track(id).cloned() else { return };
        self.current = Some(t.id.clone());
        match self.player.load(&t) {
            Ok(()) => {
                self.player.play();
                self.playing = true;
                self.data.recent.retain(|r| r != &t.id);
                self.data.recent.insert(0, t.id.clone());
                self.data.recent.truncate(30);
                self.save();
            }
            Err(e) => {
                self.playing = false;
                self.show_toast(e);
            }
        }
    }

    fn start(&mut self, ids: Vec<String>, pos: usize) {
        if ids.is_empty() {
            return;
        }
        let pos = if self.shuffle && pos == 0 && ids.len() > 1 { fastrand::usize(..ids.len()) } else { pos.min(ids.len() - 1) };
        self.context = ids;
        self.ctx_pos = pos;
        let id = self.context[pos].clone();
        self.play_id(&id);
    }

    fn next(&mut self, auto: bool) {
        if auto && self.repeat == Repeat::One {
            if let Some(id) = self.current.clone() {
                self.play_id(&id);
            }
            return;
        }
        if let Some(id) = self.queue.pop_front() {
            self.play_id(&id);
            return;
        }
        let n = self.context.len();
        if n == 0 {
            self.player.stop();
            self.playing = false;
            return;
        }
        let np = if self.shuffle && n > 1 {
            loop {
                let r = fastrand::usize(..n);
                if r != self.ctx_pos {
                    break r;
                }
            }
        } else if self.ctx_pos + 1 < n {
            self.ctx_pos + 1
        } else if self.repeat == Repeat::All || !auto {
            0
        } else {
            // End of the list: rewind to the first song and stop.
            self.ctx_pos = 0;
            let id = self.context[0].clone();
            self.play_id(&id);
            self.player.pause();
            self.playing = false;
            return;
        };
        self.ctx_pos = np;
        let id = self.context[np].clone();
        self.play_id(&id);
    }

    fn prev(&mut self) {
        if self.player.position() > 3.0 || self.context.is_empty() {
            self.player.seek(0.0);
            return;
        }
        let n = self.context.len();
        self.ctx_pos = if self.ctx_pos == 0 {
            if self.repeat == Repeat::All {
                n - 1
            } else {
                0
            }
        } else {
            self.ctx_pos - 1
        };
        let id = self.context[self.ctx_pos].clone();
        self.play_id(&id);
    }

    fn toggle_play(&mut self) {
        if self.current.is_none() {
            let ids = if !self.data.liked.is_empty() { self.data.liked.clone() } else { self.mixes[0].ids.clone() };
            self.start(ids, 0);
            return;
        }
        if self.playing {
            self.player.pause();
            self.playing = false;
        } else if !self.player.loaded() {
            if let Some(id) = self.current.clone() {
                self.play_id(&id);
            }
        } else {
            self.player.play();
            self.playing = true;
        }
    }

    fn show_toast(&mut self, s: impl Into<String>) {
        self.toast = Some((s.into(), -1.0));
    }

    fn ids_for(&self, v: &View) -> Vec<String> {
        match v {
            View::Liked => self.data.liked.clone(),
            View::Playlist(i) => self.data.playlists.get(*i).map(|p| p.tracks.clone()).unwrap_or_default(),
            View::Album(a) => self.albums.iter().find(|x| &x.name == a).map(|x| x.tracks.clone()).unwrap_or_default(),
            View::Mix(i) => self.mixes.get(*i).map(|m| m.ids.clone()).unwrap_or_default(),
            View::Local => self.data.local.iter().map(|l| library::local_to_track(l).id).collect(),
            _ => vec![],
        }
    }

    fn go(&mut self, v: View) {
        if v != self.view {
            let old = std::mem::replace(&mut self.view, v);
            self.back.push(old);
            self.forward.clear();
            if self.view == View::Search {
                self.focus_search = true;
            }
        }
    }

    fn spawn_scan(&mut self, dir: PathBuf) {
        let (tx, rx) = channel();
        std::thread::spawn(move || {
            let r = library::scan_folder(&dir);
            let _ = tx.send((dir, r));
        });
        self.scan_rx = Some(rx);
        self.show_toast("Looking for music…");
    }

    fn apply(&mut self, a: Action) {
        match a {
            Action::PlayList(ids, pos) => self.start(ids, pos),
            Action::TogglePlay => self.toggle_play(),
            Action::Next => self.next(false),
            Action::Prev => self.prev(),
            Action::Seek(f) => {
                let d = self.player.duration();
                self.player.seek(f.clamp(0.0, 1.0) * d);
            }
            Action::Volume(v) => {
                self.player.set_volume(v);
                self.data.volume = v;
                self.save();
            }
            Action::ToggleLike(id) => {
                if self.data.liked.contains(&id) {
                    self.data.liked.retain(|x| x != &id);
                    self.show_toast("Removed from Liked Songs");
                } else {
                    self.data.liked.insert(0, id);
                    self.show_toast("Added to Liked Songs");
                }
                self.save();
            }
            Action::AddToPlaylist(id, p) => {
                if let Some(pl) = self.data.playlists.get_mut(p) {
                    let name = pl.name.clone();
                    if pl.tracks.contains(&id) {
                        self.show_toast(format!("Already in {name}"));
                    } else {
                        pl.tracks.push(id);
                        self.show_toast(format!("Added to {name}"));
                    }
                }
                self.save();
            }
            Action::NewPlaylist(first) => {
                let n = self.data.playlists.len() + 1;
                let mut pl = Playlist { name: format!("My Playlist #{n}"), description: String::new(), tracks: vec![], hue: fastrand::f32() };
                if let Some(id) = first {
                    pl.tracks.push(id);
                }
                self.data.playlists.push(pl);
                let idx = self.data.playlists.len() - 1;
                self.save();
                self.go(View::Playlist(idx));
                self.show_toast("Playlist created");
            }
            Action::RemoveFromPlaylist(p, row) => {
                if let Some(pl) = self.data.playlists.get_mut(p) {
                    if row < pl.tracks.len() {
                        pl.tracks.remove(row);
                        let name = pl.name.clone();
                        self.show_toast(format!("Removed from {name}"));
                    }
                }
                self.save();
            }
            Action::DeletePlaylist(p) => {
                if p < self.data.playlists.len() {
                    let pl = self.data.playlists.remove(p);
                    self.back.clear();
                    self.forward.clear();
                    self.view = View::Library;
                    self.show_toast(format!("Deleted {}", pl.name));
                    self.save();
                }
            }
            Action::EditPlaylist(p) => {
                if let Some(pl) = self.data.playlists.get(p) {
                    self.editing = Some((p, pl.name.clone(), pl.description.clone()));
                }
            }
            Action::Queue(id) => {
                self.queue.push_back(id);
                self.show_toast("Added to queue");
            }
            Action::Go(v) => self.go(v),
            Action::Back => {
                if let Some(v) = self.back.pop() {
                    let old = std::mem::replace(&mut self.view, v);
                    self.forward.push(old);
                }
            }
            Action::Forward => {
                if let Some(v) = self.forward.pop() {
                    let old = std::mem::replace(&mut self.view, v);
                    self.back.push(old);
                }
            }
            Action::ToggleShuffle => {
                self.shuffle = !self.shuffle;
                self.data.shuffle = self.shuffle;
                self.save();
            }
            Action::CycleRepeat => {
                self.repeat = match self.repeat {
                    Repeat::Off => Repeat::All,
                    Repeat::All => Repeat::One,
                    Repeat::One => Repeat::Off,
                };
            }
            Action::AddFolder => {
                if self.scan_rx.is_none() {
                    if let Some(dir) = rfd::FileDialog::new().set_title("Choose a folder with your music").pick_folder() {
                        self.spawn_scan(dir);
                    }
                }
            }
            Action::RescanFolder(dir) => {
                if self.scan_rx.is_none() {
                    self.spawn_scan(dir);
                }
            }
            Action::RemoveFolder(i) => {
                if i < self.data.folders.len() {
                    let f = self.data.folders.remove(i);
                    self.data.local.retain(|l| !l.path.starts_with(&f));
                    self.rebuild_index();
                    self.save();
                    self.show_toast("Folder removed");
                }
            }
            Action::SignOut => self.sign_out(),
        }
    }

    fn poll_scan(&mut self) {
        let Some(rx) = &self.scan_rx else { return };
        if let Ok((dir, found)) = rx.try_recv() {
            self.scan_rx = None;
            let n = found.len();
            if n == 0 {
                self.show_toast("No music files found in that folder");
                return;
            }
            self.data.local.retain(|l| !l.path.starts_with(&dir));
            self.data.local.extend(found);
            if !self.data.folders.contains(&dir) {
                self.data.folders.push(dir);
            }
            self.rebuild_index();
            self.save();
            self.show_toast(format!("Added {n} songs from your computer"));
        }
    }

    // ---------------------------------------------------------------- frame

    fn tick(&mut self, ctx: &Context) {
        if self.playing && self.player.finished() {
            self.next(true);
        }
        if self.playing || self.scan_rx.is_some() {
            ctx.request_repaint_after(std::time::Duration::from_millis(100));
        }
        if self.user.is_some() && self.editing.is_none() && !ctx.wants_keyboard_input() && ctx.input(|i| i.key_pressed(Key::Space)) {
            self.toggle_play();
        }
    }

    fn handle_screenshot(&mut self, ctx: &Context) {
        let Some(path) = self.screenshot.clone() else { return };
        self.frames += 1;
        ctx.request_repaint();
        if self.frames >= 120 && !self.shot_requested {
            self.shot_requested = true;
            ctx.send_viewport_cmd(egui::ViewportCommand::Screenshot(Default::default()));
        }
        let shot = ctx.input(|i| {
            i.events.iter().find_map(|e| match e {
                egui::Event::Screenshot { image, .. } => Some(image.clone()),
                _ => None,
            })
        });
        if let Some(img) = shot {
            let [w, h] = img.size;
            let mut bytes = Vec::with_capacity(w * h * 4);
            for c in &img.pixels {
                bytes.extend_from_slice(&[c.r(), c.g(), c.b(), 255]);
            }
            if let Some(parent) = path.parent() {
                if !parent.as_os_str().is_empty() {
                    let _ = std::fs::create_dir_all(parent);
                }
            }
            if let Some(buf) = image::RgbaImage::from_raw(w as u32, h as u32, bytes) {
                if let Err(e) = buf.save(&path) {
                    eprintln!("failed to save screenshot: {e}");
                }
            }
            ctx.send_viewport_cmd(egui::ViewportCommand::Close);
        }
        if self.frames > 600 {
            ctx.send_viewport_cmd(egui::ViewportCommand::Close);
        }
    }

    // ---------------------------------------------------------------- auth screen

    fn auth_ui(&mut self, ctx: &Context) {
        egui::CentralPanel::default().frame(Frame::new().fill(BG)).show(ctx, |ui| {
            let full = ui.max_rect();
            let p = ui.painter().clone();
            gradient4(&p, full, Color32::from_rgb(52, 26, 82), Color32::from_rgb(18, 14, 26), Color32::from_rgb(14, 12, 20), Color32::from_rgb(78, 34, 30));
            p.circle_filled(pos2(full.left() + full.width() * 0.18, full.top() + full.height() * 0.25), 180.0, ACCENT2.gamma_multiply(0.08));
            p.circle_filled(pos2(full.right() - full.width() * 0.15, full.bottom() - full.height() * 0.2), 220.0, ACCENT.gamma_multiply(0.07));

            let signup = self.auth_tab == AuthTab::SignUp;
            let h: f32 = if signup { 660.0 } else { 540.0 };
            let card = Rect::from_center_size(full.center(), vec2(430.0, h.min(full.height() - 20.0)));
            p.rect_filled(card, cr(18), PANEL);
            p.rect_stroke(card, cr(18), Stroke::new(1.0, CARD_HOVER), egui::StrokeKind::Inside);

            ui.scope_builder(UiBuilder::new().max_rect(card.shrink2(vec2(40.0, 28.0))), |ui| {
                let w = ui.available_width();
                let (lr, _) = ui.allocate_exact_size(vec2(w, 56.0), Sense::hover());
                logo(&p, lr.center(), 26.0);
                ui.vertical_centered(|ui| {
                    ui.label(RichText::new("Wavelet").font(bold(30.0)).color(TEXT));
                    ui.label(RichText::new("Music without interruptions. No ads, ever.").color(SUBTLE));
                });
                ui.add_space(16.0);

                let (tr, _) = ui.allocate_exact_size(vec2(w, 42.0), Sense::hover());
                p.rect_filled(tr, cr(21), BG);
                for (i, (tab, label)) in [(AuthTab::SignIn, "Sign in"), (AuthTab::SignUp, "Create account")].iter().enumerate() {
                    let r = Rect::from_min_size(pos2(tr.left() + i as f32 * w / 2.0, tr.top()), vec2(w / 2.0, 42.0)).shrink(4.0);
                    let resp = ui.interact(r, Id::new(("auth_tab", i)), Sense::click());
                    let sel = self.auth_tab == *tab;
                    if sel {
                        p.rect_filled(r, cr(17), CARD_HOVER);
                    }
                    let col = if sel || resp.hovered() { TEXT } else { SUBTLE };
                    p.text(r.center(), Align2::CENTER_CENTER, *label, bold(14.0), col);
                    if resp.clicked() && !sel {
                        self.auth_tab = *tab;
                        self.auth_error = None;
                    }
                }
                ui.add_space(12.0);

                let mut submit = false;
                field_label(ui, "Username");
                let r = ui.add(text_field(&mut self.f_user, "your-name", false, w));
                submit |= enter_pressed(ui, &r);
                if signup {
                    field_label(ui, "Display name");
                    let r = ui.add(text_field(&mut self.f_display, "What should we call you?", false, w));
                    submit |= enter_pressed(ui, &r);
                }
                field_label(ui, "Password");
                let r = ui.add(text_field(&mut self.f_pass, "At least 6 characters", true, w));
                submit |= enter_pressed(ui, &r);
                if signup {
                    field_label(ui, "Confirm password");
                    let r = ui.add(text_field(&mut self.f_pass2, "Type it again", true, w));
                    submit |= enter_pressed(ui, &r);
                }
                ui.add_space(6.0);
                ui.checkbox(&mut self.f_remember, RichText::new("Keep me signed in").color(SUBTLE));
                ui.add_space(10.0);

                let label = if signup { "Create account" } else { "Sign in" };
                if pill_button(ui, label, w, 46.0, ACCENT, BG).clicked() {
                    submit = true;
                }
                if let Some(e) = &self.auth_error {
                    ui.add_space(8.0);
                    ui.vertical_centered(|ui| ui.label(RichText::new(e).color(Color32::from_rgb(255, 110, 110))));
                }
                ui.add_space(10.0);
                ui.vertical_centered(|ui| {
                    let msg = if signup { "Your account is stored privately on this computer." } else { "New here? Choose \"Create account\" above." };
                    ui.label(RichText::new(msg).size(12.5).color(FAINT));
                });

                if submit {
                    let res = if signup {
                        self.accounts.sign_up(&self.f_user, &self.f_display, &self.f_pass, &self.f_pass2)
                    } else {
                        self.accounts.sign_in(&self.f_user, &self.f_pass)
                    };
                    match res {
                        Ok(acc) => {
                            self.accounts.remembered = if self.f_remember { Some(acc.username.clone()) } else { None };
                            self.save_accounts();
                            let first = acc.display_name.split_whitespace().next().unwrap_or("").to_string();
                            self.enter(acc);
                            if signup {
                                self.show_toast(format!("Welcome, {first}! Enjoy ad-free music."));
                            }
                        }
                        Err(e) => self.auth_error = Some(e),
                    }
                }
            });
        });
    }

