                p.circle_filled(pr.center(), 15.0, CARD_HOVER);
            }
            plus(&p, pr.center(), 14.0, if presp.hovered() { TEXT } else { SUBTLE });
            if presp.clicked() {
                self.pending.push(Action::NewPlaylist(None));
            }
            ui.add_space(4.0);

            let list_h = ui.available_height() - 48.0;
            ScrollArea::vertical().max_height(list_h.max(60.0)).auto_shrink([false, true]).show(ui, |ui| {
                let liked_n = self.data.liked.len();
                if lib_row(ui, "Liked Songs", &format!("Playlist · {liked_n} songs"), Art::Liked, self.view == View::Liked).clicked() {
                    self.pending.push(Action::Go(View::Liked));
                }
                let pls: Vec<(usize, String, usize, f32)> = self.data.playlists.iter().enumerate().map(|(i, p)| (i, p.name.clone(), p.tracks.len(), p.hue)).collect();
                for (i, name, n, hue) in pls {
                    let resp = lib_row(ui, &name, &format!("Playlist · {n} songs"), Art::Cover(hue, name.clone()), self.view == View::Playlist(i));
                    if resp.clicked() {
                        self.pending.push(Action::Go(View::Playlist(i)));
                    }
                    resp.context_menu(|ui| {
                        if ui.button("Play").clicked() {
                            let ids = self.ids_for(&View::Playlist(i));
                            self.pending.push(Action::PlayList(ids, 0));
                            ui.close_menu();
                        }
                        if ui.button("Edit details").clicked() {
                            self.pending.push(Action::EditPlaylist(i));
                            ui.close_menu();
                        }
                        if ui.button("Delete").clicked() {
                            self.pending.push(Action::DeletePlaylist(i));
                            ui.close_menu();
                        }
                    });
                }
                if !self.data.local.is_empty() {
                    let n = self.data.local.len();
                    if lib_row(ui, "Local files", &format!("{n} songs on this computer"), Art::Local, self.view == View::Local).clicked() {
                        self.pending.push(Action::Go(View::Local));
                    }
                }
                let albums: Vec<(String, String, f32)> = self.albums.iter().filter(|a| !a.local).map(|a| (a.name.clone(), a.artist.clone(), a.hue)).collect();
                for (name, artist, hue) in albums {
                    let sel = self.view == View::Album(name.clone());
                    if lib_row(ui, &name, &format!("Album · {artist}"), Art::Cover(hue, name.clone()), sel).clicked() {
                        self.pending.push(Action::Go(View::Album(name)));
                    }
                }
            });
            ui.add_space(6.0);
            let label = if self.scan_rx.is_some() { "Scanning your music…" } else { "Add music from your computer" };
            if outline_button(ui, label, w, 36.0).clicked() {
                self.pending.push(Action::AddFolder);
            }
        });
    }

    fn top_bar(&mut self, ui: &mut Ui) {
        let (bar, _) = ui.allocate_exact_size(vec2(ui.available_width(), 64.0), Sense::hover());
        let p = ui.painter().clone();
        for (i, left) in [true, false].iter().enumerate() {
            let c = pos2(bar.left() + 36.0 + i as f32 * 42.0, bar.center().y);
            let r = Rect::from_center_size(c, vec2(32.0, 32.0));
            let enabled = if *left { !self.back.is_empty() } else { !self.forward.is_empty() };
            let resp = ui.interact(r, Id::new(("nav", i)), Sense::click());
            p.circle_filled(c, 16.0, Color32::from_black_alpha(if resp.hovered() && enabled { 200 } else { 130 }));
            chevron(&p, c, 18.0, if enabled { TEXT } else { FAINT }, *left);
            if resp.clicked() && enabled {
                self.pending.push(if *left { Action::Back } else { Action::Forward });
            }
        }
        if self.view == View::Search {
            let sr = Rect::from_min_size(pos2(bar.left() + 110.0, bar.center().y - 22.0), vec2(380.0f32.min(bar.width() - 320.0), 44.0));
            p.rect_filled(sr, cr(22), CARD_HOVER);
            search(&p, pos2(sr.left() + 24.0, sr.center().y), 18.0, SUBTLE, false);
            let inner = Rect::from_min_max(pos2(sr.left() + 44.0, sr.center().y - 11.0), pos2(sr.right() - 16.0, sr.center().y + 11.0));
            let resp = ui.put(inner, TextEdit::singleline(&mut self.search).frame(false).hint_text("What do you want to listen to?").font(reg(15.0)).desired_width(inner.width()));
            if self.focus_search {
                resp.request_focus();
                self.focus_search = false;
            }
        }
        let Some(user) = self.user.clone() else { return };
        let ac = pos2(bar.right() - 36.0, bar.center().y);
        let ar = Rect::from_center_size(ac, vec2(36.0, 36.0));
        let aresp = ui.interact(ar, Id::new("avatar"), Sense::click()).on_hover_text(&user.display_name);
        p.circle_filled(ac, 18.0, Color32::from_black_alpha(140));
        p.circle_filled(ac, 14.0, hsv(library::hue_of(&user.username), 0.55, 0.9));
        let initial = user.display_name.chars().next().unwrap_or('?').to_uppercase().to_string();
        p.text(ac, Align2::CENTER_CENTER, initial, bold(14.0), BG);
        if aresp.hovered() {
            p.circle_stroke(ac, 18.0, Stroke::new(1.5, TEXT));
        }
        let badge = Rect::from_min_size(pos2(ac.x - 30.0 - 92.0, bar.center().y - 15.0), vec2(92.0, 30.0));
        p.rect_filled(badge, cr(15), Color32::from_black_alpha(120));
        p.rect_stroke(badge, cr(15), Stroke::new(1.0, ACCENT.gamma_multiply(0.7)), egui::StrokeKind::Inside);
        p.circle_filled(pos2(badge.left() + 16.0, badge.center().y), 4.0, ACCENT);
        p.text(pos2(badge.left() + 28.0, badge.center().y), Align2::LEFT_CENTER, "Ad-free", bold(13.0), TEXT);
        ui.interact(badge, Id::new("adfree"), Sense::hover()).on_hover_text("No ads. No interruptions between songs. Ever.");

        let popup_id = Id::new("acct_popup");
        if aresp.clicked() {
            ui.memory_mut(|m| m.toggle_popup(popup_id));
        }
        egui::popup::popup_below_widget(ui, popup_id, &aresp, egui::PopupCloseBehavior::CloseOnClick, |ui| {
            ui.set_min_width(190.0);
            ui.label(RichText::new(&user.display_name).font(bold(14.0)));
            ui.label(RichText::new(format!("@{}", user.username)).color(SUBTLE).size(12.5));
            ui.separator();
            if ui.button("Account").clicked() {
                self.pending.push(Action::Go(View::Account));
            }
            if ui.button("Queue").clicked() {
                self.pending.push(Action::Go(View::Queue));
            }
            if ui.button("Sign out").clicked() {
                self.pending.push(Action::SignOut);
            }
        });
    }

    // ---------------------------------------------------------------- player bar

    fn player_bar(&mut self, ui: &mut Ui) {
        let r = ui.max_rect();
        let p = ui.painter().clone();
        let cur = self.current.clone().and_then(|id| self.track(&id).cloned());

        let left_w = (r.width() * 0.3).min(360.0);
        if let Some(t) = &cur {
            let cv = Rect::from_min_size(pos2(r.left(), r.center().y - 30.0), vec2(60.0, 60.0));
            draw_art(&p, cv, &Art::Cover(t.hue, t.album.clone()));
            let tw = left_w - 120.0;
            let tr = fit_text(&p, pos2(cv.right() + 14.0, r.center().y - 2.0), Align2::LEFT_BOTTOM, &t.title, bold(14.5), TEXT, tw);
            fit_text(&p, pos2(cv.right() + 14.0, r.center().y + 2.0), Align2::LEFT_TOP, &t.artist, reg(12.5), SUBTLE, tw);
            if ui.interact(tr, Id::new("np_title"), Sense::click()).clicked() {
                self.pending.push(Action::Go(View::Album(t.album.clone())));
            }
            let liked = self.data.liked.contains(&t.id);
            let hx = (tr.right().max(cv.right() + 74.0) + 22.0).min(r.left() + left_w - 10.0);
            let hc = pos2(hx, r.center().y);
            let hresp = ui.interact(Rect::from_center_size(hc, vec2(28.0, 28.0)), Id::new("np_like"), Sense::click());
            heart(&p, hc, 15.0, if liked { ACCENT } else if hresp.hovered() { TEXT } else { SUBTLE }, liked);
            if hresp.clicked() {
                self.pending.push(Action::ToggleLike(t.id.clone()));
            }
        } else {
            p.text(pos2(r.left(), r.center().y), Align2::LEFT_CENTER, "Pick something to play", reg(14.0), SUBTLE);
        }

        let cx = r.center().x;
        let cy = r.top() + 26.0;
        let has = cur.is_some();
        let btn = |ui: &mut Ui, c: Pos2, id: &str, tip: &str| ui.interact(Rect::from_center_size(c, vec2(32.0, 32.0)), Id::new(id), Sense::click()).on_hover_text(tip);

        let sc = pos2(cx - 100.0, cy);
        let s = btn(ui, sc, "pb_shuffle", "Shuffle");
        shuffle(&p, sc, 20.0, if self.shuffle { ACCENT } else if s.hovered() { TEXT } else { SUBTLE });
        if self.shuffle {
            p.circle_filled(pos2(sc.x, sc.y + 14.0), 2.0, ACCENT);
        }
        if s.clicked() {
            self.pending.push(Action::ToggleShuffle);
        }
        let pc = pos2(cx - 50.0, cy);
        let pr = btn(ui, pc, "pb_prev", "Previous");
        skip(&p, pc, 18.0, if pr.hovered() && has { TEXT } else { SUBTLE }, false);
        if pr.clicked() {
            self.pending.push(Action::Prev);
        }
        let mc = pos2(cx, cy);
        let m = ui.interact(Rect::from_center_size(mc, vec2(38.0, 38.0)), Id::new("pb_play"), Sense::click()).on_hover_text(if self.playing { "Pause" } else { "Play" });
        p.circle_filled(mc, if m.hovered() { 19.5 } else { 18.0 }, TEXT);
        if self.playing {
            pause(&p, mc, 14.0, BG);
        } else {
            play(&p, pos2(mc.x + 1.5, mc.y), 14.0, BG);
        }
        if m.clicked() {
            self.pending.push(Action::TogglePlay);
        }
        let nc = pos2(cx + 50.0, cy);
        let nr = btn(ui, nc, "pb_next", "Next");
        skip(&p, nc, 18.0, if nr.hovered() && has { TEXT } else { SUBTLE }, true);
        if nr.clicked() {
            self.pending.push(Action::Next);
        }
        let rc = pos2(cx + 100.0, cy);
        let tip = match self.repeat {
            Repeat::Off => "Repeat",
            Repeat::All => "Repeat all",
            Repeat::One => "Repeat one",
        };
        let rr = btn(ui, rc, "pb_repeat", tip);
        let rcol = if self.repeat != Repeat::Off { ACCENT } else if rr.hovered() { TEXT } else { SUBTLE };
        repeat(&p, rc, 20.0, rcol, self.repeat == Repeat::One);
        if self.repeat != Repeat::Off {
            p.circle_filled(pos2(rc.x, rc.y + 14.0), 2.0, ACCENT);
        }
        if rr.clicked() {
            self.pending.push(Action::CycleRepeat);
        }

        let dur = self.player.duration().max(0.0);
        let pos = if has { self.player.position() } else { 0.0 };
        let bw = (r.width() * 0.4).min(600.0);
        let py = r.top() + 62.0;
        let bar = Rect::from_center_size(pos2(cx, py), vec2(bw, 4.0));
        let frac = if dur > 0.0 { (pos / dur).clamp(0.0, 1.0) } else { 0.0 };
        let shown = self.seek_drag.unwrap_or(frac);
        p.text(pos2(bar.left() - 12.0, py), Align2::RIGHT_CENTER, fmt_time(shown * dur), reg(12.0), SUBTLE);
        p.text(pos2(bar.right() + 12.0, py), Align2::LEFT_CENTER, fmt_time(dur), reg(12.0), SUBTLE);
        if let Some(ev) = slider_bar(ui, &p, bar, "seek", shown, has) {
            match ev {
                SliderEv::Drag(v) => self.seek_drag = Some(v),
                SliderEv::Done(v) => {
                    self.seek_drag = None;
                    self.pending.push(Action::Seek(v));
                }
            }
        }

        let qc = pos2(r.right() - 196.0, r.center().y);
        let qr = btn(ui, qc, "pb_queue", "Queue");
        queue(&p, qc, 18.0, if self.view == View::Queue { ACCENT } else if qr.hovered() { TEXT } else { SUBTLE });
        if qr.clicked() {
            self.pending.push(if self.view == View::Queue { Action::Back } else { Action::Go(View::Queue) });
        }
        let vc = pos2(r.right() - 156.0, r.center().y);
        let vr = btn(ui, vc, "pb_mute", "Mute");
        let vol = self.data.volume;
        volume(&p, vc, 20.0, if vr.hovered() { TEXT } else { SUBTLE }, vol);
        if vr.clicked() {
            self.pending.push(Action::Volume(if vol > 0.0 { 0.0 } else { 0.7 }));
        }
        let vbar = Rect::from_min_size(pos2(r.right() - 130.0, r.center().y - 2.0), vec2(120.0, 4.0));
        if let Some(ev) = slider_bar(ui, &p, vbar, "volume", vol, true) {
            let v = match ev {
                SliderEv::Drag(v) | SliderEv::Done(v) => v,
            };
            self.pending.push(Action::Volume(v));
        }
    }

    fn edit_window(&mut self, ctx: &Context) {
        let Some((idx, mut name, mut desc)) = self.editing.clone() else { return };
        let mut close = false;
        let mut save = false;
        egui::Window::new("Edit details")
            .collapsible(false)
            .resizable(false)
            .title_bar(false)
            .anchor(Align2::CENTER_CENTER, vec2(0.0, 0.0))
            .frame(Frame::new().fill(CARD).corner_radius(cr(12)).inner_margin(Margin::same(24)).stroke(Stroke::new(1.0, CARD_HOVER)))
            .show(ctx, |ui| {
                ui.set_width(380.0);
                ui.label(RichText::new("Edit details").font(bold(22.0)));
                ui.add_space(10.0);
                field_label(ui, "Name");
                let r = ui.add(text_field(&mut name, "Playlist name", false, 380.0));
                if enter_pressed(ui, &r) {
                    save = true;
                }
                field_label(ui, "Description");
                ui.add(TextEdit::multiline(&mut desc).hint_text("Add an optional description").desired_width(380.0).desired_rows(3).margin(Margin::symmetric(10, 8)));
                ui.add_space(12.0);
                ui.horizontal(|ui| {
                    if pill_button(ui, "Save", 100.0, 38.0, TEXT, BG).clicked() {
                        save = true;
                    }
                    if ui.add(egui::Button::new("Cancel").frame(false)).clicked() {
                        close = true;
                    }
                });
            });
        if ctx.input(|i| i.key_pressed(Key::Escape)) {
            close = true;
        }
        if save {
            if let Some(pl) = self.data.playlists.get_mut(idx) {
                if !name.trim().is_empty() {
                    pl.name = name.trim().to_string();
                }
                pl.description = desc.trim().to_string();
            }
            self.save();
            self.editing = None;
        } else if close {
            self.editing = None;
        } else {
            self.editing = Some((idx, name, desc));
        }
    }

    fn toast_ui(&mut self, ctx: &Context) {
        let now = ctx.input(|i| i.time);
        let Some((msg, t0)) = self.toast.clone() else { return };
        let t0 = if t0 < 0.0 {
            self.toast = Some((msg.clone(), now));
            now
        } else {
            t0
        };
        if now - t0 > 2.6 {
            self.toast = None;
            return;
        }
        ctx.request_repaint_after(std::time::Duration::from_millis(100));
        egui::Area::new(Id::new("toast"))
            .anchor(Align2::CENTER_BOTTOM, vec2(0.0, -112.0))
            .order(egui::Order::Foreground)
            .interactable(false)
            .show(ctx, |ui| {
                Frame::new().fill(TEXT).corner_radius(cr(8)).inner_margin(Margin::symmetric(16, 10)).show(ui, |ui| {
                    ui.label(RichText::new(msg).color(BG).font(bold(14.0)));
                });
            });
    }
}

impl eframe::App for WaveletApp {
    fn update(&mut self, ctx: &Context, _frame: &mut eframe::Frame) {
        self.poll_scan();
        if self.user.is_some() {
            self.main_ui(ctx);
        } else {
            self.auth_ui(ctx);
        }
        let actions = std::mem::take(&mut self.pending);
        for a in actions {
            self.apply(a);
        }
        self.tick(ctx);
        self.handle_screenshot(ctx);
    }
}

use super::widgets::*;
use super::*;
use crate::accounts::member_since;

impl WaveletApp {
    pub(super) fn view_content(&mut self, ui: &mut Ui) {
        match self.view.clone() {
            View::Home => self.home_view(ui),
            View::Search => self.search_view(ui),
            View::Library => self.library_view(ui),
            View::Liked => {
                let name = self.user.as_ref().map(|u| u.display_name.clone()).unwrap_or_default();
                let ids = self.data.liked.clone();
                let sub = format!("{name} · {} songs", ids.len());
                self.collection_view(ui, "Playlist", "Liked Songs".into(), sub, String::new(), Art::Liked, ids, TableKind::Plain, None);
            }
            View::Playlist(i) => {
                let Some(pl) = self.data.playlists.get(i).cloned() else {
                    ui.label("This playlist no longer exists.");
                    return;
                };
                let name = self.user.as_ref().map(|u| u.display_name.clone()).unwrap_or_default();
                let total: f32 = pl.tracks.iter().filter_map(|id| self.track(id)).map(|t| t.duration).sum();
                let sub = format!("{name} · {} songs, {}", pl.tracks.len(), long_time(total));
                self.collection_view(ui, "Playlist", pl.name.clone(), sub, pl.description.clone(), Art::Cover(pl.hue, pl.name.clone()), pl.tracks.clone(), TableKind::Playlist(i), Some(i));
            }
            View::Album(a) => {
                let Some(al) = self.albums.iter().find(|x| x.name == a).cloned() else {
                    ui.label("Album not found.");
                    return;
                };
                let total: f32 = al.tracks.iter().filter_map(|id| self.track(id)).map(|t| t.duration).sum();
                let sub = format!("{} · {} songs, {}", al.artist, al.tracks.len(), long_time(total));
                let kind = if al.local { "Album · On this computer" } else { "Album" };
                self.collection_view(ui, kind, al.name.clone(), sub, String::new(), Art::Cover(al.hue, al.name.clone()), al.tracks.clone(), TableKind::Plain, None);
            }
            View::Mix(i) => {
                let Some(m) = self.mixes.get(i) else { return };
                let (name, desc, hue, ids) = (m.name.clone(), m.desc.clone(), m.hue, m.ids.clone());
                let sub = format!("Made for you · {} songs", ids.len());
                self.collection_view(ui, "Mix", name.clone(), sub, desc, Art::Cover(hue, name), ids, TableKind::Plain, None);
            }
            View::Local => self.local_view(ui),
            View::Queue => self.queue_view(ui),
            View::Account => self.account_view(ui),
        }
    }

    fn home_view(&mut self, ui: &mut Ui) {
        let first = self.user.as_ref().map(|u| u.display_name.split_whitespace().next().unwrap_or("").to_string()).unwrap_or_default();
        ui.add_space(4.0);
        ui.label(RichText::new(format!("Welcome back, {first}")).font(bold(30.0)));
        ui.add_space(14.0);

        let mut tiles: Vec<CardItem> = vec![CardItem { title: "Liked Songs".into(), subtitle: String::new(), art: Art::Liked, view: View::Liked }];
        for (i, p) in self.data.playlists.iter().enumerate().take(3) {
            tiles.push(CardItem { title: p.name.clone(), subtitle: String::new(), art: Art::Cover(p.hue, p.name.clone()), view: View::Playlist(i) });
        }
        for (i, m) in self.mixes.iter().enumerate() {
            if tiles.len() >= 6 {
                break;
            }
            tiles.push(CardItem { title: m.name.clone(), subtitle: String::new(), art: Art::Cover(m.hue, m.name.clone()), view: View::Mix(i) });
        }
        for a in self.albums.iter().filter(|a| !a.local) {
            if tiles.len() >= 6 {
                break;
            }
            tiles.push(CardItem { title: a.name.clone(), subtitle: String::new(), art: Art::Cover(a.hue, a.name.clone()), view: View::Album(a.name.clone()) });
        }
        let w = ui.available_width();
        let gap = 12.0;
        let cols = if w > 900.0 { 3 } else { 2 };
        let tw = (w - gap * (cols as f32 - 1.0)) / cols as f32;
        for row in tiles.chunks(cols) {
            ui.horizontal(|ui| {
                ui.spacing_mut().item_spacing.x = gap;
                for t in row {
                    self.quick_tile(ui, t, tw);
                }
            });
            ui.add_space(4.0);
        }

        ui.add_space(20.0);
        let mixes: Vec<CardItem> = self
            .mixes
            .iter()
            .enumerate()
            .map(|(i, m)| CardItem { title: m.name.clone(), subtitle: m.desc.clone(), art: Art::Cover(m.hue, m.name.clone()), view: View::Mix(i) })
            .collect();
        let name = self.user.as_ref().map(|u| u.display_name.clone()).unwrap_or_default();
        self.shelf(ui, &format!("Made for {name}"), mixes, false);

        let mut recent_albums: Vec<String> = vec![];
        for id in &self.data.recent {
            if let Some(t) = self.track(id) {
                if !recent_albums.contains(&t.album) {
                    recent_albums.push(t.album.clone());
                }
            }
        }
        if !recent_albums.is_empty() {
            let items: Vec<CardItem> = recent_albums
                .iter()
                .filter_map(|n| self.albums.iter().find(|a| &a.name == n))
                .map(|a| CardItem { title: a.name.clone(), subtitle: a.artist.clone(), art: Art::Cover(a.hue, a.name.clone()), view: View::Album(a.name.clone()) })
                .collect();
            self.shelf(ui, "Recently played", items, false);
        }

        let items: Vec<CardItem> = self
            .albums
            .iter()
            .filter(|a| !a.local)
            .map(|a| CardItem { title: a.name.clone(), subtitle: a.artist.clone(), art: Art::Cover(a.hue, a.name.clone()), view: View::Album(a.name.clone()) })
            .collect();
        self.shelf(ui, "Albums to explore", items, true);

        let local: Vec<CardItem> = self
            .albums
            .iter()
            .filter(|a| a.local)
            .map(|a| CardItem { title: a.name.clone(), subtitle: a.artist.clone(), art: Art::Cover(a.hue, a.name.clone()), view: View::Album(a.name.clone()) })
            .collect();
        if !local.is_empty() {
            self.shelf(ui, "From your computer", local, true);
        }
    }

    fn quick_tile(&mut self, ui: &mut Ui, t: &CardItem, w: f32) {
        let (r, resp) = ui.allocate_exact_size(vec2(w, 64.0), Sense::click());
        let p = ui.painter().clone();
        p.rect_filled(r, cr(6), if resp.hovered() { Color32::from_white_alpha(40) } else { Color32::from_white_alpha(18) });
        let cvr = Rect::from_min_size(r.min, vec2(64.0, 64.0));
        draw_art(&p, cvr, &t.art);
        fit_text(&p, pos2(cvr.right() + 14.0, r.center().y), Align2::LEFT_CENTER, &t.title, bold(15.0), TEXT, w - 64.0 - 76.0);
        let ids = self.ids_for(&t.view);
        let playing_this = self.playing && !ids.is_empty() && self.context == ids;
        if resp.hovered() || playing_this {
            let c = pos2(r.right() - 32.0, r.center().y);
            let pr = Rect::from_center_size(c, vec2(40.0, 40.0));
            let presp = ui.interact(pr, Id::new(("qt_play", &t.title)), Sense::click());
            p.circle_filled(c, if presp.hovered() { 21.0 } else { 20.0 }, if presp.hovered() { ACCENT_HI } else { ACCENT });
            if playing_this {
                pause(&p, c, 14.0, BG);
            } else {
                play(&p, pos2(c.x + 1.0, c.y), 14.0, BG);
            }
            if presp.clicked() {
                self.pending.push(if playing_this { Action::TogglePlay } else { Action::PlayList(ids, 0) });
                return;
            }
        }
        if resp.clicked() {
            self.pending.push(Action::Go(t.view.clone()));
        }
    }

    fn shelf(&mut self, ui: &mut Ui, title: &str, items: Vec<CardItem>, wrap: bool) {
        if items.is_empty() {
            return;
        }
        ui.add_space(8.0);
        ui.label(RichText::new(title).font(bold(22.0)));
        ui.add_space(8.0);
        let w = ui.available_width();
        let gap = 12.0;
        let cols = (((w + gap) / (180.0 + gap)).floor() as usize).max(2);
        let cw = (w - gap * (cols as f32 - 1.0)) / cols as f32;
        let take = if wrap { items.len() } else { cols.min(items.len()) };
        for row in items[..take].chunks(cols) {
            ui.horizontal(|ui| {
                ui.spacing_mut().item_spacing.x = gap;
                for it in row {
                    self.card(ui, it, cw);
                }
            });
            ui.add_space(6.0);
        }
        ui.add_space(14.0);
    }

    fn card(&mut self, ui: &mut Ui, it: &CardItem, w: f32) {
        let h = w + 50.0;
        let (r, resp) = ui.allocate_exact_size(vec2(w, h), Sense::click());
        let p = ui.painter().clone();
        if resp.hovered() {
            p.rect_filled(r, cr(8), Color32::from_white_alpha(14));
        }
        let pad = 10.0;
        let cvr = Rect::from_min_size(r.min + vec2(pad, pad), vec2(w - 2.0 * pad, w - 2.0 * pad));
        p.rect_filled(cvr.translate(vec2(0.0, 4.0)), cr(6), Color32::from_black_alpha(60));
        draw_art(&p, cvr, &it.art);
        fit_text(&p, pos2(cvr.left(), cvr.bottom() + 10.0), Align2::LEFT_TOP, &it.title, bold(15.0), TEXT, cvr.width());
        fit_text(&p, pos2(cvr.left(), cvr.bottom() + 31.0), Align2::LEFT_TOP, &it.subtitle, reg(13.0), SUBTLE, cvr.width());
        if resp.hovered() {
            let c = pos2(cvr.right() - 28.0, cvr.bottom() - 28.0);
            let pr = Rect::from_center_size(c, vec2(46.0, 46.0));
            let presp = ui.interact(pr, Id::new(("card_play", &it.title)), Sense::click());
            p.circle_filled(c + vec2(0.0, 2.0), 23.0, Color32::from_black_alpha(90));
            p.circle_filled(c, 23.0, if presp.hovered() { ACCENT_HI } else { ACCENT });
            play(&p, pos2(c.x + 1.5, c.y), 16.0, BG);
            if presp.clicked() {
                let ids = self.ids_for(&it.view);
                self.pending.push(Action::PlayList(ids, 0));
                return;
            }
        }
        if resp.clicked() {
            self.pending.push(Action::Go(it.view.clone()));
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn collection_view(&mut self, ui: &mut Ui, kind: &str, title: String, sub: String, desc: String, art: Art, ids: Vec<String>, table: TableKind, playlist: Option<usize>) {
        let w = ui.available_width();
        let (hr, _) = ui.allocate_exact_size(vec2(w, 220.0), Sense::hover());
        let p = ui.painter().clone();
        let cv = Rect::from_min_size(pos2(hr.left(), hr.top() + 10.0), vec2(200.0, 200.0));
        p.rect_filled(cv.translate(vec2(0.0, 6.0)), cr(4), Color32::from_black_alpha(90));
        draw_art(&p, cv, &art);
        let tx = cv.right() + 24.0;
        let tw = hr.right() - tx;
        p.text(pos2(tx, cv.top() + 64.0), Align2::LEFT_BOTTOM, kind, bold(13.0), TEXT);
        let size = if title.chars().count() > 18 { 40.0 } else { 64.0 };
        fit_text(&p, pos2(tx - 2.0, cv.top() + 138.0), Align2::LEFT_BOTTOM, &title, bold(size), TEXT, tw);
        if !desc.is_empty() {
            fit_text(&p, pos2(tx, cv.top() + 168.0), Align2::LEFT_BOTTOM, &desc, reg(14.0), SUBTLE, tw);
        }
        fit_text(&p, pos2(tx, cv.bottom()), Align2::LEFT_BOTTOM, &sub, reg(14.0), TEXT, tw);
        if let Some(i) = playlist {
            let tr = Rect::from_min_max(pos2(tx, cv.top() + 70.0), pos2(hr.right(), cv.top() + 140.0));
            if ui.interact(tr, Id::new("pl_title"), Sense::click()).on_hover_text("Edit details").clicked() {
                self.pending.push(Action::EditPlaylist(i));
            }
        }

        ui.add_space(16.0);
        let (ar, _) = ui.allocate_exact_size(vec2(w, 64.0), Sense::hover());
        let c = pos2(ar.left() + 30.0, ar.center().y);
        let presp = ui.interact(Rect::from_center_size(c, vec2(58.0, 58.0)), Id::new("big_play"), Sense::click());
        let this_ctx = !ids.is_empty() && self.context == ids && self.current.is_some();
        p.circle_filled(c, if presp.hovered() { 30.0 } else { 28.0 }, if ids.is_empty() { FAINT } else if presp.hovered() { ACCENT_HI } else { ACCENT });
        if this_ctx && self.playing {
            pause(&p, c, 20.0, BG);
        } else {
            play(&p, pos2(c.x + 2.0, c.y), 20.0, BG);
        }
        if presp.clicked() && !ids.is_empty() {
            self.pending.push(if this_ctx { Action::TogglePlay } else { Action::PlayList(ids.clone(), 0) });
        }
        let sc = pos2(ar.left() + 90.0, ar.center().y);
        let sresp = ui.interact(Rect::from_center_size(sc, vec2(36.0, 36.0)), Id::new("big_shuffle"), Sense::click()).on_hover_text("Shuffle");
        shuffle(&p, sc, 26.0, if self.shuffle { ACCENT } else if sresp.hovered() { TEXT } else { SUBTLE });
        if self.shuffle {
            p.circle_filled(pos2(sc.x, sc.y + 18.0), 2.0, ACCENT);
        }
        if sresp.clicked() {
            self.pending.push(Action::ToggleShuffle);
        }
        if let Some(i) = playlist {
            let dc = pos2(ar.left() + 140.0, ar.center().y);
            let dresp = ui.interact(Rect::from_center_size(dc, vec2(36.0, 36.0)), Id::new("pl_more"), Sense::click()).on_hover_text("More options");
            dots(&p, dc, 26.0, if dresp.hovered() { TEXT } else { SUBTLE });
            let pid = Id::new("pl_more_popup");
            if dresp.clicked() {
                ui.memory_mut(|m| m.toggle_popup(pid));
            }
            egui::popup::popup_below_widget(ui, pid, &dresp, egui::PopupCloseBehavior::CloseOnClick, |ui| {
                ui.set_min_width(170.0);
                if ui.button("Edit details").clicked() {
                    self.pending.push(Action::EditPlaylist(i));
                }
                if ui.button("Add songs").clicked() {
                    self.pending.push(Action::Go(View::Search));
                }
                if ui.button("Delete playlist").clicked() {
                    self.pending.push(Action::DeletePlaylist(i));
                }
            });
        }
        ui.add_space(8.0);

        if ids.is_empty() {
            ui.add_space(30.0);
            ui.vertical_centered(|ui| {
                ui.label(RichText::new("Nothing here yet").font(bold(22.0)));
                ui.label(RichText::new("Find songs you love and add them here. Right-click any song for options.").color(SUBTLE));
                ui.add_space(10.0);
                if pill_button(ui, "Find songs", 140.0, 40.0, TEXT, BG).clicked() {
                    self.pending.push(Action::Go(View::Search));
                }
            });
            return;
        }
        self.track_table(ui, &ids, table, true);
    }

    fn track_table(&mut self, ui: &mut Ui, ids: &[String], kind: TableKind, show_album: bool) {
        let w = ui.available_width();
        let p = ui.painter().clone();
        let album_x = w * 0.52;
        let (hr, _) = ui.allocate_exact_size(vec2(w, 32.0), Sense::hover());
        p.text(pos2(hr.left() + 22.0, hr.center().y), Align2::CENTER_CENTER, "#", reg(13.0), SUBTLE);
        p.text(pos2(hr.left() + 52.0, hr.center().y), Align2::LEFT_CENTER, "Title", reg(13.0), SUBTLE);
        if show_album {
            p.text(pos2(hr.left() + album_x, hr.center().y), Align2::LEFT_CENTER, "Album", reg(13.0), SUBTLE);
        }
        p.text(pos2(hr.right() - 30.0, hr.center().y), Align2::RIGHT_CENTER, "Time", reg(13.0), SUBTLE);
        p.line_segment([pos2(hr.left(), hr.bottom()), pos2(hr.right(), hr.bottom())], Stroke::new(1.0, Color32::from_white_alpha(20)));
        ui.add_space(6.0);
        let time = ui.input(|i| i.time);
        let playlists: Vec<String> = self.data.playlists.iter().map(|p| p.name.clone()).collect();

        for (row, id) in ids.iter().enumerate() {
            let Some(t) = self.track(id).cloned() else { continue };
            let (r, resp) = ui.allocate_exact_size(vec2(w, 56.0), Sense::click());
            if !ui.is_rect_visible(r) {
                continue;
            }
            let is_cur = self.current.as_deref() == Some(id.as_str());
            let hovered = resp.hovered() || resp.context_menu_opened();
            if hovered {
                p.rect_filled(r, cr(6), Color32::from_white_alpha(16));
            }
            let nc = pos2(r.left() + 22.0, r.center().y);
            let num_resp = ui.interact(Rect::from_center_size(nc, vec2(32.0, 32.0)), Id::new(("row_play", row, id)), Sense::click());
            if hovered || num_resp.hovered() {
                if is_cur && self.playing {
                    pause(&p, nc, 14.0, TEXT);
                } else {
                    play(&p, nc, 14.0, TEXT);
                }
            } else if is_cur && self.playing {
                for k in 0..3 {
                    let hh = 4.0 + 10.0 * (0.5 + 0.5 * ((time * 6.0 + k as f64 * 1.7).sin() as f32));
                    p.rect_filled(Rect::from_center_size(pos2(nc.x - 5.0 + k as f32 * 5.0, nc.y + 7.0 - hh / 2.0), vec2(3.0, hh)), cr(1), ACCENT);
                }
            } else {
                p.text(nc, Align2::CENTER_CENTER, format!("{}", row + 1), reg(15.0), if is_cur { ACCENT } else { SUBTLE });
            }
            if num_resp.clicked() {
                self.pending.push(if is_cur { Action::TogglePlay } else { Action::PlayList(ids.to_vec(), row) });
            }
            let cvr = Rect::from_min_size(pos2(r.left() + 48.0, r.center().y - 20.0), vec2(40.0, 40.0));
            draw_art(&p, cvr, &Art::Cover(t.hue, t.album.clone()));
            let title_w = if show_album { album_x - 110.0 } else { w - 260.0 };
            fit_text(&p, pos2(cvr.right() + 12.0, r.center().y - 1.0), Align2::LEFT_BOTTOM, &t.title, reg(15.5), if is_cur { ACCENT } else { TEXT }, title_w);
            fit_text(&p, pos2(cvr.right() + 12.0, r.center().y + 2.0), Align2::LEFT_TOP, &t.artist, reg(13.5), SUBTLE, title_w);
            if show_album {
                fit_text(&p, pos2(r.left() + album_x, r.center().y), Align2::LEFT_CENTER, &t.album, reg(14.0), SUBTLE, w - album_x - 140.0);
            }
            let liked = self.data.liked.contains(id);
            let hc = pos2(r.right() - 100.0, r.center().y);
            let hresp = ui.interact(Rect::from_center_size(hc, vec2(28.0, 28.0)), Id::new(("row_like", row, id)), Sense::click());
            if liked {
                heart(&p, hc, 15.0, ACCENT, true);
            } else if hovered || hresp.hovered() {
                heart(&p, hc, 15.0, if hresp.hovered() { TEXT } else { SUBTLE }, false);
            }
            if hresp.clicked() {
                self.pending.push(Action::ToggleLike(id.clone()));
            }
            p.text(pos2(r.right() - 30.0, r.center().y), Align2::RIGHT_CENTER, fmt_time(t.duration), reg(14.0), SUBTLE);
            if resp.double_clicked() {
                self.pending.push(Action::PlayList(ids.to_vec(), row));
            }
            resp.context_menu(|ui| {
                ui.set_min_width(210.0);
                if ui.button("Play").clicked() {
                    self.pending.push(Action::PlayList(ids.to_vec(), row));
                    ui.close_menu();
                }
                if ui.button("Add to queue").clicked() {
                    self.pending.push(Action::Queue(id.clone()));
                    ui.close_menu();
                }
                let like_label = if liked { "Remove from Liked Songs" } else { "Save to Liked Songs" };
                if ui.button(like_label).clicked() {
                    self.pending.push(Action::ToggleLike(id.clone()));
                    ui.close_menu();
                }
                ui.menu_button("Add to playlist", |ui| {
                    if ui.button("+ New playlist").clicked() {
                        self.pending.push(Action::NewPlaylist(Some(id.clone())));
                        ui.close_menu();
                    }
                    if !playlists.is_empty() {
                        ui.separator();
                    }
                    for (pi, name) in playlists.iter().enumerate() {
                        if ui.button(name).clicked() {
                            self.pending.push(Action::AddToPlaylist(id.clone(), pi));
                            ui.close_menu();
                        }
                    }
                });
                if let TableKind::Playlist(pi) = kind {
                    if ui.button("Remove from this playlist").clicked() {
                        self.pending.push(Action::RemoveFromPlaylist(pi, row));
                        ui.close_menu();
                    }
                }
                ui.separator();
                if ui.button("Go to album").clicked() {
                    self.pending.push(Action::Go(View::Album(t.album.clone())));
                    ui.close_menu();
                }
            });
        }
    }

    fn search_view(&mut self, ui: &mut Ui) {
        let q = self.search.trim().to_lowercase();
        if q.is_empty() {
            ui.add_space(8.0);
            ui.label(RichText::new("Browse all").font(bold(24.0)));
            ui.add_space(12.0);
            let genres: [(&str, f32); 7] = [("Electronic", 0.74), ("Chill", 0.11), ("Lo-fi", 0.53), ("Ambient", 0.03), ("Dance", 0.9), ("Made for you", 0.35), ("Local files", 0.48)];
            let w = ui.available_width();
            let gap = 16.0;
            let cols = (((w + gap) / (220.0 + gap)).floor() as usize).max(2);
            let tw = (w - gap * (cols as f32 - 1.0)) / cols as f32;
            for row in genres.chunks(cols) {
                ui.horizontal(|ui| {
                    ui.spacing_mut().item_spacing.x = gap;
                    for (g, hue) in row {
                        let (r, resp) = ui.allocate_exact_size(vec2(tw, tw * 0.55), Sense::click());
                        let p = ui.painter().with_clip_rect(r);
                        p.rect_filled(r, cr(8), hsv(*hue, 0.6, if resp.hovered() { 0.75 } else { 0.62 }));
                        let art = Rect::from_min_size(pos2(r.right() - tw * 0.3, r.bottom() - tw * 0.26), vec2(tw * 0.32, tw * 0.32));
                        cover(&p, art, *hue + 0.05, g);
                        p.text(r.left_top() + vec2(16.0, 14.0), Align2::LEFT_TOP, *g, bold(22.0), TEXT);
                        if resp.clicked() {
                            if *g == "Made for you" {
                                self.pending.push(Action::Go(View::Mix(0)));
                            } else if *g == "Local files" {
                                self.pending.push(if self.data.local.is_empty() { Action::AddFolder } else { Action::Go(View::Local) });
                            } else {
                                self.search = g.to_string();
                            }
                        }
                    }
                });
                ui.add_space(gap - 6.0);
            }
            return;
        }

        let songs: Vec<String> = self
            .tracks
            .iter()
            .filter(|t| t.title.to_lowercase().contains(&q) || t.artist.to_lowercase().contains(&q) || t.album.to_lowercase().contains(&q) || t.genre.to_lowercase().contains(&q))
            .map(|t| t.id.clone())
            .collect();
        let albums: Vec<CardItem> = self
            .albums
            .iter()
            .filter(|a| a.name.to_lowercase().contains(&q) || a.artist.to_lowercase().contains(&q) || a.tracks.iter().any(|id| songs.contains(id)))
            .map(|a| CardItem { title: a.name.clone(), subtitle: a.artist.clone(), art: Art::Cover(a.hue, a.name.clone()), view: View::Album(a.name.clone()) })
            .collect();
        let pls: Vec<CardItem> = self
            .data
            .playlists
            .iter()
            .enumerate()
            .filter(|(_, p)| p.name.to_lowercase().contains(&q))
            .map(|(i, p)| CardItem { title: p.name.clone(), subtitle: format!("{} songs", p.tracks.len()), art: Art::Cover(p.hue, p.name.clone()), view: View::Playlist(i) })
            .collect();
        if songs.is_empty() && albums.is_empty() && pls.is_empty() {
            ui.add_space(60.0);
            ui.vertical_centered(|ui| {
                ui.label(RichText::new(format!("No results found for \"{}\"", self.search.trim())).font(bold(22.0)));
                ui.label(RichText::new("Check the spelling, or try different words.").color(SUBTLE));
            });
            return;
        }
        if !songs.is_empty() {
            ui.add_space(4.0);
            ui.label(RichText::new("Songs").font(bold(22.0)));
            ui.add_space(4.0);
            let shown: Vec<String> = songs.into_iter().take(40).collect();
            self.track_table(ui, &shown, TableKind::Plain, true);
            ui.add_space(16.0);
        }
        self.shelf(ui, "Albums", albums, true);
        self.shelf(ui, "Your playlists", pls, true);
    }

    fn library_view(&mut self, ui: &mut Ui) {
        ui.add_space(4.0);
        ui.label(RichText::new("Your Library").font(bold(30.0)));
        ui.add_space(10.0);
        ui.horizontal(|ui| {
            for (f, label) in [(LibFilter::All, "All"), (LibFilter::Playlists, "Playlists"), (LibFilter::Albums, "Albums"), (LibFilter::Local, "Local files")] {
                if chip(ui, label, self.lib_filter == f).clicked() {
                    self.lib_filter = f;
                }
            }
            ui.add_space(12.0);
            if chip(ui, "+ New playlist", false).clicked() {
                self.pending.push(Action::NewPlaylist(None));
            }
            if chip(ui, "+ Add music folder", false).clicked() {
                self.pending.push(Action::AddFolder);
            }
        });
        ui.add_space(14.0);

        let mut items: Vec<CardItem> = vec![];
        let f = self.lib_filter;
        if f == LibFilter::All || f == LibFilter::Playlists {
            items.push(CardItem { title: "Liked Songs".into(), subtitle: format!("{} songs", self.data.liked.len()), art: Art::Liked, view: View::Liked });
            for (i, p) in self.data.playlists.iter().enumerate() {
                items.push(CardItem { title: p.name.clone(), subtitle: format!("Playlist · {} songs", p.tracks.len()), art: Art::Cover(p.hue, p.name.clone()), view: View::Playlist(i) });
            }
        }
        if f == LibFilter::All || f == LibFilter::Local {
            if !self.data.local.is_empty() {
                items.push(CardItem { title: "Local files".into(), subtitle: format!("{} songs", self.data.local.len()), art: Art::Local, view: View::Local });
            }
            for a in self.albums.iter().filter(|a| a.local) {
                items.push(CardItem { title: a.name.clone(), subtitle: format!("Album · {}", a.artist), art: Art::Cover(a.hue, a.name.clone()), view: View::Album(a.name.clone()) });
            }
        }
        if f == LibFilter::All || f == LibFilter::Albums {
            for a in self.albums.iter().filter(|a| !a.local) {
                items.push(CardItem { title: a.name.clone(), subtitle: format!("Album · {}", a.artist), art: Art::Cover(a.hue, a.name.clone()), view: View::Album(a.name.clone()) });
            }
        }
        if f == LibFilter::Local && self.data.local.is_empty() {
            ui.add_space(30.0);
            ui.vertical_centered(|ui| {
                ui.label(RichText::new("Play music from your computer").font(bold(22.0)));
                ui.label(RichText::new("Pick a folder with MP3, FLAC, WAV, OGG or M4A files and it will show up here.").color(SUBTLE));
                ui.add_space(10.0);
                if pill_button(ui, "Choose a folder", 170.0, 40.0, TEXT, BG).clicked() {
                    self.pending.push(Action::AddFolder);
                }
            });
            return;
        }
        let w = ui.available_width();
        let gap = 12.0;
        let cols = (((w + gap) / (180.0 + gap)).floor() as usize).max(2);
        let cw = (w - gap * (cols as f32 - 1.0)) / cols as f32;
        for row in items.chunks(cols) {
            ui.horizontal(|ui| {
                ui.spacing_mut().item_spacing.x = gap;
                for it in row {
                    self.card(ui, it, cw);
                }
            });
            ui.add_space(6.0);
        }
    }

    fn local_view(&mut self, ui: &mut Ui) {
        let ids = self.ids_for(&View::Local);
        let sub = format!("{} songs on this computer", ids.len());
        self.collection_view(ui, "Folder", "Local files".into(), sub, String::new(), Art::Local, ids, TableKind::Plain, None);
        ui.add_space(20.0);
        ui.label(RichText::new("Music folders").font(bold(18.0)));
        let folders = self.data.folders.clone();
        for (i, f) in folders.iter().enumerate() {
            ui.horizontal(|ui| {
                ui.label(RichText::new(f.display().to_string()).color(SUBTLE));
                if ui.small_button("Rescan").clicked() {
                    self.pending.push(Action::RescanFolder(f.clone()));
                }
                if ui.small_button("Remove").clicked() {
                    self.pending.push(Action::RemoveFolder(i));
                }
            });
        }
        ui.add_space(6.0);
        if chip(ui, "+ Add another folder", false).clicked() {
            self.pending.push(Action::AddFolder);
        }
    }

    fn queue_view(&mut self, ui: &mut Ui) {
        ui.add_space(4.0);
        ui.label(RichText::new("Queue").font(bold(30.0)));
        ui.add_space(12.0);
        let Some(cur) = self.current.clone() else {
            ui.label(RichText::new("Nothing is playing yet. Pick a song to get started.").color(SUBTLE));
            return;
        };
        ui.label(RichText::new("Now playing").font(bold(17.0)).color(SUBTLE));
        self.track_table(ui, &[cur], TableKind::Plain, true);
        if !self.queue.is_empty() {
            ui.add_space(16.0);
            ui.horizontal(|ui| {
                ui.label(RichText::new("Next in queue").font(bold(17.0)).color(SUBTLE));
                if ui.small_button("Clear").clicked() {
                    self.queue.clear();
                }
            });
            let q: Vec<String> = self.queue.iter().cloned().collect();
            self.track_table(ui, &q, TableKind::Plain, true);
        }
        if !self.context.is_empty() {
            ui.add_space(16.0);
            ui.label(RichText::new(if self.shuffle { "Next up (shuffle is on)" } else { "Next up" }).font(bold(17.0)).color(SUBTLE));
            let upcoming: Vec<String> = self.context.iter().skip(self.ctx_pos + 1).take(30).cloned().collect();
            if upcoming.is_empty() {
                ui.label(RichText::new("End of the list.").color(SUBTLE));
            } else {
                self.track_table(ui, &upcoming, TableKind::Plain, true);
            }
        }
    }

    fn account_view(&mut self, ui: &mut Ui) {
        let Some(user) = self.user.clone() else { return };
        let w = ui.available_width();
        let (hr, _) = ui.allocate_exact_size(vec2(w, 210.0), Sense::hover());
        let p = ui.painter().clone();
        let ac = pos2(hr.left() + 96.0, hr.center().y);
        p.circle_filled(ac + vec2(0.0, 6.0), 92.0, Color32::from_black_alpha(80));
        p.circle_filled(ac, 92.0, hsv(library::hue_of(&user.username), 0.55, 0.9));
        let initial = user.display_name.chars().next().unwrap_or('?').to_uppercase().to_string();
        p.text(ac, Align2::CENTER_CENTER, initial, bold(78.0), BG);
        let tx = hr.left() + 220.0;
        p.text(pos2(tx, hr.center().y - 44.0), Align2::LEFT_BOTTOM, "Profile", bold(13.0), TEXT);
        fit_text(&p, pos2(tx, hr.center().y + 26.0), Align2::LEFT_BOTTOM, &user.display_name, bold(60.0), TEXT, hr.right() - tx);
        let meta = format!("@{} · {} playlists · {} liked songs · Member since {}", user.username, self.data.playlists.len(), self.data.liked.len(), member_since(user.created));
        fit_text(&p, pos2(tx, hr.center().y + 54.0), Align2::LEFT_BOTTOM, &meta, reg(14.0), SUBTLE, hr.right() - tx);
        ui.add_space(20.0);

        let box_w = (w - 16.0) / 2.0;
        ui.horizontal_top(|ui| {
            ui.spacing_mut().item_spacing.x = 16.0;
            section_box(ui, box_w, |ui| {
                ui.label(RichText::new("Your plan").font(bold(18.0)));
                ui.add_space(4.0);
                ui.label(RichText::new("Free forever · Ad-free").font(bold(24.0)).color(ACCENT));
                ui.add_space(4.0);
                for line in ["No ads between songs, ever", "Unlimited skips", "Play your own music files", "Unlimited playlists"] {
                    ui.horizontal(|ui| {
                        ui.label(RichText::new("✓").color(ACCENT));
                        ui.label(RichText::new(line).color(SUBTLE));
                    });
                }
            });
            section_box(ui, box_w, |ui| {
                ui.label(RichText::new("Edit profile").font(bold(18.0)));
                ui.add_space(4.0);
                field_label(ui, "Display name");
                ui.add(text_field(&mut self.acct_name, "Your name", false, box_w - 40.0));
                ui.add_space(8.0);
                if pill_button(ui, "Save name", 130.0, 36.0, TEXT, BG).clicked() {
                    let n = self.acct_name.trim().to_string();
                    if n.is_empty() {
                        self.acct_msg = Some(("Name can't be empty.".into(), false));
                    } else {
                        self.accounts.rename(&user.username, &n);
                        self.save_accounts();
                        if let Some(u) = &mut self.user {
                            u.display_name = n;
                        }
                        self.acct_msg = Some(("Name saved.".into(), true));
                    }
                }
            });
        });
        ui.add_space(16.0);
        ui.horizontal_top(|ui| {
            ui.spacing_mut().item_spacing.x = 16.0;
            section_box(ui, box_w, |ui| {
                ui.label(RichText::new("Change password").font(bold(18.0)));
                ui.add_space(4.0);
                field_label(ui, "Current password");
                ui.add(text_field(&mut self.acct_old, "", true, box_w - 40.0));
                field_label(ui, "New password");
                ui.add(text_field(&mut self.acct_new, "At least 6 characters", true, box_w - 40.0));
                ui.add_space(8.0);
                if pill_button(ui, "Update password", 160.0, 36.0, TEXT, BG).clicked() {
                    match self.accounts.change_password(&user.username, &self.acct_old, &self.acct_new) {
                        Ok(()) => {
                            self.save_accounts();
                            self.acct_old.clear();
                            self.acct_new.clear();
                            self.acct_msg = Some(("Password updated.".into(), true));
                        }
                        Err(e) => self.acct_msg = Some((e, false)),
                    }
                }
            });
            section_box(ui, box_w, |ui| {
                ui.label(RichText::new("Session").font(bold(18.0)));
                ui.add_space(4.0);
                ui.label(RichText::new("Sign out of this computer. Your playlists and likes stay saved with your account.").color(SUBTLE));
                ui.add_space(8.0);
                if pill_button(ui, "Sign out", 120.0, 36.0, TEXT, BG).clicked() {
                    self.pending.push(Action::SignOut);
                }
                ui.add_space(14.0);
                let red = Color32::from_rgb(255, 110, 110);
                if !self.confirm_delete {
                    if ui.add(egui::Button::new(RichText::new("Delete account").color(red)).frame(false)).clicked() {
                        self.confirm_delete = true;
                    }
                } else {
                    ui.label(RichText::new("This removes your account, playlists and likes from this computer.").color(red));
                    ui.horizontal(|ui| {
                        if ui.button(RichText::new("Yes, delete it").color(red)).clicked() {
                            self.accounts.delete(&user.username);
                            if !self.ephemeral {
                                UserData::delete(&self.data_dir, &user.username);
                            }
                            self.save_accounts();
                            self.pending.push(Action::SignOut);
                        }
                        if ui.button("Cancel").clicked() {
                            self.confirm_delete = false;
                        }
                    });
                }
            });
        });
        if let Some((m, ok)) = &self.acct_msg {
            ui.add_space(10.0);
            ui.label(RichText::new(m).color(if *ok { ACCENT } else { Color32::from_rgb(255, 110, 110) }));
        }
    }
}

toolu_01CpFxYKHAZpwEw3Fg4XHmKD.content:
use super::widgets::*;
use super::*;
use crate::accounts::member_since;

impl WaveletApp {
    pub(super) fn view_content(&mut self, ui: &mut Ui) {
        match self.view.clone() {
            View::Home => self.home_view(ui),
            View::Search => self.search_view(ui),
            View::Library => self.library_view(ui),
            View::Liked => {
                let name = self.user.as_ref().map(|u| u.display_name.clone()).unwrap_or_default();
                let ids = self.data.liked.clone();
                let sub = format!("{name} · {} songs", ids.len());
                self.collection_view(ui, "Playlist", "Liked Songs".into(), sub, String::new(), Art::Liked, ids, TableKind::Plain, None);
            }
            View::Playlist(i) => {
                let Some(pl) = self.data.playlists.get(i).cloned() else {
                    ui.label("This playlist no longer exists.");
                    return;
                };
                let name = self.user.as_ref().map(|u| u.display_name.clone()).unwrap_or_default();
                let total: f32 = pl.tracks.iter().filter_map(|id| self.track(id)).map(|t| t.duration).sum();
                let sub = format!("{name} · {} songs, {}", pl.tracks.len(), long_time(total));
                self.collection_view(ui, "Playlist", pl.name.clone(), sub, pl.description.clone(), Art::Cover(pl.hue, pl.name.clone()), pl.tracks.clone(), TableKind::Playlist(i), Some(i));
            }
            View::Album(a) => {
                let Some(al) = self.albums.iter().find(|x| x.name == a).cloned() else {
                    ui.label("Album not found.");
                    return;
                };
                let total: f32 = al.tracks.iter().filter_map(|id| self.track(id)).map(|t| t.duration).sum();
                let sub = format!("{} · {} songs, {}", al.artist, al.tracks.len(), long_time(total));
                let kind = if al.local { "Album · On this computer" } else { "Album" };
                self.collection_view(ui, kind, al.name.clone(), sub, String::new(), Art::Cover(al.hue, al.name.clone()), al.tracks.clone(), TableKind::Plain, None);
            }
            View::Mix(i) => {
                let Some(m) = self.mixes.get(i) else { return };
                let (name, desc, hue, ids) = (m.name.clone(), m.desc.clone(), m.hue, m.ids.clone());
                let sub = format!("Made for you · {} songs", ids.len());
                self.collection_view(ui, "Mix", name.clone(), sub, desc, Art::Cover(hue, name), ids, TableKind::Plain, None);
            }
            View::Local => self.local_view(ui),
            View::Queue => self.queue_view(ui),
            View::Account => self.account_view(ui),
        }
    }

    fn home_view(&mut self, ui: &mut Ui) {
        let first = self.user.as_ref().map(|u| u.display_name.split_whitespace().next().unwrap_or("").to_string()).unwrap_or_default();
        ui.add_space(4.0);
        ui.label(RichText::new(format!("Welcome back, {first}")).font(bold(30.0)));
        ui.add_space(14.0);

        let mut tiles: Vec<CardItem> = vec![CardItem { title: "Liked Songs".into(), subtitle: String::new(), art: Art::Liked, view: View::Liked }];
        for (i, p) in self.data.playlists.iter().enumerate().take(3) {
            tiles.push(CardItem { title: p.name.clone(), subtitle: String::new(), art: Art::Cover(p.hue, p.name.clone()), view: View::Playlist(i) });
        }
        for (i, m) in self.mixes.iter().enumerate() {
            if tiles.len() >= 6 {
                break;
            }
            tiles.push(CardItem { title: m.name.clone(), subtitle: String::new(), art: Art::Cover(m.hue, m.name.clone()), view: View::Mix(i) });
        }
        for a in self.albums.iter().filter(|a| !a.local) {
            if tiles.len() >= 6 {
                break;
            }
            tiles.push(CardItem { title: a.name.clone(), subtitle: String::new(), art: Art::Cover(a.hue, a.name.clone()), view: View::Album(a.name.clone()) });
        }
        let w = ui.available_width();
        let gap = 12.0;
        let cols = if w > 900.0 { 3 } else { 2 };
        let tw = (w - gap * (cols as f32 - 1.0)) / cols as f32;
        for row in tiles.chunks(cols) {
            ui.horizontal(|ui| {
                ui.spacing_mut().item_spacing.x = gap;
                for t in row {
                    self.quick_tile(ui, t, tw);
                }
            });
            ui.add_space(4.0);
        }

        ui.add_space(20.0);
        let mixes: Vec<CardItem> = self
            .mixes
            .iter()
            .enumerate()
            .map(|(i, m)| CardItem { title: m.name.clone(), subtitle: m.desc.clone(), art: Art::Cover(m.hue, m.name.clone()), view: View::Mix(i) })
            .collect();
        let name = self.user.as_ref().map(|u| u.display_name.clone()).unwrap_or_default();
        self.shelf(ui, &format!("Made for {name}"), mixes, false);

        let mut recent_albums: Vec<String> = vec![];
        for id in &self.data.recent {
            if let Some(t) = self.track(id) {
                if !recent_albums.contains(&t.album) {
                    recent_albums.push(t.album.clone());
                }
            }
        }
        if !recent_albums.is_empty() {
            let items: Vec<CardItem> = recent_albums
                .iter()
                .filter_map(|n| self.albums.iter().find(|a| &a.name == n))
                .map(|a| CardItem { title: a.name.clone(), subtitle: a.artist.clone(), art: Art::Cover(a.hue, a.name.clone()), view: View::Album(a.name.clone()) })
                .collect();
            self.shelf(ui, "Recently played", items, false);
        }

        let items: Vec<CardItem> = self
            .albums
            .iter()
            .filter(|a| !a.local)
            .map(|a| CardItem { title: a.name.clone(), subtitle: a.artist.clone(), art: Art::Cover(a.hue, a.name.clone()), view: View::Album(a.name.clone()) })
            .collect();
        self.shelf(ui, "Albums to explore", items, true);

        let local: Vec<CardItem> = self
            .albums
            .iter()
            .filter(|a| a.local)
            .map(|a| CardItem { title: a.name.clone(), subtitle: a.artist.clone(), art: Art::Cover(a.hue, a.name.clone()), view: View::Album(a.name.clone()) })
            .collect();
        if !local.is_empty() {
            self.shelf(ui, "From your computer", local, true);
        }
    }

    fn quick_tile(&mut self, ui: &mut Ui, t: &CardItem, w: f32) {
        let (r, resp) = ui.allocate_exact_size(vec2(w, 64.0), Sense::click());
        let p = ui.painter().clone();
        p.rect_filled(r, cr(6), if resp.hovered() { Color32::from_white_alpha(40) } else { Color32::from_white_alpha(18) });
        let cvr = Rect::from_min_size(r.min, vec2(64.0, 64.0));
        draw_art(&p, cvr, &t.art);
        fit_text(&p, pos2(cvr.right() + 14.0, r.center().y), Align2::LEFT_CENTER, &t.title, bold(15.0), TEXT, w - 64.0 - 76.0);
        let ids = self.ids_for(&t.view);
        let playing_this = self.playing && !ids.is_empty() && self.context == ids;
        if resp.hovered() || playing_this {
            let c = pos2(r.right() - 32.0, r.center().y);
            let pr = Rect::from_center_size(c, vec2(40.0, 40.0));
            let presp = ui.interact(pr, Id::new(("qt_play", &t.title)), Sense::click());
            p.circle_filled(c, if presp.hovered() { 21.0 } else { 20.0 }, if presp.hovered() { ACCENT_HI } else { ACCENT });
            if playing_this {
                pause(&p, c, 14.0, BG);
            } else {
                play(&p, pos2(c.x + 1.0, c.y), 14.0, BG);
            }
            if presp.clicked() {
                self.pending.push(if playing_this { Action::TogglePlay } else { Action::PlayList(ids, 0) });
                return;
            }
        }
        if resp.clicked() {
            self.pending.push(Action::Go(t.view.clone()));
        }
    }

    fn shelf(&mut self, ui: &mut Ui, title: &str, items: Vec<CardItem>, wrap: bool) {
        if items.is_empty() {
            return;
        }
        ui.add_space(8.0);
        ui.label(RichText::new(title).font(bold(22.0)));
        ui.add_space(8.0);
        let w = ui.available_width();
        let gap = 12.0;
        let cols = (((w + gap) / (180.0 + gap)).floor() as usize).max(2);
        let cw = (w - gap * (cols as f32 - 1.0)) / cols as f32;
        let take = if wrap { items.len() } else { cols.min(items.len()) };
        for row in items[..take].chunks(cols) {
            ui.horizontal(|ui| {
                ui.spacing_mut().item_spacing.x = gap;
                for it in row {
                    self.card(ui, it, cw);
                }
            });
            ui.add_space(6.0);
        }
        ui.add_space(14.0);
    }

    fn card(&mut self, ui: &mut Ui, it: &CardItem, w: f32) {
        let h = w + 50.0;
        let (r, resp) = ui.allocate_exact_size(vec2(w, h), Sense::click());
        let p = ui.painter().clone();
        if resp.hovered() {
            p.rect_filled(r, cr(8), Color32::from_white_alpha(14));
        }
        let pad = 10.0;
        let cvr = Rect::from_min_size(r.min + vec2(pad, pad), vec2(w - 2.0 * pad, w - 2.0 * pad));
        p.rect_filled(cvr.translate(vec2(0.0, 4.0)), cr(6), Color32::from_black_alpha(60));
        draw_art(&p, cvr, &it.art);
        fit_text(&p, pos2(cvr.left(), cvr.bottom() + 10.0), Align2::LEFT_TOP, &it.title, bold(15.0), TEXT, cvr.width());
        fit_text(&p, pos2(cvr.left(), cvr.bottom() + 31.0), Align2::LEFT_TOP, &it.subtitle, reg(13.0), SUBTLE, cvr.width());
        if resp.hovered() {
            let c = pos2(cvr.right() - 28.0, cvr.bottom() - 28.0);
            let pr = Rect::from_center_size(c, vec2(46.0, 46.0));
            let presp = ui.interact(pr, Id::new(("card_play", &it.title)), Sense::click());
            p.circle_filled(c + vec2(0.0, 2.0), 23.0, Color32::from_black_alpha(90));
            p.circle_filled(c, 23.0, if presp.hovered() { ACCENT_HI } else { ACCENT });
            play(&p, pos2(c.x + 1.5, c.y), 16.0, BG);
            if presp.clicked() {
                let ids = self.ids_for(&it.view);
                self.pending.push(Action::PlayList(ids, 0));
                return;
            }
        }
        if resp.clicked() {
            self.pending.push(Action::Go(it.view.clone()));
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn collection_view(&mut self, ui: &mut Ui, kind: &str, title: String, sub: String, desc: String, art: Art, ids: Vec<String>, table: TableKind, playlist: Option<usize>) {
        let w = ui.available_width();
        let (hr, _) = ui.allocate_exact_size(vec2(w, 220.0), Sense::hover());
        let p = ui.painter().clone();
        let cv = Rect::from_min_size(pos2(hr.left(), hr.top() + 10.0), vec2(200.0, 200.0));
        p.rect_filled(cv.translate(vec2(0.0, 6.0)), cr(4), Color32::from_black_alpha(90));
        draw_art(&p, cv, &art);
        let tx = cv.right() + 24.0;
        let tw = hr.right() - tx;
        p.text(pos2(tx, cv.top() + 64.0), Align2::LEFT_BOTTOM, kind, bold(13.0), TEXT);
        let size = if title.chars().count() > 18 { 40.0 } else { 64.0 };
        fit_text(&p, pos2(tx - 2.0, cv.top() + 138.0), Align2::LEFT_BOTTOM, &title, bold(size), TEXT, tw);
        if !desc.is_empty() {
            fit_text(&p, pos2(tx, cv.top() + 168.0), Align2::LEFT_BOTTOM, &desc, reg(14.0), SUBTLE, tw);
        }
        fit_text(&p, pos2(tx, cv.bottom()), Align2::LEFT_BOTTOM, &sub, reg(14.0), TEXT, tw);
        if let Some(i) = playlist {
            let tr = Rect::from_min_max(pos2(tx, cv.top() + 70.0), pos2(hr.right(), cv.top() + 140.0));
            if ui.interact(tr, Id::new("pl_title"), Sense::click()).on_hover_text("Edit details").clicked() {
                self.pending.push(Action::EditPlaylist(i));
            }
        }

        ui.add_space(16.0);
        let (ar, _) = ui.allocate_exact_size(vec2(w, 64.0), Sense::hover());
        let c = pos2(ar.left() + 30.0, ar.center().y);
        let presp = ui.interact(Rect::from_center_size(c, vec2(58.0, 58.0)), Id::new("big_play"), Sense::click());
        let this_ctx = !ids.is_empty() && self.context == ids && self.current.is_some();
        p.circle_filled(c, if presp.hovered() { 30.0 } else { 28.0 }, if ids.is_empty() { FAINT } else if presp.hovered() { ACCENT_HI } else { ACCENT });
        if this_ctx && self.playing {
            pause(&p, c, 20.0, BG);
        } else {
            play(&p, pos2(c.x + 2.0, c.y), 20.0, BG);
        }
        if presp.clicked() && !ids.is_empty() {
            self.pending.push(if this_ctx { Action::TogglePlay } else { Action::PlayList(ids.clone(), 0) });
        }
        let sc = pos2(ar.left() + 90.0, ar.center().y);
        let sresp = ui.interact(Rect::from_center_size(sc, vec2(36.0, 36.0)), Id::new("big_shuffle"), Sense::click()).on_hover_text("Shuffle");
        shuffle(&p, sc, 26.0, if self.shuffle { ACCENT } else if sresp.hovered() { TEXT } else { SUBTLE });
        if self.shuffle {
            p.circle_filled(pos2(sc.x, sc.y + 18.0), 2.0, ACCENT);
        }
        if sresp.clicked() {
            self.pending.push(Action::ToggleShuffle);
        }
        if let Some(i) = playlist {
            let dc = pos2(ar.left() + 140.0, ar.center().y);
            let dresp = ui.interact(Rect::from_center_size(dc, vec2(36.0, 36.0)), Id::new("pl_more"), Sense::click()).on_hover_text("More options");
            dots(&p, dc, 26.0, if dresp.hovered() { TEXT } else { SUBTLE });
            let pid = Id::new("pl_more_popup");
            if dresp.clicked() {
                ui.memory_mut(|m| m.toggle_popup(pid));
            }
            egui::popup::popup_below_widget(ui, pid, &dresp, egui::PopupCloseBehavior::CloseOnClick, |ui| {
                ui.set_min_width(170.0);
                if ui.button("Edit details").clicked() {
                    self.pending.push(Action::EditPlaylist(i));
                }
                if ui.button("Add songs").clicked() {
                    self.pending.push(Action::Go(View::Search));
                }
                if ui.button("Delete playlist").clicked() {
                    self.pending.push(Action::DeletePlaylist(i));
                }
            });
        }
        ui.add_space(8.0);

        if ids.is_empty() {
            ui.add_space(30.0);
            ui.vertical_centered(|ui| {
                ui.label(RichText::new("Nothing here yet").font(bold(22.0)));
                ui.label(RichText::new("Find songs you love and add them here. Right-click any song for options.").color(SUBTLE));
                ui.add_space(10.0);
                if pill_button(ui, "Find songs", 140.0, 40.0, TEXT, BG).clicked() {
                    self.pending.push(Action::Go(View::Search));
                }
            });
            return;
        }
        self.track_table(ui, &ids, table, true);
    }

    fn track_table(&mut self, ui: &mut Ui, ids: &[String], kind: TableKind, show_album: bool) {
        let w = ui.available_width();
        let p = ui.painter().clone();
        let album_x = w * 0.52;
        let (hr, _) = ui.allocate_exact_size(vec2(w, 32.0), Sense::hover());
        p.text(pos2(hr.left() + 22.0, hr.center().y), Align2::CENTER_CENTER, "#", reg(13.0), SUBTLE);
        p.text(pos2(hr.left() + 52.0, hr.center().y), Align2::LEFT_CENTER, "Title", reg(13.0), SUBTLE);
        if show_album {
            p.text(pos2(hr.left() + album_x, hr.center().y), Align2::LEFT_CENTER, "Album", reg(13.0), SUBTLE);
        }
        p.text(pos2(hr.right() - 30.0, hr.center().y), Align2::RIGHT_CENTER, "Time", reg(13.0), SUBTLE);
        p.line_segment([pos2(hr.left(), hr.bottom()), pos2(hr.right(), hr.bottom())], Stroke::new(1.0, Color32::from_white_alpha(20)));
        ui.add_space(6.0);
        let time = ui.input(|i| i.time);
        let playlists: Vec<String> = self.data.playlists.iter().map(|p| p.name.clone()).collect();

        for (row, id) in ids.iter().enumerate() {
            let Some(t) = self.track(id).cloned() else { continue };
            let (r, resp) = ui.allocate_exact_size(vec2(w, 56.0), Sense::click());
            if !ui.is_rect_visible(r) {
                continue;
            }
            let is_cur = self.current.as_deref() == Some(id.as_str());
            let hovered = resp.hovered() || resp.context_menu_opened();
            if hovered {
                p.rect_filled(r, cr(6), Color32::from_white_alpha(16));
            }
            let nc = pos2(r.left() + 22.0, r.center().y);
            let num_resp = ui.interact(Rect::from_center_size(nc, vec2(32.0, 32.0)), Id::new(("row_play", row, id)), Sense::click());
            if hovered || num_resp.hovered() {
                if is_cur && self.playing {
                    pause(&p, nc, 14.0, TEXT);
                } else {
                    play(&p, nc, 14.0, TEXT);
                }
            } else if is_cur && self.playing {
                for k in 0..3 {
                    let hh = 4.0 + 10.0 * (0.5 + 0.5 * ((time * 6.0 + k as f64 * 1.7).sin() as f32));
                    p.rect_filled(Rect::from_center_size(pos2(nc.x - 5.0 + k as f32 * 5.0, nc.y + 7.0 - hh / 2.0), vec2(3.0, hh)), cr(1), ACCENT);
                }
            } else {
                p.text(nc, Align2::CENTER_CENTER, format!("{}", row + 1), reg(15.0), if is_cur { ACCENT } else { SUBTLE });
            }
            if num_resp.clicked() {
                self.pending.push(if is_cur { Action::TogglePlay } else { Action::PlayList(ids.to_vec(), row) });
            }
            let cvr = Rect::from_min_size(pos2(r.left() + 48.0, r.center().y - 20.0), vec2(40.0, 40.0));
            draw_art(&p, cvr, &Art::Cover(t.hue, t.album.clone()));
            let title_w = if show_album { album_x - 110.0 } else { w - 260.0 };
            fit_text(&p, pos2(cvr.right() + 12.0, r.center().y - 1.0), Align2::LEFT_BOTTOM, &t.title, reg(15.5), if is_cur { ACCENT } else { TEXT }, title_w);
            fit_text(&p, pos2(cvr.right() + 12.0, r.center().y + 2.0), Align2::LEFT_TOP, &t.artist, reg(13.5), SUBTLE, title_w);
            if show_album {
                fit_text(&p, pos2(r.left() + album_x, r.center().y), Align2::LEFT_CENTER, &t.album, reg(14.0), SUBTLE, w - album_x - 140.0);
            }
            let liked = self.data.liked.contains(id);
            let hc = pos2(r.right() - 100.0, r.center().y);
            let hresp = ui.interact(Rect::from_center_size(hc, vec2(28.0, 28.0)), Id::new(("row_like", row, id)), Sense::click());
            if liked {
                heart(&p, hc, 15.0, ACCENT, true);
            } else if hovered || hresp.hovered() {
                heart(&p, hc, 15.0, if hresp.hovered() { TEXT } else { SUBTLE }, false);
            }
            if hresp.clicked() {
                self.pending.push(Action::ToggleLike(id.clone()));
            }
            p.text(pos2(r.right() - 30.0, r.center().y), Align2::RIGHT_CENTER, fmt_time(t.duration), reg(14.0), SUBTLE);
            if resp.double_clicked() {
                self.pending.push(Action::PlayList(ids.to_vec(), row));
            }
            resp.context_menu(|ui| {
                ui.set_min_width(210.0);
                if ui.button("Play").clicked() {
                    self.pending.push(Action::PlayList(ids.to_vec(), row));
                    ui.close_menu();
                }
                if ui.button("Add to queue").clicked() {
                    self.pending.push(Action::Queue(id.clone()));
                    ui.close_menu();
                }
                let like_label = if liked { "Remove from Liked Songs" } else { "Save to Liked Songs" };
                if ui.button(like_label).clicked() {
                    self.pending.push(Action::ToggleLike(id.clone()));
                    ui.close_menu();
                }
                ui.menu_button("Add to playlist", |ui| {
                    if ui.button("+ New playlist").clicked() {
                        self.pending.push(Action::NewPlaylist(Some(id.clone())));
                        ui.close_menu();
                    }
                    if !playlists.is_empty() {
                        ui.separator();
                    }
                    for (pi, name) in playlists.iter().enumerate() {
                        if ui.button(name).clicked() {
                            self.pending.push(Action::AddToPlaylist(id.clone(), pi));
                            ui.close_menu();
                        }
                    }
                });
                if let TableKind::Playlist(pi) = kind {
                    if ui.button("Remove from this playlist").clicked() {
                        self.pending.push(Action::RemoveFromPlaylist(pi, row));
                        ui.close_menu();
                    }
                }
                ui.separator();
                if ui.button("Go to album").clicked() {
                    self.pending.push(Action::Go(View::Album(t.album.clone())));
                    ui.close_menu();
                }
            });
        }
    }

    fn search_view(&mut self, ui: &mut Ui) {
        let q = self.search.trim().to_lowercase();
        if q.is_empty() {
            ui.add_space(8.0);
            ui.label(RichText::new("Browse all").font(bold(24.0)));
            ui.add_space(12.0);
            let genres: [(&str, f32); 7] = [("Electronic", 0.74), ("Chill", 0.11), ("Lo-fi", 0.53), ("Ambient", 0.03), ("Dance", 0.9), ("Made for you", 0.35), ("Local files", 0.48)];
            let w = ui.available_width();
            let gap = 16.0;
            let cols = (((w + gap) / (220.0 + gap)).floor() as usize).max(2);
            let tw = (w - gap * (cols as f32 - 1.0)) / cols as f32;
            for row in genres.chunks(cols) {
                ui.horizontal(|ui| {
                    ui.spacing_mut().item_spacing.x = gap;
                    for (g, hue) in row {
                        let (r, resp) = ui.allocate_exact_size(vec2(tw, tw * 0.55), Sense::click());
                        let p = ui.painter().with_clip_rect(r);
                        p.rect_filled(r, cr(8), hsv(*hue, 0.6, if resp.hovered() { 0.75 } else { 0.62 }));
                        let art = Rect::from_min_size(pos2(r.right() - tw * 0.3, r.bottom() - tw * 0.26), vec2(tw * 0.32, tw * 0.32));
                        cover(&p, art, *hue + 0.05, g);
                        p.text(r.left_top() + vec2(16.0, 14.0), Align2::LEFT_TOP, *g, bold(22.0), TEXT);
                        if resp.clicked() {
                            if *g == "Made for you" {
                                self.pending.push(Action::Go(View::Mix(0)));
                            } else if *g == "Local files" {
                                self.pending.push(if self.data.local.is_empty() { Action::AddFolder } else { Action::Go(View::Local) });
                            } else {
                                self.search = g.to_string();
                            }
                        }
                    }
                });
                ui.add_space(gap - 6.0);
            }
            return;
        }

        let songs: Vec<String> = self
            .tracks
            .iter()
            .filter(|t| t.title.to_lowercase().contains(&q) || t.artist.to_lowercase().contains(&q) || t.album.to_lowercase().contains(&q) || t.genre.to_lowercase().contains(&q))
            .map(|t| t.id.clone())
            .collect();
        let albums: Vec<CardItem> = self
            .albums
            .iter()
            .filter(|a| a.name.to_lowercase().contains(&q) || a.artist.to_lowercase().contains(&q) || a.tracks.iter().any(|id| songs.contains(id)))
            .map(|a| CardItem { title: a.name.clone(), subtitle: a.artist.clone(), art: Art::Cover(a.hue, a.name.clone()), view: View::Album(a.name.clone()) })
            .collect();
        let pls: Vec<CardItem> = self
            .data
            .playlists
            .iter()
            .enumerate()
            .filter(|(_, p)| p.name.to_lowercase().contains(&q))
            .map(|(i, p)| CardItem { title: p.name.clone(), subtitle: format!("{} songs", p.tracks.len()), art: Art::Cover(p.hue, p.name.clone()), view: View::Playlist(i) })
            .collect();
        if songs.is_empty() && albums.is_empty() && pls.is_empty() {
            ui.add_space(60.0);
            ui.vertical_centered(|ui| {
                ui.label(RichText::new(format!("No results found for \"{}\"", self.search.trim())).font(bold(22.0)));
                ui.label(RichText::new("Check the spelling, or try different words.").color(SUBTLE));
            });
            return;
        }
        if !songs.is_empty() {
            ui.add_space(4.0);
            ui.label(RichText::new("Songs").font(bold(22.0)));
            ui.add_space(4.0);
            let shown: Vec<String> = songs.into_iter().take(40).collect();
            self.track_table(ui, &shown, TableKind::Plain, true);
            ui.add_space(16.0);
        }
        self.shelf(ui, "Albums", albums, true);
        self.shelf(ui, "Your playlists", pls, true);
    }

    fn library_view(&mut self, ui: &mut Ui) {
        ui.add_space(4.0);
        ui.label(RichText::new("Your Library").font(bold(30.0)));
        ui.add_space(10.0);
        ui.horizontal(|ui| {
            for (f, label) in [(LibFilter::All, "All"), (LibFilter::Playlists, "Playlists"), (LibFilter::Albums, "Albums"), (LibFilter::Local, "Local files")] {
                if chip(ui, label, self.lib_filter == f).clicked() {
                    self.lib_filter = f;
                }
            }
            ui.add_space(12.0);
            if chip(ui, "+ New playlist", false).clicked() {
                self.pending.push(Action::NewPlaylist(None));
            }
            if chip(ui, "+ Add music folder", false).clicked() {
                self.pending.push(Action::AddFolder);
            }
        });
        ui.add_space(14.0);

        let mut items: Vec<CardItem> = vec![];
        let f = self.lib_filter;
        if f == LibFilter::All || f == LibFilter::Playlists {
            items.push(CardItem { title: "Liked Songs".into(), subtitle: format!("{} songs", self.data.liked.len()), art: Art::Liked, view: View::Liked });
            for (i, p) in self.data.playlists.iter().enumerate() {
                items.push(CardItem { title: p.name.clone(), subtitle: format!("Playlist · {} songs", p.tracks.len()), art: Art::Cover(p.hue, p.name.clone()), view: View::Playlist(i) });
            }
        }
        if f == LibFilter::All || f == LibFilter::Local {
            if !self.data.local.is_empty() {
                items.push(CardItem { title: "Local files".into(), subtitle: format!("{} songs", self.data.local.len()), art: Art::Local, view: View::Local });
            }
            for a in self.albums.iter().filter(|a| a.local) {
                items.push(CardItem { title: a.name.clone(), subtitle: format!("Album · {}", a.artist), art: Art::Cover(a.hue, a.name.clone()), view: View::Album(a.name.clone()) });
            }
        }
        if f == LibFilter::All || f == LibFilter::Albums {
            for a in self.albums.iter().filter(|a| !a.local) {
                items.push(CardItem { title: a.name.clone(), subtitle: format!("Album · {}", a.artist), art: Art::Cover(a.hue, a.name.clone()), view: View::Album(a.name.clone()) });
            }
        }
        if f == LibFilter::Local && self.data.local.is_empty() {
            ui.add_space(30.0);
            ui.vertical_centered(|ui| {
                ui.label(RichText::new("Play music from your computer").font(bold(22.0)));
                ui.label(RichText::new("Pick a folder with MP3, FLAC, WAV, OGG or M4A files and it will show up here.").color(SUBTLE));
                ui.add_space(10.0);
                if pill_button(ui, "Choose a folder", 170.0, 40.0, TEXT, BG).clicked() {
                    self.pending.push(Action::AddFolder);
                }
            });
            return;
        }
        let w = ui.available_width();
        let gap = 12.0;
        let cols = (((w + gap) / (180.0 + gap)).floor() as usize).max(2);
        let cw = (w - gap * (cols as f32 - 1.0)) / cols as f32;
        for row in items.chunks(cols) {
            ui.horizontal(|ui| {
                ui.spacing_mut().item_spacing.x = gap;
                for it in row {
                    self.card(ui, it, cw);
                }
            });
            ui.add_space(6.0);
        }
    }

    fn local_view(&mut self, ui: &mut Ui) {
        let ids = self.ids_for(&View::Local);
        let sub = format!("{} songs on this computer", ids.len());
        self.collection_view(ui, "Folder", "Local files".into(), sub, String::new(), Art::Local, ids, TableKind::Plain, None);
        ui.add_space(20.0);
        ui.label(RichText::new("Music folders").font(bold(18.0)));
        let folders = self.data.folders.clone();
        for (i, f) in folders.iter().enumerate() {
            ui.horizontal(|ui| {
                ui.label(RichText::new(f.display().to_string()).color(SUBTLE));
                if ui.small_button("Rescan").clicked() {
                    self.pending.push(Action::RescanFolder(f.clone()));
                }
                if ui.small_button("Remove").clicked() {
                    self.pending.push(Action::RemoveFolder(i));
                }
            });
        }
        ui.add_space(6.0);
        if chip(ui, "+ Add another folder", false).clicked() {
            self.pending.push(Action::AddFolder);
        }
    }

    fn queue_view(&mut self, ui: &mut Ui) {
        ui.add_space(4.0);
        ui.label(RichText::new("Queue").font(bold(30.0)));
        ui.add_space(12.0);
        let Some(cur) = self.current.clone() else {
            ui.label(RichText::new("Nothing is playing yet. Pick a song to get started.").color(SUBTLE));
            return;
        };
        ui.label(RichText::new("Now playing").font(bold(17.0)).color(SUBTLE));
        self.track_table(ui, &[cur], TableKind::Plain, true);
        if !self.queue.is_empty() {
            ui.add_space(16.0);
            ui.horizontal(|ui| {
                ui.label(RichText::new("Next in queue").font(bold(17.0)).color(SUBTLE));
                if ui.small_button("Clear").clicked() {
                    self.queue.clear();
                }
            });
            let q: Vec<String> = self.queue.iter().cloned().collect();
            self.track_table(ui, &q, TableKind::Plain, true);
        }
        if !self.context.is_empty() {
            ui.add_space(16.0);
            ui.label(RichText::new(if self.shuffle { "Next up (shuffle is on)" } else { "Next up" }).font(bold(17.0)).color(SUBTLE));
            let upcoming: Vec<String> = self.context.iter().skip(self.ctx_pos + 1).take(30).cloned().collect();
            if upcoming.is_empty() {
                ui.label(RichText::new("End of the list.").color(SUBTLE));
            } else {
                self.track_table(ui, &upcoming, TableKind::Plain, true);
            }
        }
    }

    fn account_view(&mut self, ui: &mut Ui) {
        let Some(user) = self.user.clone() else { return };
        let w = ui.available_width();
        let (hr, _) = ui.allocate_exact_size(vec2(w, 210.0), Sense::hover());
        let p = ui.painter().clone();
        let ac = pos2(hr.left() + 96.0, hr.center().y);
        p.circle_filled(ac + vec2(0.0, 6.0), 92.0, Color32::from_black_alpha(80));
        p.circle_filled(ac, 92.0, hsv(library::hue_of(&user.username), 0.55, 0.9));
        let initial = user.display_name.chars().next().unwrap_or('?').to_uppercase().to_string();
        p.text(ac, Align2::CENTER_CENTER, initial, bold(78.0), BG);
        let tx = hr.left() + 220.0;
        p.text(pos2(tx, hr.center().y - 44.0), Align2::LEFT_BOTTOM, "Profile", bold(13.0), TEXT);
        fit_text(&p, pos2(tx, hr.center().y + 26.0), Align2::LEFT_BOTTOM, &user.display_name, bold(60.0), TEXT, hr.right() - tx);
        let meta = format!("@{} · {} playlists · {} liked songs · Member since {}", user.username, self.data.playlists.len(), self.data.liked.len(), member_since(user.created));
        fit_text(&p, pos2(tx, hr.center().y + 54.0), Align2::LEFT_BOTTOM, &meta, reg(14.0), SUBTLE, hr.right() - tx);
        ui.add_space(20.0);

        let box_w = (w - 16.0) / 2.0;
        ui.horizontal_top(|ui| {
            ui.spacing_mut().item_spacing.x = 16.0;
            section_box(ui, box_w, |ui| {
                ui.label(RichText::new("Your plan").font(bold(18.0)));
                ui.add_space(4.0);
                ui.label(RichText::new("Free forever · Ad-free").font(bold(24.0)).color(ACCENT));
                ui.add_space(4.0);
                for line in ["No ads between songs, ever", "Unlimited skips", "Play your own music files", "Unlimited playlists"] {
                    ui.horizontal(|ui| {
                        ui.label(RichText::new("✓").color(ACCENT));
                        ui.label(RichText::new(line).color(SUBTLE));
                    });
                }
            });
            section_box(ui, box_w, |ui| {
                ui.label(RichText::new("Edit profile").font(bold(18.0)));
                ui.add_space(4.0);
                field_label(ui, "Display name");
                ui.add(text_field(&mut self.acct_name, "Your name", false, box_w - 40.0));
                ui.add_space(8.0);
                if pill_button(ui, "Save name", 130.0, 36.0, TEXT, BG).clicked() {
                    let n = self.acct_name.trim().to_string();
                    if n.is_empty() {
                        self.acct_msg = Some(("Name can't be empty.".into(), false));
                    } else {
                        self.accounts.rename(&user.username, &n);
                        self.save_accounts();
                        if let Some(u) = &mut self.user {
                            u.display_name = n;
                        }
                        self.acct_msg = Some(("Name saved.".into(), true));
                    }
                }
            });
        });
        ui.add_space(16.0);
        ui.horizontal_top(|ui| {
            ui.spacing_mut().item_spacing.x = 16.0;
            section_box(ui, box_w, |ui| {
                ui.label(RichText::new("Change password").font(bold(18.0)));
                ui.add_space(4.0);
                field_label(ui, "Current password");
                ui.add(text_field(&mut self.acct_old, "", true, box_w - 40.0));
                field_label(ui, "New password");
                ui.add(text_field(&mut self.acct_new, "At least 6 characters", true, box_w - 40.0));
                ui.add_space(8.0);
                if pill_button(ui, "Update password", 160.0, 36.0, TEXT, BG).clicked() {
                    match self.accounts.change_password(&user.username, &self.acct_old, &self.acct_new) {
                        Ok(()) => {
                            self.save_accounts();
                            self.acct_old.clear();
                            self.acct_new.clear();
                            self.acct_msg = Some(("Password updated.".into(), true));
                        }
                        Err(e) => self.acct_msg = Some((e, false)),
                    }
                }
            });
            section_box(ui, box_w, |ui| {
                ui.label(RichText::new("Session").font(bold(18.0)));
                ui.add_space(4.0);
                ui.label(RichText::new("Sign out of this computer. Your playlists and likes stay saved with your account.").color(SUBTLE));
                ui.add_space(8.0);
                if pill_button(ui, "Sign out", 120.0, 36.0, TEXT, BG).clicked() {
                    self.pending.push(Action::SignOut);
                }
                ui.add_space(14.0);
                let red = Color32::from_rgb(255, 110, 110);
                if !self.confirm_delete {
                    if ui.add(egui::Button::new(RichText::new("Delete account").color(red)).frame(false)).clicked() {
                        self.confirm_delete = true;
                    }
                } else {
                    ui.label(RichText::new("This removes your account, playlists and likes from this computer.").color(red));
                    ui.horizontal(|ui| {
                        if ui.button(RichText::new("Yes, delete it").color(red)).clicked() {
                            self.accounts.delete(&user.username);
                            if !self.ephemeral {
                                UserData::delete(&self.data_dir, &user.username);
                            }
                            self.save_accounts();
                            self.pending.push(Action::SignOut);
                        }
                        if ui.button("Cancel").clicked() {
                            self.confirm_delete = false;
                        }
                    });
                }
            });
        });
        if let Some((m, ok)) = &self.acct_msg {
            ui.add_space(10.0);
            ui.label(RichText::new(m).color(if *ok { ACCENT } else { Color32::from_rgb(255, 110, 110) }));
        }
    }
}

toolUseResult.content:
use super::widgets::*;
use super::*;
use crate::accounts::member_since;

impl WaveletApp {
    pub(super) fn view_content(&mut self, ui: &mut Ui) {
        match self.view.clone() {
            View::Home => self.home_view(ui),
            View::Search => self.search_view(ui),
            View::Library => self.library_view(ui),
            View::Liked => {
                let name = self.user.as_ref().map(|u| u.display_name.clone()).unwrap_or_default();
                let ids = self.data.liked.clone();
                let sub = format!("{name} · {} songs", ids.len());
                self.collection_view(ui, "Playlist", "Liked Songs".into(), sub, String::new(), Art::Liked, ids, TableKind::Plain, None);
            }
            View::Playlist(i) => {
                let Some(pl) = self.data.playlists.get(i).cloned() else {
                    ui.label("This playlist no longer exists.");
                    return;
                };
                let name = self.user.as_ref().map(|u| u.display_name.clone()).unwrap_or_default();
                let total: f32 = pl.tracks.iter().filter_map(|id| self.track(id)).map(|t| t.duration).sum();
                let sub = format!("{name} · {} songs, {}", pl.tracks.len(), long_time(total));
                self.collection_view(ui, "Playlist", pl.name.clone(), sub, pl.description.clone(), Art::Cover(pl.hue, pl.name.clone()), pl.tracks.clone(), TableKind::Playlist(i), Some(i));
            }
            View::Album(a) => {
                let Some(al) = self.albums.iter().find(|x| x.name == a).cloned() else {
                    ui.label("Album not found.");
                    return;
                };
                let total: f32 = al.tracks.iter().filter_map(|id| self.track(id)).map(|t| t.duration).sum();
                let sub = format!("{} · {} songs, {}", al.artist, al.tracks.len(), long_time(total));
                let kind = if al.local { "Album · On this computer" } else { "Album" };
                self.collection_view(ui, kind, al.name.clone(), sub, String::new(), Art::Cover(al.hue, al.name.clone()), al.tracks.clone(), TableKind::Plain, None);
            }
            View::Mix(i) => {
                let Some(m) = self.mixes.get(i) else { return };
                let (name, desc, hue, ids) = (m.name.clone(), m.desc.clone(), m.hue, m.ids.clone());
                let sub = format!("Made for you · {} songs", ids.len());
                self.collection_view(ui, "Mix", name.clone(), sub, desc, Art::Cover(hue, name), ids, TableKind::Plain, None);
            }
            View::Local => self.local_view(ui),
            View::Queue => self.queue_view(ui),
            View::Account => self.account_view(ui),
        }
    }

    fn home_view(&mut self, ui: &mut Ui) {
        let first = self.user.as_ref().map(|u| u.display_name.split_whitespace().next().unwrap_or("").to_string()).unwrap_or_default();
        ui.add_space(4.0);
        ui.label(RichText::new(format!("Welcome back, {first}")).font(bold(30.0)));
        ui.add_space(14.0);

        let mut tiles: Vec<CardItem> = vec![CardItem { title: "Liked Songs".into(), subtitle: String::new(), art: Art::Liked, view: View::Liked }];
        for (i, p) in self.data.playlists.iter().enumerate().take(3) {
            tiles.push(CardItem { title: p.name.clone(), subtitle: String::new(), art: Art::Cover(p.hue, p.name.clone()), view: View::Playlist(i) });
        }
        for (i, m) in self.mixes.iter().enumerate() {
            if tiles.len() >= 6 {
                break;
            }
            tiles.push(CardItem { title: m.name.clone(), subtitle: String::new(), art: Art::Cover(m.hue, m.name.clone()), view: View::Mix(i) });
        }
        for a in self.albums.iter().filter(|a| !a.local) {
            if tiles.len() >= 6 {
                break;
            }
            tiles.push(CardItem { title: a.name.clone(), subtitle: String::new(), art: Art::Cover(a.hue, a.name.clone()), view: View::Album(a.name.clone()) });
        }
        let w = ui.available_width();
        let gap = 12.0;
        let cols = if w > 900.0 { 3 } else { 2 };
        let tw = (w - gap * (cols as f32 - 1.0)) / cols as f32;
        for row in tiles.chunks(cols) {
            ui.horizontal(|ui| {
                ui.spacing_mut().item_spacing.x = gap;
                for t in row {
                    self.quick_tile(ui, t, tw);
                }
            });
            ui.add_space(4.0);
        }

        ui.add_space(20.0);
        let mixes: Vec<CardItem> = self
            .mixes
            .iter()
            .enumerate()
            .map(|(i, m)| CardItem { title: m.name.clone(), subtitle: m.desc.clone(), art: Art::Cover(m.hue, m.name.clone()), view: View::Mix(i) })
            .collect();
        let name = self.user.as_ref().map(|u| u.display_name.clone()).unwrap_or_default();
        self.shelf(ui, &format!("Made for {name}"), mixes, false);

        let mut recent_albums: Vec<String> = vec![];
        for id in &self.data.recent {
            if let Some(t) = self.track(id) {
                if !recent_albums.contains(&t.album) {
                    recent_albums.push(t.album.clone());
                }
            }
        }
        if !recent_albums.is_empty() {
            let items: Vec<CardItem> = recent_albums
                .iter()
                .filter_map(|n| self.albums.iter().find(|a| &a.name == n))
                .map(|a| CardItem { title: a.name.clone(), subtitle: a.artist.clone(), art: Art::Cover(a.hue, a.name.clone()), view: View::Album(a.name.clone()) })
                .collect();
            self.shelf(ui, "Recently played", items, false);
        }

        let items: Vec<CardItem> = self
            .albums
            .iter()
            .filter(|a| !a.local)
            .map(|a| CardItem { title: a.name.clone(), subtitle: a.artist.clone(), art: Art::Cover(a.hue, a.name.clone()), view: View::Album(a.name.clone()) })
            .collect();
        self.shelf(ui, "Albums to explore", items, true);

        let local: Vec<CardItem> = self
            .albums
            .iter()
            .filter(|a| a.local)
            .map(|a| CardItem { title: a.name.clone(), subtitle: a.artist.clone(), art: Art::Cover(a.hue, a.name.clone()), view: View::Album(a.name.clone()) })
            .collect();
        if !local.is_empty() {
            self.shelf(ui, "From your computer", local, true);
        }
    }

    fn quick_tile(&mut self, ui: &mut Ui, t: &CardItem, w: f32) {
        let (r, resp) = ui.allocate_exact_size(vec2(w, 64.0), Sense::click());
        let p = ui.painter().clone();
        p.rect_filled(r, cr(6), if resp.hovered() { Color32::from_white_alpha(40) } else { Color32::from_white_alpha(18) });
        let cvr = Rect::from_min_size(r.min, vec2(64.0, 64.0));
        draw_art(&p, cvr, &t.art);
        fit_text(&p, pos2(cvr.right() + 14.0, r.center().y), Align2::LEFT_CENTER, &t.title, bold(15.0), TEXT, w - 64.0 - 76.0);
        let ids = self.ids_for(&t.view);
        let playing_this = self.playing && !ids.is_empty() && self.context == ids;
        if resp.hovered() || playing_this {
            let c = pos2(r.right() - 32.0, r.center().y);
            let pr = Rect::from_center_size(c, vec2(40.0, 40.0));
            let presp = ui.interact(pr, Id::new(("qt_play", &t.title)), Sense::click());
            p.circle_filled(c, if presp.hovered() { 21.0 } else { 20.0 }, if presp.hovered() { ACCENT_HI } else { ACCENT });
            if playing_this {
                pause(&p, c, 14.0, BG);
            } else {
                play(&p, pos2(c.x + 1.0, c.y), 14.0, BG);
            }
            if presp.clicked() {
                self.pending.push(if playing_this { Action::TogglePlay } else { Action::PlayList(ids, 0) });
                return;
            }
        }
        if resp.clicked() {
            self.pending.push(Action::Go(t.view.clone()));
        }
    }

    fn shelf(&mut self, ui: &mut Ui, title: &str, items: Vec<CardItem>, wrap: bool) {
        if items.is_empty() {
            return;
        }
        ui.add_space(8.0);
        ui.label(RichText::new(title).font(bold(22.0)));
        ui.add_space(8.0);
        let w = ui.available_width();
        let gap = 12.0;
        let cols = (((w + gap) / (180.0 + gap)).floor() as usize).max(2);
        let cw = (w - gap * (cols as f32 - 1.0)) / cols as f32;
        let take = if wrap { items.len() } else { cols.min(items.len()) };
        for row in items[..take].chunks(cols) {
            ui.horizontal(|ui| {
                ui.spacing_mut().item_spacing.x = gap;
                for it in row {
                    self.card(ui, it, cw);
                }
            });
            ui.add_space(6.0);
        }
        ui.add_space(14.0);
    }

    fn card(&mut self, ui: &mut Ui, it: &CardItem, w: f32) {
        let h = w + 50.0;
        let (r, resp) = ui.allocate_exact_size(vec2(w, h), Sense::click());
        let p = ui.painter().clone();
        if resp.hovered() {
            p.rect_filled(r, cr(8), Color32::from_white_alpha(14));
        }
        let pad = 10.0;
        let cvr = Rect::from_min_size(r.min + vec2(pad, pad), vec2(w - 2.0 * pad, w - 2.0 * pad));
        p.rect_filled(cvr.translate(vec2(0.0, 4.0)), cr(6), Color32::from_black_alpha(60));
        draw_art(&p, cvr, &it.art);
        fit_text(&p, pos2(cvr.left(), cvr.bottom() + 10.0), Align2::LEFT_TOP, &it.title, bold(15.0), TEXT, cvr.width());
        fit_text(&p, pos2(cvr.left(), cvr.bottom() + 31.0), Align2::LEFT_TOP, &it.subtitle, reg(13.0), SUBTLE, cvr.width());
        if resp.hovered() {
            let c = pos2(cvr.right() - 28.0, cvr.bottom() - 28.0);
            let pr = Rect::from_center_size(c, vec2(46.0, 46.0));
            let presp = ui.interact(pr, Id::new(("card_play", &it.title)), Sense::click());
            p.circle_filled(c + vec2(0.0, 2.0), 23.0, Color32::from_black_alpha(90));
            p.circle_filled(c, 23.0, if presp.hovered() { ACCENT_HI } else { ACCENT });
            play(&p, pos2(c.x + 1.5, c.y), 16.0, BG);
            if presp.clicked() {
                let ids = self.ids_for(&it.view);
                self.pending.push(Action::PlayList(ids, 0));
                return;
            }
        }
        if resp.clicked() {
            self.pending.push(Action::Go(it.view.clone()));
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn collection_view(&mut self, ui: &mut Ui, kind: &str, title: String, sub: String, desc: String, art: Art, ids: Vec<String>, table: TableKind, playlist: Option<usize>) {
        let w = ui.available_width();
        let (hr, _) = ui.allocate_exact_size(vec2(w, 220.0), Sense::hover());
        let p = ui.painter().clone();
        let cv = Rect::from_min_size(pos2(hr.left(), hr.top() + 10.0), vec2(200.0, 200.0));
        p.rect_filled(cv.translate(vec2(0.0, 6.0)), cr(4), Color32::from_black_alpha(90));
        draw_art(&p, cv, &art);
        let tx = cv.right() + 24.0;
        let tw = hr.right() - tx;
        p.text(pos2(tx, cv.top() + 64.0), Align2::LEFT_BOTTOM, kind, bold(13.0), TEXT);
        let size = if title.chars().count() > 18 { 40.0 } else { 64.0 };
        fit_text(&p, pos2(tx - 2.0, cv.top() + 138.0), Align2::LEFT_BOTTOM, &title, bold(size), TEXT, tw);
        if !desc.is_empty() {
            fit_text(&p, pos2(tx, cv.top() + 168.0), Align2::LEFT_BOTTOM, &desc, reg(14.0), SUBTLE, tw);
        }
        fit_text(&p, pos2(tx, cv.bottom()), Align2::LEFT_BOTTOM, &sub, reg(14.0), TEXT, tw);
        if let Some(i) = playlist {
            let tr = Rect::from_min_max(pos2(tx, cv.top() + 70.0), pos2(hr.right(), cv.top() + 140.0));
            if ui.interact(tr, Id::new("pl_title"), Sense::click()).on_hover_text("Edit details").clicked() {
                self.pending.push(Action::EditPlaylist(i));
            }
        }

        ui.add_space(16.0);
        let (ar, _) = ui.allocate_exact_size(vec2(w, 64.0), Sense::hover());
        let c = pos2(ar.left() + 30.0, ar.center().y);
        let presp = ui.interact(Rect::from_center_size(c, vec2(58.0, 58.0)), Id::new("big_play"), Sense::click());
        let this_ctx = !ids.is_empty() && self.context == ids && self.current.is_some();
        p.circle_filled(c, if presp.hovered() { 30.0 } else { 28.0 }, if ids.is_empty() { FAINT } else if presp.hovered() { ACCENT_HI } else { ACCENT });
        if this_ctx && self.playing {
            pause(&p, c, 20.0, BG);
        } else {
            play(&p, pos2(c.x + 2.0, c.y), 20.0, BG);
        }
        if presp.clicked() && !ids.is_empty() {
            self.pending.push(if this_ctx { Action::TogglePlay } else { Action::PlayList(ids.clone(), 0) });
        }
        let sc = pos2(ar.left() + 90.0, ar.center().y);
        let sresp = ui.interact(Rect::from_center_size(sc, vec2(36.0, 36.0)), Id::new("big_shuffle"), Sense::click()).on_hover_text("Shuffle");
        shuffle(&p, sc, 26.0, if self.shuffle { ACCENT } else if sresp.hovered() { TEXT } else { SUBTLE });
        if self.shuffle {
            p.circle_filled(pos2(sc.x, sc.y + 18.0), 2.0, ACCENT);
        }
        if sresp.clicked() {
            self.pending.push(Action::ToggleShuffle);
        }
        if let Some(i) = playlist {
            let dc = pos2(ar.left() + 140.0, ar.center().y);
            let dresp = ui.interact(Rect::from_center_size(dc, vec2(36.0, 36.0)), Id::new("pl_more"), Sense::click()).on_hover_text("More options");
            dots(&p, dc, 26.0, if dresp.hovered() { TEXT } else { SUBTLE });
            let pid = Id::new("pl_more_popup");
            if dresp.clicked() {
                ui.memory_mut(|m| m.toggle_popup(pid));
            }
            egui::popup::popup_below_widget(ui, pid, &dresp, egui::PopupCloseBehavior::CloseOnClick, |ui| {
                ui.set_min_width(170.0);
                if ui.button("Edit details").clicked() {
                    self.pending.push(Action::EditPlaylist(i));
                }
                if ui.button("Add songs").clicked() {
                    self.pending.push(Action::Go(View::Search));
                }
                if ui.button("Delete playlist").clicked() {
                    self.pending.push(Action::DeletePlaylist(i));
                }
            });
        }
        ui.add_space(8.0);

        if ids.is_empty() {
            ui.add_space(30.0);
            ui.vertical_centered(|ui| {
                ui.label(RichText::new("Nothing here yet").font(bold(22.0)));
                ui.label(RichText::new("Find songs you love and add them here. Right-click any song for options.").color(SUBTLE));
                ui.add_space(10.0);
                if pill_button(ui, "Find songs", 140.0, 40.0, TEXT, BG).clicked() {
                    self.pending.push(Action::Go(View::Search));
                }
            });
            return;
        }
        self.track_table(ui, &ids, table, true);
    }

    fn track_table(&mut self, ui: &mut Ui, ids: &[String], kind: TableKind, show_album: bool) {
        let w = ui.available_width();
        let p = ui.painter().clone();
        let album_x = w * 0.52;
        let (hr, _) = ui.allocate_exact_size(vec2(w, 32.0), Sense::hover());
        p.text(pos2(hr.left() + 22.0, hr.center().y), Align2::CENTER_CENTER, "#", reg(13.0), SUBTLE);
        p.text(pos2(hr.left() + 52.0, hr.center().y), Align2::LEFT_CENTER, "Title", reg(13.0), SUBTLE);
        if show_album {
            p.text(pos2(hr.left() + album_x, hr.center().y), Align2::LEFT_CENTER, "Album", reg(13.0), SUBTLE);
        }
        p.text(pos2(hr.right() - 30.0, hr.center().y), Align2::RIGHT_CENTER, "Time", reg(13.0), SUBTLE);
        p.line_segment([pos2(hr.left(), hr.bottom()), pos2(hr.right(), hr.bottom())], Stroke::new(1.0, Color32::from_white_alpha(20)));
        ui.add_space(6.0);
        let time = ui.input(|i| i.time);
        let playlists: Vec<String> = self.data.playlists.iter().map(|p| p.name.clone()).collect();

        for (row, id) in ids.iter().enumerate() {
            let Some(t) = self.track(id).cloned() else { continue };
            let (r, resp) = ui.allocate_exact_size(vec2(w, 56.0), Sense::click());
            if !ui.is_rect_visible(r) {
                continue;
            }
            let is_cur = self.current.as_deref() == Some(id.as_str());
            let hovered = resp.hovered() || resp.context_menu_opened();
            if hovered {
                p.rect_filled(r, cr(6), Color32::from_white_alpha(16));
            }
            let nc = pos2(r.left() + 22.0, r.center().y);
            let num_resp = ui.interact(Rect::from_center_size(nc, vec2(32.0, 32.0)), Id::new(("row_play", row, id)), Sense::click());
            if hovered || num_resp.hovered() {
                if is_cur && self.playing {
                    pause(&p, nc, 14.0, TEXT);
                } else {
                    play(&p, nc, 14.0, TEXT);
                }
            } else if is_cur && self.playing {
                for k in 0..3 {
                    let hh = 4.0 + 10.0 * (0.5 + 0.5 * ((time * 6.0 + k as f64 * 1.7).sin() as f32));
                    p.rect_filled(Rect::from_center_size(pos2(nc.x - 5.0 + k as f32 * 5.0, nc.y + 7.0 - hh / 2.0), vec2(3.0, hh)), cr(1), ACCENT);
                }
            } else {
                p.text(nc, Align2::CENTER_CENTER, format!("{}", row + 1), reg(15.0), if is_cur { ACCENT } else { SUBTLE });
            }
            if num_resp.clicked() {
                self.pending.push(if is_cur { Action::TogglePlay } else { Action::PlayList(ids.to_vec(), row) });
            }
            let cvr = Rect::from_min_size(pos2(r.left() + 48.0, r.center().y - 20.0), vec2(40.0, 40.0));
            draw_art(&p, cvr, &Art::Cover(t.hue, t.album.clone()));
            let title_w = if show_album { album_x - 110.0 } else { w - 260.0 };
            fit_text(&p, pos2(cvr.right() + 12.0, r.center().y - 1.0), Align2::LEFT_BOTTOM, &t.title, reg(15.5), if is_cur { ACCENT } else { TEXT }, title_w);
            fit_text(&p, pos2(cvr.right() + 12.0, r.center().y + 2.0), Align2::LEFT_TOP, &t.artist, reg(13.5), SUBTLE, title_w);
            if show_album {
                fit_text(&p, pos2(r.left() + album_x, r.center().y), Align2::LEFT_CENTER, &t.album, reg(14.0), SUBTLE, w - album_x - 140.0);
            }
            let liked = self.data.liked.contains(id);
            let hc = pos2(r.right() - 100.0, r.center().y);
            let hresp = ui.interact(Rect::from_center_size(hc, vec2(28.0, 28.0)), Id::new(("row_like", row, id)), Sense::click());
            if liked {
                heart(&p, hc, 15.0, ACCENT, true);
            } else if hovered || hresp.hovered() {
                heart(&p, hc, 15.0, if hresp.hovered() { TEXT } else { SUBTLE }, false);
            }
            if hresp.clicked() {
                self.pending.push(Action::ToggleLike(id.clone()));
            }
            p.text(pos2(r.right() - 30.0, r.center().y), Align2::RIGHT_CENTER, fmt_time(t.duration), reg(14.0), SUBTLE);
            if resp.double_clicked() {
                self.pending.push(Action::PlayList(ids.to_vec(), row));
            }
            resp.context_menu(|ui| {
                ui.set_min_width(210.0);
                if ui.button("Play").clicked() {
                    self.pending.push(Action::PlayList(ids.to_vec(), row));
                    ui.close_menu();
                }
                if ui.button("Add to queue").clicked() {
                    self.pending.push(Action::Queue(id.clone()));
                    ui.close_menu();
                }
                let like_label = if liked { "Remove from Liked Songs" } else { "Save to Liked Songs" };
                if ui.button(like_label).clicked() {
                    self.pending.push(Action::ToggleLike(id.clone()));
                    ui.close_menu();
                }
                ui.menu_button("Add to playlist", |ui| {
                    if ui.button("+ New playlist").clicked() {
                        self.pending.push(Action::NewPlaylist(Some(id.clone())));
                        ui.close_menu();
                    }
                    if !playlists.is_empty() {
                        ui.separator();
                    }
                    for (pi, name) in playlists.iter().enumerate() {
                        if ui.button(name).clicked() {
                            self.pending.push(Action::AddToPlaylist(id.clone(), pi));
                            ui.close_menu();
                        }
                    }
                });
                if let TableKind::Playlist(pi) = kind {
                    if ui.button("Remove from this playlist").clicked() {
                        self.pending.push(Action::RemoveFromPlaylist(pi, row));
                        ui.close_menu();
                    }
                }
                ui.separator();
                if ui.button("Go to album").clicked() {
                    self.pending.push(Action::Go(View::Album(t.album.clone())));
                    ui.close_menu();
                }
            });
        }
    }

    fn search_view(&mut self, ui: &mut Ui) {
        let q = self.search.trim().to_lowercase();
        if q.is_empty() {
            ui.add_space(8.0);
            ui.label(RichText::new("Browse all").font(bold(24.0)));
            ui.add_space(12.0);
            let genres: [(&str, f32); 7] = [("Electronic", 0.74), ("Chill", 0.11), ("Lo-fi", 0.53), ("Ambient", 0.03), ("Dance", 0.9), ("Made for you", 0.35), ("Local files", 0.48)];
            let w = ui.available_width();
            let gap = 16.0;
            let cols = (((w + gap) / (220.0 + gap)).floor() as usize).max(2);
            let tw = (w - gap * (cols as f32 - 1.0)) / cols as f32;
            for row in genres.chunks(cols) {
                ui.horizontal(|ui| {
                    ui.spacing_mut().item_spacing.x = gap;
                    for (g, hue) in row {
                        let (r, resp) = ui.allocate_exact_size(vec2(tw, tw * 0.55), Sense::click());
                        let p = ui.painter().with_clip_rect(r);
                        p.rect_filled(r, cr(8), hsv(*hue, 0.6, if resp.hovered() { 0.75 } else { 0.62 }));
                        let art = Rect::from_min_size(pos2(r.right() - tw * 0.3, r.bottom() - tw * 0.26), vec2(tw * 0.32, tw * 0.32));
                        cover(&p, art, *hue + 0.05, g);
                        p.text(r.left_top() + vec2(16.0, 14.0), Align2::LEFT_TOP, *g, bold(22.0), TEXT);
                        if resp.clicked() {
                            if *g == "Made for you" {
                                self.pending.push(Action::Go(View::Mix(0)));
                            } else if *g == "Local files" {
                                self.pending.push(if self.data.local.is_empty() { Action::AddFolder } else { Action::Go(View::Local) });
                            } else {
                                self.search = g.to_string();
                            }
                        }
                    }
                });
                ui.add_space(gap - 6.0);
            }
            return;
        }

        let songs: Vec<String> = self
            .tracks
            .iter()
            .filter(|t| t.title.to_lowercase().contains(&q) || t.artist.to_lowercase().contains(&q) || t.album.to_lowercase().contains(&q) || t.genre.to_lowercase().contains(&q))
            .map(|t| t.id.clone())
            .collect();
        let albums: Vec<CardItem> = self
            .albums
            .iter()
            .filter(|a| a.name.to_lowercase().contains(&q) || a.artist.to_lowercase().contains(&q) || a.tracks.iter().any(|id| songs.contains(id)))
            .map(|a| CardItem { title: a.name.clone(), subtitle: a.artist.clone(), art: Art::Cover(a.hue, a.name.clone()), view: View::Album(a.name.clone()) })
            .collect();
        let pls: Vec<CardItem> = self
            .data
            .playlists
            .iter()
            .enumerate()
            .filter(|(_, p)| p.name.to_lowercase().contains(&q))
            .map(|(i, p)| CardItem { title: p.name.clone(), subtitle: format!("{} songs", p.tracks.len()), art: Art::Cover(p.hue, p.name.clone()), view: View::Playlist(i) })
            .collect();
        if songs.is_empty() && albums.is_empty() && pls.is_empty() {
            ui.add_space(60.0);
            ui.vertical_centered(|ui| {
                ui.label(RichText::new(format!("No results found for \"{}\"", self.search.trim())).font(bold(22.0)));
                ui.label(RichText::new("Check the spelling, or try different words.").color(SUBTLE));
            });
            return;
        }
        if !songs.is_empty() {
            ui.add_space(4.0);
            ui.label(RichText::new("Songs").font(bold(22.0)));
            ui.add_space(4.0);
            let shown: Vec<String> = songs.into_iter().take(40).collect();
            self.track_table(ui, &shown, TableKind::Plain, true);
            ui.add_space(16.0);
        }
        self.shelf(ui, "Albums", albums, true);
        self.shelf(ui, "Your playlists", pls, true);
    }

    fn library_view(&mut self, ui: &mut Ui) {
        ui.add_space(4.0);
        ui.label(RichText::new("Your Library").font(bold(30.0)));
        ui.add_space(10.0);
        ui.horizontal(|ui| {
            for (f, label) in [(LibFilter::All, "All"), (LibFilter::Playlists, "Playlists"), (LibFilter::Albums, "Albums"), (LibFilter::Local, "Local files")] {
                if chip(ui, label, self.lib_filter == f).clicked() {
                    self.lib_filter = f;
                }
            }
            ui.add_space(12.0);
            if chip(ui, "+ New playlist", false).clicked() {
                self.pending.push(Action::NewPlaylist(None));
            }
            if chip(ui, "+ Add music folder", false).clicked() {
                self.pending.push(Action::AddFolder);
            }
        });
        ui.add_space(14.0);

        let mut items: Vec<CardItem> = vec![];
        let f = self.lib_filter;
        if f == LibFilter::All || f == LibFilter::Playlists {
            items.push(CardItem { title: "Liked Songs".into(), subtitle: format!("{} songs", self.data.liked.len()), art: Art::Liked, view: View::Liked });
            for (i, p) in self.data.playlists.iter().enumerate() {
                items.push(CardItem { title: p.name.clone(), subtitle: format!("Playlist · {} songs", p.tracks.len()), art: Art::Cover(p.hue, p.name.clone()), view: View::Playlist(i) });
            }
        }
        if f == LibFilter::All || f == LibFilter::Local {
            if !self.data.local.is_empty() {
                items.push(CardItem { title: "Local files".into(), subtitle: format!("{} songs", self.data.local.len()), art: Art::Local, view: View::Local });
            }
            for a in self.albums.iter().filter(|a| a.local) {
                items.push(CardItem { title: a.name.clone(), subtitle: format!("Album · {}", a.artist), art: Art::Cover(a.hue, a.name.clone()), view: View::Album(a.name.clone()) });
            }
        }
        if f == LibFilter::All || f == LibFilter::Albums {
            for a in self.albums.iter().filter(|a| !a.local) {
                items.push(CardItem { title: a.name.clone(), subtitle: format!("Album · {}", a.artist), art: Art::Cover(a.hue, a.name.clone()), view: View::Album(a.name.clone()) });
            }
        }
        if f == LibFilter::Local && self.data.local.is_empty() {
            ui.add_space(30.0);
            ui.vertical_centered(|ui| {
                ui.label(RichText::new("Play music from your computer").font(bold(22.0)));
                ui.label(RichText::new("Pick a folder with MP3, FLAC, WAV, OGG or M4A files and it will show up here.").color(SUBTLE));
                ui.add_space(10.0);
                if pill_button(ui, "Choose a folder", 170.0, 40.0, TEXT, BG).clicked() {
                    self.pending.push(Action::AddFolder);
                }
            });
            return;
        }
        let w = ui.available_width();
        let gap = 12.0;
        let cols = (((w + gap) / (180.0 + gap)).floor() as usize).max(2);
        let cw = (w - gap * (cols as f32 - 1.0)) / cols as f32;
        for row in items.chunks(cols) {
            ui.horizontal(|ui| {
                ui.spacing_mut().item_spacing.x = gap;
                for it in row {
                    self.card(ui, it, cw);
                }
            });
            ui.add_space(6.0);
        }
    }

    fn local_view(&mut self, ui: &mut Ui) {
        let ids = self.ids_for(&View::Local);
        let sub = format!("{} songs on this computer", ids.len());
        self.collection_view(ui, "Folder", "Local files".into(), sub, String::new(), Art::Local, ids, TableKind::Plain, None);
        ui.add_space(20.0);
        ui.label(RichText::new("Music folders").font(bold(18.0)));
        let folders = self.data.folders.clone();
        for (i, f) in folders.iter().enumerate() {
            ui.horizontal(|ui| {
                ui.label(RichText::new(f.display().to_string()).color(SUBTLE));
                if ui.small_button("Rescan").clicked() {
                    self.pending.push(Action::RescanFolder(f.clone()));
                }
                if ui.small_button("Remove").clicked() {
                    self.pending.push(Action::RemoveFolder(i));
                }
            });
        }
        ui.add_space(6.0);
        if chip(ui, "+ Add another folder", false).clicked() {
            self.pending.push(Action::AddFolder);
        }
    }

    fn queue_view(&mut self, ui: &mut Ui) {
        ui.add_space(4.0);
        ui.label(RichText::new("Queue").font(bold(30.0)));
        ui.add_space(12.0);
        let Some(cur) = self.current.clone() else {
            ui.label(RichText::new("Nothing is playing yet. Pick a song to get started.").color(SUBTLE));
            return;
        };
        ui.label(RichText::new("Now playing").font(bold(17.0)).color(SUBTLE));
        self.track_table(ui, &[cur], TableKind::Plain, true);
        if !self.queue.is_empty() {
            ui.add_space(16.0);
            ui.horizontal(|ui| {
                ui.label(RichText::new("Next in queue").font(bold(17.0)).color(SUBTLE));
                if ui.small_button("Clear").clicked() {
                    self.queue.clear();
                }
            });
            let q: Vec<String> = self.queue.iter().cloned().collect();
            self.track_table(ui, &q, TableKind::Plain, true);
        }
        if !self.context.is_empty() {
            ui.add_space(16.0);
            ui.label(RichText::new(if self.shuffle { "Next up (shuffle is on)" } else { "Next up" }).font(bold(17.0)).color(SUBTLE));
            let upcoming: Vec<String> = self.context.iter().skip(self.ctx_pos + 1).take(30).cloned().collect();
            if upcoming.is_empty() {
                ui.label(RichText::new("End of the list.").color(SUBTLE));
            } else {
                self.track_table(ui, &upcoming, TableKind::Plain, true);
            }
        }
    }

    fn account_view(&mut self, ui: &mut Ui) {
        let Some(user) = self.user.clone() else { return };
        let w = ui.available_width();
        let (hr, _) = ui.allocate_exact_size(vec2(w, 210.0), Sense::hover());
        let p = ui.painter().clone();
        let ac = pos2(hr.left() + 96.0, hr.center().y);
        p.circle_filled(ac + vec2(0.0, 6.0), 92.0, Color32::from_black_alpha(80));
        p.circle_filled(ac, 92.0, hsv(library::hue_of(&user.username), 0.55, 0.9));
        let initial = user.display_name.chars().next().unwrap_or('?').to_uppercase().to_string();
        p.text(ac, Align2::CENTER_CENTER, initial, bold(78.0), BG);
        let tx = hr.left() + 220.0;
        p.text(pos2(tx, hr.center().y - 44.0), Align2::LEFT_BOTTOM, "Profile", bold(13.0), TEXT);
        fit_text(&p, pos2(tx, hr.center().y + 26.0), Align2::LEFT_BOTTOM, &user.display_name, bold(60.0), TEXT, hr.right() - tx);
        let meta = format!("@{} · {} playlists · {} liked songs · Member since {}", user.username, self.data.playlists.len(), self.data.liked.len(), member_since(user.created));
        fit_text(&p, pos2(tx, hr.center().y + 54.0), Align2::LEFT_BOTTOM, &meta, reg(14.0), SUBTLE, hr.right() - tx);
        ui.add_space(20.0);

        let box_w = (w - 16.0) / 2.0;
        ui.horizontal_top(|ui| {
            ui.spacing_mut().item_spacing.x = 16.0;
            section_box(ui, box_w, |ui| {
                ui.label(RichText::new("Your plan").font(bold(18.0)));
                ui.add_space(4.0);
                ui.label(RichText::new("Free forever · Ad-free").font(bold(24.0)).color(ACCENT));
                ui.add_space(4.0);
                for line in ["No ads between songs, ever", "Unlimited skips", "Play your own music files", "Unlimited playlists"] {
                    ui.horizontal(|ui| {
                        ui.label(RichText::new("✓").color(ACCENT));
                        ui.label(RichText::new(line).color(SUBTLE));
                    });
                }
            });
            section_box(ui, box_w, |ui| {
                ui.label(RichText::new("Edit profile").font(bold(18.0)));
                ui.add_space(4.0);
                field_label(ui, "Display name");
                ui.add(text_field(&mut self.acct_name, "Your name", false, box_w - 40.0));
                ui.add_space(8.0);
                if pill_button(ui, "Save name", 130.0, 36.0, TEXT, BG).clicked() {
                    let n = self.acct_name.trim().to_string();
                    if n.is_empty() {
                        self.acct_msg = Some(("Name can't be empty.".into(), false));
                    } else {
                        self.accounts.rename(&user.username, &n);
                        self.save_accounts();
                        if let Some(u) = &mut self.user {
                            u.display_name = n;
                        }
                        self.acct_msg = Some(("Name saved.".into(), true));
                    }
                }
            });
        });
        ui.add_space(16.0);
        ui.horizontal_top(|ui| {
            ui.spacing_mut().item_spacing.x = 16.0;
            section_box(ui, box_w, |ui| {
                ui.label(RichText::new("Change password").font(bold(18.0)));
                ui.add_space(4.0);
                field_label(ui, "Current password");
                ui.add(text_field(&mut self.acct_old, "", true, box_w - 40.0));
                field_label(ui, "New password");
                ui.add(text_field(&mut self.acct_new, "At least 6 characters", true, box_w - 40.0));
                ui.add_space(8.0);
                if pill_button(ui, "Update password", 160.0, 36.0, TEXT, BG).clicked() {
                    match self.accounts.change_password(&user.username, &self.acct_old, &self.acct_new) {
                        Ok(()) => {
                            self.save_accounts();
                            self.acct_old.clear();
                            self.acct_new.clear();
                            self.acct_msg = Some(("Password updated.".into(), true));
                        }
                        Err(e) => self.acct_msg = Some((e, false)),
                    }
                }
            });
            section_box(ui, box_w, |ui| {
                ui.label(RichText::new("Session").font(bold(18.0)));
                ui.add_space(4.0);
                ui.label(RichText::new("Sign out of this computer. Your playlists and likes stay saved with your account.").color(SUBTLE));
                ui.add_space(8.0);
                if pill_button(ui, "Sign out", 120.0, 36.0, TEXT, BG).clicked() {
                    self.pending.push(Action::SignOut);
                }
                ui.add_space(14.0);
                let red = Color32::from_rgb(255, 110, 110);
                if !self.confirm_delete {
                    if ui.add(egui::Button::new(RichText::new("Delete account").color(red)).frame(false)).clicked() {
                        self.confirm_delete = true;
                    }
                } else {
                    ui.label(RichText::new("This removes your account, playlists and likes from this computer.").color(red));
                    ui.horizontal(|ui| {
                        if ui.button(RichText::new("Yes, delete it").color(red)).clicked() {
                            self.accounts.delete(&user.username);
                            if !self.ephemeral {
                                UserData::delete(&self.data_dir, &user.username);
                            }
                            self.save_accounts();
                            self.pending.push(Action::SignOut);
                        }
                        if ui.button("Cancel").clicked() {
                            self.confirm_delete = false;
                        }
                    });
                }
            });
        });
        if let Some((m, ok)) = &self.acct_msg {
            ui.add_space(10.0);
            ui.label(RichText::new(m).color(if *ok { ACCENT } else { Color32::from_rgb(255, 110, 110) }));
        }
    }
}

input.content:
use super::widgets::*;
use super::*;
use crate::accounts::member_since;

impl WaveletApp {
    pub(super) fn view_content(&mut self, ui: &mut Ui) {
        match self.view.clone() {
            View::Home => self.home_view(ui),
            View::Search => self.search_view(ui),
            View::Library => self.library_view(ui),
            View::Liked => {
                let name = self.user.as_ref().map(|u| u.display_name.clone()).unwrap_or_default();
                let ids = self.data.liked.clone();
                let sub = format!("{name} · {} songs", ids.len());
                self.collection_view(ui, "Playlist", "Liked Songs".into(), sub, String::new(), Art::Liked, ids, TableKind::Plain, None);
            }
            View::Playlist(i) => {
                let Some(pl) = self.data.playlists.get(i).cloned() else {
                    ui.label("This playlist no longer exists.");
                    return;
                };
                let name = self.user.as_ref().map(|u| u.display_name.clone()).unwrap_or_default();
                let total: f32 = pl.tracks.iter().filter_map(|id| self.track(id)).map(|t| t.duration).sum();
                let sub = format!("{name} · {} songs, {}", pl.tracks.len(), long_time(total));
                self.collection_view(ui, "Playlist", pl.name.clone(), sub, pl.description.clone(), Art::Cover(pl.hue, pl.name.clone()), pl.tracks.clone(), TableKind::Playlist(i), Some(i));
            }
            View::Album(a) => {
                let Some(al) = self.albums.iter().find(|x| x.name == a).cloned() else {
                    ui.label("Album not found.");
                    return;
                };
                let total: f32 = al.tracks.iter().filter_map(|id| self.track(id)).map(|t| t.duration).sum();
                let sub = format!("{} · {} songs, {}", al.artist, al.tracks.len(), long_time(total));
                let kind = if al.local { "Album · On this computer" } else { "Album" };
                self.collection_view(ui, kind, al.name.clone(), sub, String::new(), Art::Cover(al.hue, al.name.clone()), al.tracks.clone(), TableKind::Plain, None);
            }
            View::Mix(i) => {
                let Some(m) = self.mixes.get(i) else { return };
                let (name, desc, hue, ids) = (m.name.clone(), m.desc.clone(), m.hue, m.ids.clone());
                let sub = format!("Made for you · {} songs", ids.len());
                self.collection_view(ui, "Mix", name.clone(), sub, desc, Art::Cover(hue, name), ids, TableKind::Plain, None);
            }
            View::Local => self.local_view(ui),
            View::Queue => self.queue_view(ui),
            View::Account => self.account_view(ui),
        }
    }

    fn home_view(&mut self, ui: &mut Ui) {
        let first = self.user.as_ref().map(|u| u.display_name.split_whitespace().next().unwrap_or("").to_string()).unwrap_or_default();
        ui.add_space(4.0);
        ui.label(RichText::new(format!("Welcome back, {first}")).font(bold(30.0)));
        ui.add_space(14.0);

        let mut tiles: Vec<CardItem> = vec![CardItem { title: "Liked Songs".into(), subtitle: String::new(), art: Art::Liked, view: View::Liked }];
        for (i, p) in self.data.playlists.iter().enumerate().take(3) {
            tiles.push(CardItem { title: p.name.clone(), subtitle: String::new(), art: Art::Cover(p.hue, p.name.clone()), view: View::Playlist(i) });
        }
        for (i, m) in self.mixes.iter().enumerate() {
            if tiles.len() >= 6 {
                break;
            }
            tiles.push(CardItem { title: m.name.clone(), subtitle: String::new(), art: Art::Cover(m.hue, m.name.clone()), view: View::Mix(i) });
        }
        for a in self.albums.iter().filter(|a| !a.local) {
            if tiles.len() >= 6 {
                break;
            }
            tiles.push(CardItem { title: a.name.clone(), subtitle: String::new(), art: Art::Cover(a.hue, a.name.clone()), view: View::Album(a.name.clone()) });
        }
        let w = ui.available_width();
        let gap = 12.0;
        let cols = if w > 900.0 { 3 } else { 2 };
        let tw = (w - gap * (cols as f32 - 1.0)) / cols as f32;
        for row in tiles.chunks(cols) {
            ui.horizontal(|ui| {
                ui.spacing_mut().item_spacing.x = gap;
                for t in row {
                    self.quick_tile(ui, t, tw);
                }
            });
            ui.add_space(4.0);
        }

        ui.add_space(20.0);
        let mixes: Vec<CardItem> = self
            .mixes
            .iter()
            .enumerate()
            .map(|(i, m)| CardItem { title: m.name.clone(), subtitle: m.desc.clone(), art: Art::Cover(m.hue, m.name.clone()), view: View::Mix(i) })
            .collect();
        let name = self.user.as_ref().map(|u| u.display_name.clone()).unwrap_or_default();
        self.shelf(ui, &format!("Made for {name}"), mixes, false);

        let mut recent_albums: Vec<String> = vec![];
        for id in &self.data.recent {
            if let Some(t) = self.track(id) {
                if !recent_albums.contains(&t.album) {
                    recent_albums.push(t.album.clone());
                }
            }
        }
        if !recent_albums.is_empty() {
            let items: Vec<CardItem> = recent_albums
                .iter()
                .filter_map(|n| self.albums.iter().find(|a| &a.name == n))
                .map(|a| CardItem { title: a.name.clone(), subtitle: a.artist.clone(), art: Art::Cover(a.hue, a.name.clone()), view: View::Album(a.name.clone()) })
                .collect();
            self.shelf(ui, "Recently played", items, false);
        }

        let items: Vec<CardItem> = self
            .albums
            .iter()
            .filter(|a| !a.local)
            .map(|a| CardItem { title: a.name.clone(), subtitle: a.artist.clone(), art: Art::Cover(a.hue, a.name.clone()), view: View::Album(a.name.clone()) })
            .collect();
        self.shelf(ui, "Albums to explore", items, true);

        let local: Vec<CardItem> = self
            .albums
            .iter()
            .filter(|a| a.local)
            .map(|a| CardItem { title: a.name.clone(), subtitle: a.artist.clone(), art: Art::Cover(a.hue, a.name.clone()), view: View::Album(a.name.clone()) })
            .collect();
        if !local.is_empty() {
            self.shelf(ui, "From your computer", local, true);
        }
    }

    fn quick_tile(&mut self, ui: &mut Ui, t: &CardItem, w: f32) {
        let (r, resp) = ui.allocate_exact_size(vec2(w, 64.0), Sense::click());
        let p = ui.painter().clone();
        p.rect_filled(r, cr(6), if resp.hovered() { Color32::from_white_alpha(40) } else { Color32::from_white_alpha(18) });
        let cvr = Rect::from_min_size(r.min, vec2(64.0, 64.0));
        draw_art(&p, cvr, &t.art);
        fit_text(&p, pos2(cvr.right() + 14.0, r.center().y), Align2::LEFT_CENTER, &t.title, bold(15.0), TEXT, w - 64.0 - 76.0);
        let ids = self.ids_for(&t.view);
        let playing_this = self.playing && !ids.is_empty() && self.context == ids;
        if resp.hovered() || playing_this {
            let c = pos2(r.right() - 32.0, r.center().y);
            let pr = Rect::from_center_size(c, vec2(40.0, 40.0));
            let presp = ui.interact(pr, Id::new(("qt_play", &t.title)), Sense::click());
            p.circle_filled(c, if presp.hovered() { 21.0 } else { 20.0 }, if presp.hovered() { ACCENT_HI } else { ACCENT });
            if playing_this {
                pause(&p, c, 14.0, BG);
            } else {
                play(&p, pos2(c.x + 1.0, c.y), 14.0, BG);
            }
            if presp.clicked() {
                self.pending.push(if playing_this { Action::TogglePlay } else { Action::PlayList(ids, 0) });
                return;
            }
        }
        if resp.clicked() {
            self.pending.push(Action::Go(t.view.clone()));
        }
    }

    fn shelf(&mut self, ui: &mut Ui, title: &str, items: Vec<CardItem>, wrap: bool) {
        if items.is_empty() {
            return;
        }
        ui.add_space(8.0);
        ui.label(RichText::new(title).font(bold(22.0)));
        ui.add_space(8.0);
        let w = ui.available_width();
        let gap = 12.0;
        let cols = (((w + gap) / (180.0 + gap)).floor() as usize).max(2);
        let cw = (w - gap * (cols as f32 - 1.0)) / cols as f32;
        let take = if wrap { items.len() } else { cols.min(items.len()) };
        for row in items[..take].chunks(cols) {
            ui.horizontal(|ui| {
                ui.spacing_mut().item_spacing.x = gap;
                for it in row {
                    self.card(ui, it, cw);
                }
            });
            ui.add_space(6.0);
        }
        ui.add_space(14.0);
    }

    fn card(&mut self, ui: &mut Ui, it: &CardItem, w: f32) {
        let h = w + 50.0;
        let (r, resp) = ui.allocate_exact_size(vec2(w, h), Sense::click());
        let p = ui.painter().clone();
        if resp.hovered() {
            p.rect_filled(r, cr(8), Color32::from_white_alpha(14));
        }
        let pad = 10.0;
        let cvr = Rect::from_min_size(r.min + vec2(pad, pad), vec2(w - 2.0 * pad, w - 2.0 * pad));
        p.rect_filled(cvr.translate(vec2(0.0, 4.0)), cr(6), Color32::from_black_alpha(60));
        draw_art(&p, cvr, &it.art);
        fit_text(&p, pos2(cvr.left(), cvr.bottom() + 10.0), Align2::LEFT_TOP, &it.title, bold(15.0), TEXT, cvr.width());
        fit_text(&p, pos2(cvr.left(), cvr.bottom() + 31.0), Align2::LEFT_TOP, &it.subtitle, reg(13.0), SUBTLE, cvr.width());
        if resp.hovered() {
            let c = pos2(cvr.right() - 28.0, cvr.bottom() - 28.0);
            let pr = Rect::from_center_size(c, vec2(46.0, 46.0));
            let presp = ui.interact(pr, Id::new(("card_play", &it.title)), Sense::click());
            p.circle_filled(c + vec2(0.0, 2.0), 23.0, Color32::from_black_alpha(90));
            p.circle_filled(c, 23.0, if presp.hovered() { ACCENT_HI } else { ACCENT });
            play(&p, pos2(c.x + 1.5, c.y), 16.0, BG);
            if presp.clicked() {
                let ids = self.ids_for(&it.view);
                self.pending.push(Action::PlayList(ids, 0));
                return;
            }
        }
        if resp.clicked() {
            self.pending.push(Action::Go(it.view.clone()));
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn collection_view(&mut self, ui: &mut Ui, kind: &str, title: String, sub: String, desc: String, art: Art, ids: Vec<String>, table: TableKind, playlist: Option<usize>) {
        let w = ui.available_width();
        let (hr, _) = ui.allocate_exact_size(vec2(w, 220.0), Sense::hover());
        let p = ui.painter().clone();
        let cv = Rect::from_min_size(pos2(hr.left(), hr.top() + 10.0), vec2(200.0, 200.0));
        p.rect_filled(cv.translate(vec2(0.0, 6.0)), cr(4), Color32::from_black_alpha(90));
        draw_art(&p, cv, &art);
        let tx = cv.right() + 24.0;
        let tw = hr.right() - tx;
        p.text(pos2(tx, cv.top() + 64.0), Align2::LEFT_BOTTOM, kind, bold(13.0), TEXT);
        let size = if title.chars().count() > 18 { 40.0 } else { 64.0 };
        fit_text(&p, pos2(tx - 2.0, cv.top() + 138.0), Align2::LEFT_BOTTOM, &title, bold(size), TEXT, tw);
        if !desc.is_empty() {
            fit_text(&p, pos2(tx, cv.top() + 168.0), Align2::LEFT_BOTTOM, &desc, reg(14.0), SUBTLE, tw);
        }
        fit_text(&p, pos2(tx, cv.bottom()), Align2::LEFT_BOTTOM, &sub, reg(14.0), TEXT, tw);
        if let Some(i) = playlist {
            let tr = Rect::from_min_max(pos2(tx, cv.top() + 70.0), pos2(hr.right(), cv.top() + 140.0));
            if ui.interact(tr, Id::new("pl_title"), Sense::click()).on_hover_text("Edit details").clicked() {
                self.pending.push(Action::EditPlaylist(i));
            }
        }

        ui.add_space(16.0);
        let (ar, _) = ui.allocate_exact_size(vec2(w, 64.0), Sense::hover());
        let c = pos2(ar.left() + 30.0, ar.center().y);
        let presp = ui.interact(Rect::from_center_size(c, vec2(58.0, 58.0)), Id::new("big_play"), Sense::click());
        let this_ctx = !ids.is_empty() && self.context == ids && self.current.is_some();
        p.circle_filled(c, if presp.hovered() { 30.0 } else { 28.0 }, if ids.is_empty() { FAINT } else if presp.hovered() { ACCENT_HI } else { ACCENT });
        if this_ctx && self.playing {
            pause(&p, c, 20.0, BG);
        } else {
            play(&p, pos2(c.x + 2.0, c.y), 20.0, BG);
        }
        if presp.clicked() && !ids.is_empty() {
            self.pending.push(if this_ctx { Action::TogglePlay } else { Action::PlayList(ids.clone(), 0) });
        }
        let sc = pos2(ar.left() + 90.0, ar.center().y);
        let sresp = ui.interact(Rect::from_center_size(sc, vec2(36.0, 36.0)), Id::new("big_shuffle"), Sense::click()).on_hover_text("Shuffle");
        shuffle(&p, sc, 26.0, if self.shuffle { ACCENT } else if sresp.hovered() { TEXT } else { SUBTLE });
        if self.shuffle {
            p.circle_filled(pos2(sc.x, sc.y + 18.0), 2.0, ACCENT);
        }
        if sresp.clicked() {
            self.pending.push(Action::ToggleShuffle);
        }
        if let Some(i) = playlist {
            let dc = pos2(ar.left() + 140.0, ar.center().y);
            let dresp = ui.interact(Rect::from_center_size(dc, vec2(36.0, 36.0)), Id::new("pl_more"), Sense::click()).on_hover_text("More options");
            dots(&p, dc, 26.0, if dresp.hovered() { TEXT } else { SUBTLE });
            let pid = Id::new("pl_more_popup");
            if dresp.clicked() {
                ui.memory_mut(|m| m.toggle_popup(pid));
            }
            egui::popup::popup_below_widget(ui, pid, &dresp, egui::PopupCloseBehavior::CloseOnClick, |ui| {
                ui.set_min_width(170.0);
                if ui.button("Edit details").clicked() {
                    self.pending.push(Action::EditPlaylist(i));
                }
                if ui.button("Add songs").clicked() {
                    self.pending.push(Action::Go(View::Search));
                }
                if ui.button("Delete playlist").clicked() {
                    self.pending.push(Action::DeletePlaylist(i));
                }
            });
        }
        ui.add_space(8.0);

        if ids.is_empty() {
            ui.add_space(30.0);
            ui.vertical_centered(|ui| {
                ui.label(RichText::new("Nothing here yet").font(bold(22.0)));
                ui.label(RichText::new("Find songs you love and add them here. Right-click any song for options.").color(SUBTLE));
                ui.add_space(10.0);
                if pill_button(ui, "Find songs", 140.0, 40.0, TEXT, BG).clicked() {
                    self.pending.push(Action::Go(View::Search));
                }
            });
            return;
        }
        self.track_table(ui, &ids, table, true);
    }

    fn track_table(&mut self, ui: &mut Ui, ids: &[String], kind: TableKind, show_album: bool) {
        let w = ui.available_width();
        let p = ui.painter().clone();
        let album_x = w * 0.52;
        let (hr, _) = ui.allocate_exact_size(vec2(w, 32.0), Sense::hover());
        p.text(pos2(hr.left() + 22.0, hr.center().y), Align2::CENTER_CENTER, "#", reg(13.0), SUBTLE);
        p.text(pos2(hr.left() + 52.0, hr.center().y), Align2::LEFT_CENTER, "Title", reg(13.0), SUBTLE);
        if show_album {
            p.text(pos2(hr.left() + album_x, hr.center().y), Align2::LEFT_CENTER, "Album", reg(13.0), SUBTLE);
        }
        p.text(pos2(hr.right() - 30.0, hr.center().y), Align2::RIGHT_CENTER, "Time", reg(13.0), SUBTLE);
        p.line_segment([pos2(hr.left(), hr.bottom()), pos2(hr.right(), hr.bottom())], Stroke::new(1.0, Color32::from_white_alpha(20)));
        ui.add_space(6.0);
        let time = ui.input(|i| i.time);
        let playlists: Vec<String> = self.data.playlists.iter().map(|p| p.name.clone()).collect();

        for (row, id) in ids.iter().enumerate() {
            let Some(t) = self.track(id).cloned() else { continue };
            let (r, resp) = ui.allocate_exact_size(vec2(w, 56.0), Sense::click());
            if !ui.is_rect_visible(r) {
                continue;
            }
            let is_cur = self.current.as_deref() == Some(id.as_str());
            let hovered = resp.hovered() || resp.context_menu_opened();
            if hovered {
                p.rect_filled(r, cr(6), Color32::from_white_alpha(16));
            }
            let nc = pos2(r.left() + 22.0, r.center().y);
            let num_resp = ui.interact(Rect::from_center_size(nc, vec2(32.0, 32.0)), Id::new(("row_play", row, id)), Sense::click());
            if hovered || num_resp.hovered() {
                if is_cur && self.playing {
                    pause(&p, nc, 14.0, TEXT);
                } else {
                    play(&p, nc, 14.0, TEXT);
                }
            } else if is_cur && self.playing {
                for k in 0..3 {
                    let hh = 4.0 + 10.0 * (0.5 + 0.5 * ((time * 6.0 + k as f64 * 1.7).sin() as f32));
                    p.rect_filled(Rect::from_center_size(pos2(nc.x - 5.0 + k as f32 * 5.0, nc.y + 7.0 - hh / 2.0), vec2(3.0, hh)), cr(1), ACCENT);
                }
            } else {
                p.text(nc, Align2::CENTER_CENTER, format!("{}", row + 1), reg(15.0), if is_cur { ACCENT } else { SUBTLE });
            }
            if num_resp.clicked() {
                self.pending.push(if is_cur { Action::TogglePlay } else { Action::PlayList(ids.to_vec(), row) });
            }
            let cvr = Rect::from_min_size(pos2(r.left() + 48.0, r.center().y - 20.0), vec2(40.0, 40.0));
            draw_art(&p, cvr, &Art::Cover(t.hue, t.album.clone()));
            let title_w = if show_album { album_x - 110.0 } else { w - 260.0 };
            fit_text(&p, pos2(cvr.right() + 12.0, r.center().y - 1.0), Align2::LEFT_BOTTOM, &t.title, reg(15.5), if is_cur { ACCENT } else { TEXT }, title_w);
            fit_text(&p, pos2(cvr.right() + 12.0, r.center().y + 2.0), Align2::LEFT_TOP, &t.artist, reg(13.5), SUBTLE, title_w);
            if show_album {
                fit_text(&p, pos2(r.left() + album_x, r.center().y), Align2::LEFT_CENTER, &t.album, reg(14.0), SUBTLE, w - album_x - 140.0);
            }
            let liked = self.data.liked.contains(id);
            let hc = pos2(r.right() - 100.0, r.center().y);
            let hresp = ui.interact(Rect::from_center_size(hc, vec2(28.0, 28.0)), Id::new(("row_like", row, id)), Sense::click());
            if liked {
                heart(&p, hc, 15.0, ACCENT, true);
            } else if hovered || hresp.hovered() {
                heart(&p, hc, 15.0, if hresp.hovered() { TEXT } else { SUBTLE }, false);
            }
            if hresp.clicked() {
                self.pending.push(Action::ToggleLike(id.clone()));
            }
            p.text(pos2(r.right() - 30.0, r.center().y), Align2::RIGHT_CENTER, fmt_time(t.duration), reg(14.0), SUBTLE);
            if resp.double_clicked() {
                self.pending.push(Action::PlayList(ids.to_vec(), row));
            }
            resp.context_menu(|ui| {
                ui.set_min_width(210.0);
                if ui.button("Play").clicked() {
                    self.pending.push(Action::PlayList(ids.to_vec(), row));
                    ui.close_menu();
                }
                if ui.button("Add to queue").clicked() {
                    self.pending.push(Action::Queue(id.clone()));
                    ui.close_menu();
                }
                let like_label = if liked { "Remove from Liked Songs" } else { "Save to Liked Songs" };
                if ui.button(like_label).clicked() {
                    self.pending.push(Action::ToggleLike(id.clone()));
                    ui.close_menu();
                }
                ui.menu_button("Add to playlist", |ui| {
                    if ui.button("+ New playlist").clicked() {
                        self.pending.push(Action::NewPlaylist(Some(id.clone())));
                        ui.close_menu();
                    }
                    if !playlists.is_empty() {
                        ui.separator();
                    }
                    for (pi, name) in playlists.iter().enumerate() {
                        if ui.button(name).clicked() {
                            self.pending.push(Action::AddToPlaylist(id.clone(), pi));
                            ui.close_menu();
                        }
                    }
                });
                if let TableKind::Playlist(pi) = kind {
                    if ui.button("Remove from this playlist").clicked() {
                        self.pending.push(Action::RemoveFromPlaylist(pi, row));
                        ui.close_menu();
                    }
                }
                ui.separator();
                if ui.button("Go to album").clicked() {
                    self.pending.push(Action::Go(View::Album(t.album.clone())));
                    ui.close_menu();
                }
            });
        }
    }

    fn search_view(&mut self, ui: &mut Ui) {
        let q = self.search.trim().to_lowercase();
        if q.is_empty() {
            ui.add_space(8.0);
            ui.label(RichText::new("Browse all").font(bold(24.0)));
            ui.add_space(12.0);
            let genres: [(&str, f32); 7] = [("Electronic", 0.74), ("Chill", 0.11), ("Lo-fi", 0.53), ("Ambient", 0.03), ("Dance", 0.9), ("Made for you", 0.35), ("Local files", 0.48)];
            let w = ui.available_width();
            let gap = 16.0;
            let cols = (((w + gap) / (220.0 + gap)).floor() as usize).max(2);
            let tw = (w - gap * (cols as f32 - 1.0)) / cols as f32;
            for row in genres.chunks(cols) {
                ui.horizontal(|ui| {
                    ui.spacing_mut().item_spacing.x = gap;
                    for (g, hue) in row {
                        let (r, resp) = ui.allocate_exact_size(vec2(tw, tw * 0.55), Sense::click());
                        let p = ui.painter().with_clip_rect(r);
                        p.rect_filled(r, cr(8), hsv(*hue, 0.6, if resp.hovered() { 0.75 } else { 0.62 }));
                        let art = Rect::from_min_size(pos2(r.right() - tw * 0.3, r.bottom() - tw * 0.26), vec2(tw * 0.32, tw * 0.32));
                        cover(&p, art, *hue + 0.05, g);
                        p.text(r.left_top() + vec2(16.0, 14.0), Align2::LEFT_TOP, *g, bold(22.0), TEXT);
                        if resp.clicked() {
                            if *g == "Made for you" {
                                self.pending.push(Action::Go(View::Mix(0)));
                            } else if *g == "Local files" {
                                self.pending.push(if self.data.local.is_empty() { Action::AddFolder } else { Action::Go(View::Local) });
                            } else {
                                self.search = g.to_string();
                            }
                        }
                    }
                });
                ui.add_space(gap - 6.0);
            }
            return;
        }

        let songs: Vec<String> = self
            .tracks
            .iter()
            .filter(|t| t.title.to_lowercase().contains(&q) || t.artist.to_lowercase().contains(&q) || t.album.to_lowercase().contains(&q) || t.genre.to_lowercase().contains(&q))
            .map(|t| t.id.clone())
            .collect();
        let albums: Vec<CardItem> = self
            .albums
            .iter()
            .filter(|a| a.name.to_lowercase().contains(&q) || a.artist.to_lowercase().contains(&q) || a.tracks.iter().any(|id| songs.contains(id)))
            .map(|a| CardItem { title: a.name.clone(), subtitle: a.artist.clone(), art: Art::Cover(a.hue, a.name.clone()), view: View::Album(a.name.clone()) })
            .collect();
        let pls: Vec<CardItem> = self
            .data
            .playlists
            .iter()
            .enumerate()
            .filter(|(_, p)| p.name.to_lowercase().contains(&q))
            .map(|(i, p)| CardItem { title: p.name.clone(), subtitle: format!("{} songs", p.tracks.len()), art: Art::Cover(p.hue, p.name.clone()), view: View::Playlist(i) })
            .collect();
        if songs.is_empty() && albums.is_empty() && pls.is_empty() {
            ui.add_space(60.0);
            ui.vertical_centered(|ui| {
                ui.label(RichText::new(format!("No results found for \"{}\"", self.search.trim())).font(bold(22.0)));
                ui.label(RichText::new("Check the spelling, or try different words.").color(SUBTLE));
            });
            return;
        }
        if !songs.is_empty() {
            ui.add_space(4.0);
            ui.label(RichText::new("Songs").font(bold(22.0)));
            ui.add_space(4.0);
            let shown: Vec<String> = songs.into_iter().take(40).collect();
            self.track_table(ui, &shown, TableKind::Plain, true);
            ui.add_space(16.0);
        }
        self.shelf(ui, "Albums", albums, true);
        self.shelf(ui, "Your playlists", pls, true);
    }

    fn library_view(&mut self, ui: &mut Ui) {
        ui.add_space(4.0);
        ui.label(RichText::new("Your Library").font(bold(30.0)));
        ui.add_space(10.0);
        ui.horizontal(|ui| {
            for (f, label) in [(LibFilter::All, "All"), (LibFilter::Playlists, "Playlists"), (LibFilter::Albums, "Albums"), (LibFilter::Local, "Local files")] {
                if chip(ui, label, self.lib_filter == f).clicked() {
                    self.lib_filter = f;
                }
            }
            ui.add_space(12.0);
            if chip(ui, "+ New playlist", false).clicked() {
                self.pending.push(Action::NewPlaylist(None));
            }
            if chip(ui, "+ Add music folder", false).clicked() {
                self.pending.push(Action::AddFolder);
            }
        });
        ui.add_space(14.0);

        let mut items: Vec<CardItem> = vec![];
        let f = self.lib_filter;
        if f == LibFilter::All || f == LibFilter::Playlists {
            items.push(CardItem { title: "Liked Songs".into(), subtitle: format!("{} songs", self.data.liked.len()), art: Art::Liked, view: View::Liked });
            for (i, p) in self.data.playlists.iter().enumerate() {
                items.push(CardItem { title: p.name.clone(), subtitle: format!("Playlist · {} songs", p.tracks.len()), art: Art::Cover(p.hue, p.name.clone()), view: View::Playlist(i) });
            }
        }
        if f == LibFilter::All || f == LibFilter::Local {
            if !self.data.local.is_empty() {
                items.push(CardItem { title: "Local files".into(), subtitle: format!("{} songs", self.data.local.len()), art: Art::Local, view: View::Local });
            }
            for a in self.albums.iter().filter(|a| a.local) {
                items.push(CardItem { title: a.name.clone(), subtitle: format!("Album · {}", a.artist), art: Art::Cover(a.hue, a.name.clone()), view: View::Album(a.name.clone()) });
            }
        }
        if f == LibFilter::All || f == LibFilter::Albums {
            for a in self.albums.iter().filter(|a| !a.local) {
                items.push(CardItem { title: a.name.clone(), subtitle: format!("Album · {}", a.artist), art: Art::Cover(a.hue, a.name.clone()), view: View::Album(a.name.clone()) });
            }
        }
        if f == LibFilter::Local && self.data.local.is_empty() {
            ui.add_space(30.0);
            ui.vertical_centered(|ui| {
                ui.label(RichText::new("Play music from your computer").font(bold(22.0)));
                ui.label(RichText::new("Pick a folder with MP3, FLAC, WAV, OGG or M4A files and it will show up here.").color(SUBTLE));
                ui.add_space(10.0);
                if pill_button(ui, "Choose a folder", 170.0, 40.0, TEXT, BG).clicked() {
                    self.pending.push(Action::AddFolder);
                }
            });
            return;
        }
        let w = ui.available_width();
        let gap = 12.0;
        let cols = (((w + gap) / (180.0 + gap)).floor() as usize).max(2);
        let cw = (w - gap * (cols as f32 - 1.0)) / cols as f32;
        for row in items.chunks(cols) {
            ui.horizontal(|ui| {
                ui.spacing_mut().item_spacing.x = gap;
                for it in row {
                    self.card(ui, it, cw);
                }
            });
            ui.add_space(6.0);
        }
    }

    fn local_view(&mut self, ui: &mut Ui) {
        let ids = self.ids_for(&View::Local);
        let sub = format!("{} songs on this computer", ids.len());
        self.collection_view(ui, "Folder", "Local files".into(), sub, String::new(), Art::Local, ids, TableKind::Plain, None);
        ui.add_space(20.0);
        ui.label(RichText::new("Music folders").font(bold(18.0)));
        let folders = self.data.folders.clone();
        for (i, f) in folders.iter().enumerate() {
            ui.horizontal(|ui| {
                ui.label(RichText::new(f.display().to_string()).color(SUBTLE));
                if ui.small_button("Rescan").clicked() {
                    self.pending.push(Action::RescanFolder(f.clone()));
                }
                if ui.small_button("Remove").clicked() {
                    self.pending.push(Action::RemoveFolder(i));
                }
            });
        }
        ui.add_space(6.0);
        if chip(ui, "+ Add another folder", false).clicked() {
            self.pending.push(Action::AddFolder);
        }
    }

    fn queue_view(&mut self, ui: &mut Ui) {
        ui.add_space(4.0);
        ui.label(RichText::new("Queue").font(bold(30.0)));
        ui.add_space(12.0);
        let Some(cur) = self.current.clone() else {
            ui.label(RichText::new("Nothing is playing yet. Pick a song to get started.").color(SUBTLE));
            return;
        };
        ui.label(RichText::new("Now playing").font(bold(17.0)).color(SUBTLE));
        self.track_table(ui, &[cur], TableKind::Plain, true);
        if !self.queue.is_empty() {
            ui.add_space(16.0);
            ui.horizontal(|ui| {
                ui.label(RichText::new("Next in queue").font(bold(17.0)).color(SUBTLE));
                if ui.small_button("Clear").clicked() {
                    self.queue.clear();
                }
            });
            let q: Vec<String> = self.queue.iter().cloned().collect();
            self.track_table(ui, &q, TableKind::Plain, true);
        }
        if !self.context.is_empty() {
            ui.add_space(16.0);
            ui.label(RichText::new(if self.shuffle { "Next up (shuffle is on)" } else { "Next up" }).font(bold(17.0)).color(SUBTLE));
            let upcoming: Vec<String> = self.context.iter().skip(self.ctx_pos + 1).take(30).cloned().collect();
            if upcoming.is_empty() {
                ui.label(RichText::new("End of the list.").color(SUBTLE));
            } else {
                self.track_table(ui, &upcoming, TableKind::Plain, true);
            }
        }
    }

    fn account_view(&mut self, ui: &mut Ui) {
        let Some(user) = self.user.clone() else { return };
        let w = ui.available_width();
        let (hr, _) = ui.allocate_exact_size(vec2(w, 210.0), Sense::hover());
        let p = ui.painter().clone();
        let ac = pos2(hr.left() + 96.0, hr.center().y);
        p.circle_filled(ac + vec2(0.0, 6.0), 92.0, Color32::from_black_alpha(80));
        p.circle_filled(ac, 92.0, hsv(library::hue_of(&user.username), 0.55, 0.9));
        let initial = user.display_name.chars().next().unwrap_or('?').to_uppercase().to_string();
        p.text(ac, Align2::CENTER_CENTER, initial, bold(78.0), BG);
        let tx = hr.left() + 220.0;
        p.text(pos2(tx, hr.center().y - 44.0), Align2::LEFT_BOTTOM, "Profile", bold(13.0), TEXT);
        fit_text(&p, pos2(tx, hr.center().y + 26.0), Align2::LEFT_BOTTOM, &user.display_name, bold(60.0), TEXT, hr.right() - tx);
        let meta = format!("@{} · {} playlists · {} liked songs · Member since {}", user.username, self.data.playlists.len(), self.data.liked.len(), member_since(user.created));
        fit_text(&p, pos2(tx, hr.center().y + 54.0), Align2::LEFT_BOTTOM, &meta, reg(14.0), SUBTLE, hr.right() - tx);
        ui.add_space(20.0);

        let box_w = (w - 16.0) / 2.0;
        ui.horizontal_top(|ui| {
            ui.spacing_mut().item_spacing.x = 16.0;
            section_box(ui, box_w, |ui| {
                ui.label(RichText::new("Your plan").font(bold(18.0)));
                ui.add_space(4.0);
                ui.label(RichText::new("Free forever · Ad-free").font(bold(24.0)).color(ACCENT));
                ui.add_space(4.0);
                for line in ["No ads between songs, ever", "Unlimited skips", "Play your own music files", "Unlimited playlists"] {
                    ui.horizontal(|ui| {
                        ui.label(RichText::new("✓").color(ACCENT));
                        ui.label(RichText::new(line).color(SUBTLE));
                    });
                }
            });
            section_box(ui, box_w, |ui| {
                ui.label(RichText::new("Edit profile").font(bold(18.0)));
                ui.add_space(4.0);
                field_label(ui, "Display name");
                ui.add(text_field(&mut self.acct_name, "Your name", false, box_w - 40.0));
                ui.add_space(8.0);
                if pill_button(ui, "Save name", 130.0, 36.0, TEXT, BG).clicked() {
                    let n = self.acct_name.trim().to_string();
                    if n.is_empty() {
                        self.acct_msg = Some(("Name can't be empty.".into(), false));
                    } else {
                        self.accounts.rename(&user.username, &n);
                        self.save_accounts();
                        if let Some(u) = &mut self.user {
                            u.display_name = n;
                        }
                        self.acct_msg = Some(("Name saved.".into(), true));
                    }
                }
            });
        });
        ui.add_space(16.0);
        ui.horizontal_top(|ui| {
            ui.spacing_mut().item_spacing.x = 16.0;
            section_box(ui, box_w, |ui| {
                ui.label(RichText::new("Change password").font(bold(18.0)));
                ui.add_space(4.0);
                field_label(ui, "Current password");
                ui.add(text_field(&mut self.acct_old, "", true, box_w - 40.0));
                field_label(ui, "New password");
                ui.add(text_field(&mut self.acct_new, "At least 6 characters", true, box_w - 40.0));
                ui.add_space(8.0);
                if pill_button(ui, "Update password", 160.0, 36.0, TEXT, BG).clicked() {
                    match self.accounts.change_password(&user.username, &self.acct_old, &self.acct_new) {
                        Ok(()) => {
                            self.save_accounts();
                            self.acct_old.clear();
                            self.acct_new.clear();
                            self.acct_msg = Some(("Password updated.".into(), true));
                        }
                        Err(e) => self.acct_msg = Some((e, false)),
                    }
                }
            });
            section_box(ui, box_w, |ui| {
                ui.label(RichText::new("Session").font(bold(18.0)));
                ui.add_space(4.0);
                ui.label(RichText::new("Sign out of this computer. Your playlists and likes stay saved with your account.").color(SUBTLE));
                ui.add_space(8.0);
                if pill_button(ui, "Sign out", 120.0, 36.0, TEXT, BG).clicked() {
                    self.pending.push(Action::SignOut);
                }
                ui.add_space(14.0);
                let red = Color32::from_rgb(255, 110, 110);
                if !self.confirm_delete {
                    if ui.add(egui::Button::new(RichText::new("Delete account").color(red)).frame(false)).clicked() {
                        self.confirm_delete = true;
                    }
                } else {
                    ui.label(RichText::new("This removes your account, playlists and likes from this computer.").color(red));
                    ui.horizontal(|ui| {
                        if ui.button(RichText::new("Yes, delete it").color(red)).clicked() {
                            self.accounts.delete(&user.username);
                            if !self.ephemeral {
                                UserData::delete(&self.data_dir, &user.username);
                            }
                            self.save_accounts();
                            self.pending.push(Action::SignOut);
                        }
                        if ui.button("Cancel").clicked() {
                            self.confirm_delete = false;
                        }
                    });
                }
            });
        });
        if let Some((m, ok)) = &self.acct_msg {
            ui.add_space(10.0);
            ui.label(RichText::new(m).color(if *ok { ACCENT } else { Color32::from_rgb(255, 110, 110) }));
        }
    }
