    let c1 = hsv(hue, 0.6, 0.85);
    let c2 = hsv(hue + 0.08, 0.75, 0.5);
    let c3 = hsv(hue - 0.06, 0.75, 0.28);
    gradient4(&p, r, c1, c2, c2, c3);
