use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::path::Path;

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Account {
    pub username: String,
    pub display_name: String,
    pub salt: String,
    pub hash: String,
    pub created: u64,
}

#[derive(Clone, Debug, Serialize, Deserialize, Default)]
pub struct AccountStore {
    pub accounts: Vec<Account>,
    pub remembered: Option<String>,
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

fn hash_password(salt: &str, password: &str) -> String {
    let mut digest: Vec<u8> = Sha256::digest(format!("{salt}:{password}").as_bytes()).to_vec();
    for _ in 0..20_000 {
        let mut h = Sha256::new();
        h.update(salt.as_bytes());
        h.update(&digest);
        digest = h.finalize().to_vec();
    }
    hex(&digest)
}

fn now_secs() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0)
}

pub fn normalize(username: &str) -> String {
    username.trim().to_lowercase()
}

impl AccountStore {
    pub fn load(dir: &Path) -> Self {
        std::fs::read_to_string(dir.join("accounts.json"))
            .ok()
            .and_then(|s| serde_json::from_str(&s).ok())
            .unwrap_or_default()
    }

    pub fn save(&self, dir: &Path) {
        let _ = std::fs::create_dir_all(dir);
        if let Ok(s) = serde_json::to_string_pretty(self) {
            let _ = std::fs::write(dir.join("accounts.json"), s);
        }
    }

    pub fn find(&self, username: &str) -> Option<&Account> {
        let u = normalize(username);
        self.accounts.iter().find(|a| a.username == u)
    }

    pub fn sign_up(&mut self, username: &str, display: &str, password: &str, confirm: &str) -> Result<Account, String> {
        let u = normalize(username);
        if u.len() < 3 {
            return Err("Username needs at least 3 characters.".into());
        }
        if !u.chars().all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '.' || c == '-') {
            return Err("Username can only use letters, numbers, dots, dashes and underscores.".into());
        }
        if self.find(&u).is_some() {
            return Err("That username is already taken.".into());
        }
        if password.chars().count() < 6 {
            return Err("Password needs at least 6 characters.".into());
        }
        if password != confirm {
            return Err("The two passwords don't match.".into());
        }
        let salt: String = hex(&(0..16).map(|_| fastrand::u8(..)).collect::<Vec<_>>());
        let display = if display.trim().is_empty() { username.trim().to_string() } else { display.trim().to_string() };
        let acc = Account {
            username: u,
            display_name: display,
            hash: hash_password(&salt, password),
            salt,
            created: now_secs(),
        };
        self.accounts.push(acc.clone());
        Ok(acc)
    }

    pub fn sign_in(&self, username: &str, password: &str) -> Result<Account, String> {
        match self.find(username) {
            None => Err("No account with that username.".into()),
            Some(a) if hash_password(&a.salt, password) == a.hash => Ok(a.clone()),
            Some(_) => Err("Wrong password. Try again.".into()),
        }
    }

    pub fn rename(&mut self, username: &str, display: &str) {
        if let Some(a) = self.accounts.iter_mut().find(|a| a.username == username) {
            a.display_name = display.trim().to_string();
        }
    }

    pub fn change_password(&mut self, username: &str, old: &str, new: &str) -> Result<(), String> {
        let Some(a) = self.accounts.iter_mut().find(|a| a.username == username) else {
            return Err("Account not found.".into());
        };
        if hash_password(&a.salt, old) != a.hash {
            return Err("Current password is wrong.".into());
        }
        if new.chars().count() < 6 {
            return Err("New password needs at least 6 characters.".into());
        }
        a.hash = hash_password(&a.salt, new);
        Ok(())
    }

    pub fn delete(&mut self, username: &str) {
        self.accounts.retain(|a| a.username != username);
        if self.remembered.as_deref() == Some(username) {
            self.remembered = None;
        }
    }
}

pub fn member_since(secs: u64) -> String {
    // Civil-from-days (Howard Hinnant), good enough for a "member since" line.
    let days = (secs / 86_400) as i64;
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = if m <= 2 { y + 1 } else { y };
    let names = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
    format!("{} {}", names[(m - 1) as usize], y)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn sign_up_and_sign_in() {
        let mut s = AccountStore::default();
        assert!(s.sign_up("ab", "", "secret1", "secret1").is_err(), "short username");
        assert!(s.sign_up("sam", "", "123", "123").is_err(), "short password");
        assert!(s.sign_up("sam", "", "secret1", "secret2").is_err(), "mismatch");
        let a = s.sign_up("Sam", "Sam Lee", "secret1", "secret1").unwrap();
        assert_eq!(a.username, "sam");
        assert!(s.sign_up("SAM", "", "secret1", "secret1").is_err(), "duplicate");
        assert!(s.sign_in("sam", "wrong").is_err());
        assert!(s.sign_in("nobody", "secret1").is_err());
        assert_eq!(s.sign_in(" SAM ", "secret1").unwrap().display_name, "Sam Lee");
        assert!(!a.hash.contains("secret1"));
        s.change_password("sam", "secret1", "newpass").unwrap();
        assert!(s.sign_in("sam", "secret1").is_err());
        assert!(s.sign_in("sam", "newpass").is_ok());
        s.delete("sam");
        assert!(s.sign_in("sam", "newpass").is_err());
    }
}

