                ScrollArea::vertical().id_salt(key).auto_shrink([false, false]).show(ui, |ui| {
                    Frame::new().inner_margin(Margin { left: 14, right: 14, top: 0, bottom: 24 }).show(ui, |ui| {
                        ui.set_width(ui.available_width());
                        self.view_content(ui);
