//! Real music from Jamendo (free, full-length, Creative Commons songs).
//! The person pastes their own free key ("Client ID" from devportal.jamendo.com).

use serde::{Deserialize, Serialize};
use std::path::Path;

pub const KEY_SITE: &str = "https://devportal.jamendo.com/";
const API: &str = "https://api.jamendo.com/v3.0/tracks/";

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct OnlineTrack {
    pub id: String,
    pub title: String,
    pub artist: String,
    pub album: String,
    pub duration: f32,
    pub audio: String,
}

impl OnlineTrack {
    pub fn track_id(&self) -> String {
        format!("jam:{}", self.id)
    }
}

