def patch(path, pairs):
    p = root + path
    s = open(p, encoding='utf-8').read()
    for old, new in pairs:
        if old not in s:
            print('MISSING in', path, ':', old[:90])
            sys.exit(1)
        s = s.replace(old, new, 1)
    open(p, 'w', encoding='utf-8').write(s)


