     '''//! Real music from the internet:
//! - Deezer's public catalogue (no key): every well-known song, with cover art and a 30-second preview.
//! - Jamendo (free key from devportal.jamendo.com): full-length Creative Commons songs.'''),
    ('''    pub duration: f32,
    pub audio: String,
}

impl OnlineTrack {
